(window.WCD=window.WCD||[]).push(["chanteurs_int",[["Q6060",1,"chanteur","50 Cent","R","50 Cent, de son vrai nom Curtis Jackson, est un rappeur, chanteur, producteur de musique, acteur, compositeur et homme d'affaires américain né le 6 juillet 1975 dans le Queens, à New York. Jackson se lance dans la vente de drogues à l'âge de dix ans, puis dans une carrière musicale en 2000, période durant laquelle il est blessé par balle. Après la publication de sa compilation Guess Who's Back? en 2002, 50 Cent est découvert par Eminem et signe sur Shady Records, Aftermath Entertainment et Interscope Records.",118,"fr:50_Cent","c:0/0c/Curtis_%2250_Cent%22_Jackson_visits_Barksdale_AFB_%285%29_%28cropped%29.jpg"],["Q219631",2,"chanteur","Adam Levine","R","Adam Levine, né le 18 mars 1979 à Los Angeles, est un chanteur, guitariste et acteur américain. Il est le leader du groupe de pop rock Maroon 5.","Adam Levine, né le 18 mars 1979 à Los Angeles, est un chanteur, guitariste et acteur américain.","fr:Adam_Levine","c:b/b1/Maroon_5_11_19_2016_-58_%2831101308922%29_%28cropped%29.jpg"],["Q23215",3,"chanteur","Adele","R","Adele Laurie Blue Adkins, née le 5 mai 1988 dans le quartier londonien de Tottenham, en Angleterre, mieux connue sous le nom de scène Adele est une auteure-compositrice-interprète britannique. En 2008, elle sort son premier album intitulé 19 qui se vend à plus de 8,5 millions d'exemplaires. Elle est la première à recevoir le prix Critics' Choice des Brit Awards. Elle est élue par un panel de critiques musicales comme la meilleure artiste émergente du Sound of 2008 de la BBC.",117,"fr:Adele","c:e/ef/Adele_in_Munich.jpg"],["Q104012678",4,"chanteur","Ado","C","Ado, née le 24 octobre 2002 à Tokyo, est une chanteuse japonaise. En 2020, à l'âge de 17 ans, elle fait ses débuts avec le single numérique Usseewa. Ce single a atteint la première place des classements Japan Hot 100, classement des singles Oricon et Oricon Streaming Chart et obtient plus de 100 millions d'écoutes d'après le magazine Billboard Japan, après avoir passé dix-sept semaines dans le classement de ce dernier. Soit le sixième titre à atteindre ce score le plus rapidement dans l'histoire.","Ado, née le 24 octobre 2002 à Tokyo, est une chanteuse japonaise.","fr:Ado_(chanteuse)",""],["Q199943",5,"chanteur","Adriano Celentano","C","Adriano Celentano, né le 6 janvier 1938 à Milan, est un auteur-compositeur-interprète, chanteur, acteur, réalisateur, scénariste et présentateur italien. En Italie, il est surnommé « Il Molleggiato » ou « L'Urlatore ». Artiste majeur de la chanson italienne, il a vendu plus de deux cents millions de disques dans le monde.",117,"fr:Adriano_Celentano","c:8/8c/Rugantino_1973_12.png"],["Q173144",6,"chanteur","Agnetha Fältskog","PC","Åse Agneta Fältskog, dite Agnetha Fältskog, née le 5 avril 1950 à Jönköping, est une chanteuse, auteure-compositrice-interprète, pianiste et productrice suédoise, et membre du groupe pop suédois ABBA.",95,"fr:Agnetha_Fältskog","c:0/04/Agnetha_F%C3%A4ltskog_2013-07-22_002_%28cropped%29.jpg"],["Q32849",7,"chanteur","Akon","C","Akon, de son vrai nom Aliaune Damala Bouga Time Puru Nacka Lu Lu Lu Badara Akon Thiam, né le 16 avril 1973 à Saint-Louis, est un chanteur et producteur de RnB américano-sénégalais. Son premier single Locked Up et son premier album Trouble sont sortis en 2004. Son deuxième album, Konvicted, a gagné une nomination au Grammy Award pour son single Smack That. Il a fondé le label Konvict Muzik.",108,"fr:Akon","c:8/80/Akon_DF2_4639_%2847859034612%29_%28cropped%29.jpg"],["Q130742",8,"chanteur","Alanis Morissette","PC","Alanis Morissette, née le 1er juin 1974 à Ottawa, est une chanteuse contemporaine canadienne.",null,"fr:Alanis_Morissette","c:5/50/Glasto_2025_%2846%29_-_Alanis_Morissette_%28cropped%29.jpg"],["Q332032",9,"chanteur","Alice Cooper","R","Alice Cooper, nom de scène puis nouveau nom légal de Vincent Damon Furnier, né le 4 février 1948 à Détroit, est un chanteur et auteur-compositeur-interprète américain de hard rock, dont la carrière s'étend sur plus de cinq décennies. Son attitude et son apparence, ainsi que ses mises en scène incluant entre autres guillotines, chaises électriques, faux sang, serpents, poupées et sabres ainsi que plusieurs figurants – notamment une infirmière sadique incarnée d'abord par Sheryl Cooper, son épouse, puis plus tard…",114,"fr:Alice_Cooper","c:0/0e/Alice_Cooper_Photo_Op_GalaxyCon_Richmond_2019.jpg"],["Q121507",10,"chanteur","Alicia Keys","PC","Alicia Augello Cook, dite Alicia Keys, est une pianiste, chanteuse, claviériste, auteure-compositrice-interprète, actrice et productrice américaine, née le 25 janvier 1981 dans le quartier de Hell's Kitchen, à New York.",113,"fr:Alicia_Keys","c:f/f1/AliciaKeys-byPhilipRomano2.jpg"],["Q80510",11,"chanteur","Alla Pougatcheva","C","Alla Borissovna Pougatcheva, née le 15 avril 1949 à Moscou, est une chanteuse et actrice russe extrêmement populaire en Russie et dans les pays de l'ancien bloc soviétique, comme l'atteste la vente de ses disques et le nombre d'émissions qui lui sont consacrées à la télévision russe.",119,"fr:Alla_Pougatcheva","c:7/74/Alla_Pugacheva_on_Slavianski_Bazaar_in_Vitebsk_01_%28cropped%29.jpg"],["Q108560",12,"chanteur","Allah Rakha Rahman","C","Allah Rakha Rahman, ou simplement A. R. Rahman, est un auteur-compositeur-interprète, producteur et philanthrope indien, né le 6 janvier 1967 à Chennai.","Allah Rakha Rahman, ou simplement A.","fr:Allah_Rakha_Rahman","c:f/f7/AR_Rahman_At_The_%E2%80%98Marvel_Anthem%E2%80%99_Launch.jpg"],["Q172632",13,"chanteur","Amy Lee","C","Amy Lee, née Amy Lynn Lee le 13 décembre 1981 à Riverside, en Californie, aux, est une chanteuse, autrice-compositrice-interprète et musicienne américaine.",97,"fr:Amy_Lee","c:6/65/Evanescence_at_The_Wiltern_theatre_in_Los_Angeles%2C_California_04_%28cropped%29.jpg",{"cats":["chanteurs_int","groupes"]}],["Q15897",14,"chanteur","Amy Winehouse","L","Amy Winehouse, née le 14 septembre 1983 à Londres et morte le 23 juillet 2011 dans cette même ville, est une chanteuse, auteure-compositrice-interprète et guitariste britannique, connue pour sa voix caractéristique rappelant celles de Dinah Washington, Sarah Vaughan ou encore Wanda Jackson. D'une manière générale, sa musique est un mélange de styles comme le jazz, le blues ou encore la soul.",119,"fr:Amy_Winehouse","c:0/02/Amy_Winehouse_in_2008.jpg"],["Q42402",15,"chanteur","Andrea Bocelli","C","Andrea Bocelli, né le 22 septembre 1958 à Lajatico, est un chanteur et ténor italien d'inspiration lyrique.",null,"fr:Andrea_Bocelli","c:3/35/Andrea_Bocelli_20190511_017-2_%28cropped%29.jpg"],["Q201908",16,"chanteur","Anni-Frid Lyngstad","C","Anni-Frid Lyngstad, surnommée « Frida », princesse Reuss et comtesse de Plauen par son troisième mariage, née le 15 novembre 1945 à Bjørkåsen près de Narvik en Norvège, est une chanteuse norvégienne. Elle est membre du groupe pop suédois ABBA.",115,"fr:Anni-Frid_Lyngstad","c:6/6f/Anni-Frid_Lyngstad%2C_May_2013.jpg"],["Q151231",17,"chanteur","Annie Lennox","C","Annie Lennox, de son vrai nom Ann Lennox, née le 25 décembre 1954 à Aberdeen, est une auteure-compositrice-interprète britannique.",117,"fr:Annie_Lennox","c:0/01/Annie_Lennox_March_2023.jpg"],["Q125121",18,"chanteur","Aretha Franklin","PC","Aretha Louise Franklin, née le 25 mars 1942 à Memphis et morte le 16 août 2018 à Détroit, est une chanteuse, pianiste et autrice-compositrice américaine de soul, jazz, gospel et rhythm and blues. Elle est surnommée « The Queen Of Soul ».",117,"fr:Aretha_Franklin","c:c/c6/Aretha_Franklin_1968.jpg"],["Q151892",19,"chanteur","Ariana Grande","E","Ariana Grande-Butera, surtout connue sous le nom d'Ariana Grande, née le 26 juin 1993 à Boca Raton, en Floride, est une auteure-compositrice-interprète, actrice et productrice de musique américaine.",119,"fr:Ariana_Grande","c:9/99/Ariana_Grande_Eternal_Sunshine_Tour_performing_%28cropped%29.jpg"],["Q30449",20,"chanteur","Avril Lavigne","R","Avril Lavigne, née le 27 septembre 1984 à Belleville, est une auteure-compositrice-interprète pop rock, musicienne, actrice et styliste franco-canadienne.",115,"fr:Avril_Lavigne","c:1/13/Avril_Lavigne_%40_Grammy_Museum_09_05_2019_%2849311430057%29.jpg"],["Q11885",21,"chanteur","Axl Rose","C","Axl Rose, né William Bruce Rose, Jr. le 6 février 1962 à Lafayette, est un musicien américain, connu pour être le chanteur et compositeur du groupe de hard rock américain Guns N' Roses. Il en est l'un des membres emblématiques, avec Slash, Duff McKagan, Izzy Stradlin et Steven Adler. En 2016, il rejoint provisoirement AC/DC pour remplacer Brian Johnson forcé au repos.","Axl Rose, né William Bruce Rose, Jr.","fr:Axl_Rose","c:1/1c/GNR_London_Stadium_2017_7.jpg",{"cats":["chanteurs_int","groupes"]}],["Q188111",22,"chanteur","Ayumi Hamasaki","C","Ayumi Hamasaki née le 2 octobre 1978 à Fukuoka, est une auteure-chanteuse japonaise. Surnommée « la reine de la J-pop » en raison de sa popularité et de son influence au Japon ainsi qu'en Asie, elle est reconnue notamment pour ses textes et considérée comme une icône culturelle de l'ère Heisei.","Ayumi Hamasaki née le 2 octobre 1978 à Fukuoka, est une auteure-chanteuse japonaise.","fr:Ayumi_Hamasaki","c:5/5c/Ayumi_Hamasaki_%E6%B5%9C%E5%B4%8E%E3%81%82%E3%82%86%E3%81%BF_%282024%29.png"],["Q44333953",23,"chanteur","Bad Bunny","PC","Bad Bunny, de son vrai nom Benito Martínez Ocasio, né le 10 mars 1994 à Bayamón, est un rappeur, chanteur, producteur, acteur et catcheur portoricain.",118,"fr:Bad_Bunny","c:d/d9/Bad_Bunny_performing_at_Est%C3%A1dio_Da_Luz%2C_Lisbon%2C_27_May_2026.jpg"],["Q4636",24,"chanteur","Barbra Streisand","R","Barbara Streisand, dite Barbra Streisand /ˈbɑɹbɹə ˈstraɪsænd/, est une chanteuse, actrice, réalisatrice et productrice américaine, née le 24 avril 1942 à New York.",118,"fr:Barbra_Streisand","c:4/44/Barbra_Streisand_with_Francis_Collins_and_Anthony_Fauci_%2827806589237%29_%28cropped%29.jpg"],["Q16185856",25,"chanteur","Bebe Rexha","C","Bleta Rexha, dite Bebe Rexha, née le 30 août 1989 à Brooklyn, est une auteure-compositrice-interprète, chanteuse et productrice américaine d'origine de Macédoine du nord.",115,"fr:Bebe_Rexha","c:0/0f/Bebe_Rexha_-_Untold_2023_-_53113724212_%28cropped%29.jpg"],["Q214582",26,"chanteur","Benny Andersson","C","Benny Bror Göran Andersson, né le 16 décembre 1946 à Stockholm, est un musicien et compositeur suédois. Il est connu pour être un membre du groupe ABBA.","Benny Bror Göran Andersson, né le 16 décembre 1946 à Stockholm, est un musicien et compositeur suédois.","fr:Benny_Andersson","c:a/a4/Benny_Andersson_at_The_Eddy_Go_Round_Show_1975.png"],["Q110008128",27,"chanteur","Benson Boone","C","Benson Boone est un chanteur et auteur-compositeur-interprète américain, né le 25 juin 2002 à Monroe dans l'État de Washington.",115,"fr:Benson_Boone","c:1/11/Benson_Boone_Press_Copy_Warner_Records_%28cropped%29.png"],["Q190631",28,"chanteur","Bette Midler","PC","Bette Midler, née le 1er décembre 1945 à Honolulu, à Hawaï, est une actrice, chanteuse et humoriste américaine.",null,"fr:Bette_Midler","c:b/b4/Bette_Midler_2021_Kennedy_Center_Honors_%28cropped%29.jpg"],["Q36153",29,"chanteur","Beyoncé","R","Beyoncé, parfois appelée par son nom complet Beyoncé Giselle Knowles, voire par son nom d'épouse Beyoncé Carter, est une chanteuse, rappeuse, autrice-compositrice-interprète, danseuse, productrice, actrice et femme d'affaires américaine.",116,"fr:Beyoncé","c:6/62/HSnE5IOWkAA1R8q.jpg"],["Q29564107",30,"chanteur","Billie Eilish","R","Billie Eilish, née le 18 décembre 2001 à Los Angeles, est une auteure-compositrice-interprète et actrice américaine.",null,"fr:Billie_Eilish","c:3/3f/BillieEilishO2140725-66_-_54666402736_%28cropped%29.jpg"],["Q104358",31,"chanteur","Billie Holiday","C","Billie Holiday, aussi surnommée Lady Day, née Eleanora Fagan à Philadelphie en Pennsylvanie le 7 avril 1915 et morte à New York le 17 juillet 1959, est l'une des plus grandes chanteuses américaines de blues et de jazz. Consacrée par Strange Fruit, la carrière de Billie Holiday est marquée par son engagement pour les droits civiques et ses addictions à la drogue et à l'alcool. Avec Ella Fitzgerald, Nina Simone et Sarah Vaughan, elle est l'une des principales représentantes du jazz vocal.",118,"fr:Billie_Holiday","c:b/bf/Portrait_of_Billie_Holiday_and_Mister%2C_Downbeat%2C_New_York%2C_N.Y.%2C_ca._Feb._1947_%28LOC%2C_5020400274%2C_cropped%29.jpg"],["Q712592",32,"chanteur","Billie Joe Armstrong","C","Billie Joe Armstrong, né le 17 février 1972 à Oakland en Californie, est un chanteur, guitariste, auteur-compositeur-interprète, producteur et comédien américain. Il est le leader du groupe punk rock Green Day. Il joue également du piano, de la basse, de la batterie, de l'harmonica et du saxophone.",97,"fr:Billie_Joe_Armstrong","c:4/4f/RiP2013_GreenDay_Billie_Joe_Armstrong_0021.jpg",{"cats":["chanteurs_int","groupes"]}],["Q194333",33,"chanteur","Billy Joel","R","William Martin Joel, plus connu sous le nom de Billy Joel, né le 9 mai 1949 dans le quartier du Bronx à New York, est un chanteur, pianiste et auteur-compositeur américain. Il démarre dans la pop music en 1971 avec le disque Cold Spring Harbor. Musicien de talent, il a gagné six Grammy Award durant sa carrière, mise entre parenthèses depuis 1993.",117,"fr:Billy_Joel","c:1/19/Billy_Joel_Shankbone_NYC_2009.jpg"],["Q72984",34,"chanteur","Bing Crosby","C","Bing Crosby, de son vrai nom Harry Lillis Crosby Jr., né le 3 mai 1903 à Tacoma et mort le 14 octobre 1977 à Alcobendas près de Madrid, est un chanteur et acteur américain. Il est l'une des icônes culturelles majeures du XXe siècle.",119,"fr:Bing_Crosby","c:e/e5/Bing_Crosby_Paramount_Pictures.jpg"],["Q42455",35,"chanteur","Björk","PC","Björk, mononyme de Björk Guðmundsdóttir, est une musicienne, chanteuse, autrice-compositrice-interprète, productrice et actrice islandaise, née le 21 novembre 1965 à Reykjavik.",119,"fr:Björk","c:0/0f/Bjork_Orkestral_Paris_%28cropped%29.png"],["Q179682",36,"chanteur","Björn Ulvaeus","C","Björn Kristian Ulvaeus, parfois orthographié Ulvæus, né le 25 avril 1945 à Göteborg, est un guitariste, chanteur, compositeur de chansons, parolier et producteur suédois. Président de la CISAC depuis 2020, il est connu pour avoir été un membre des groupes suédois Hootenanny Singers et surtout ABBA.",113,"fr:Björn_Ulvaeus","c:3/30/Bj%C3%B6rn_Ulvaeus_2023_%2853338026438%29_%28cropped%29.jpg"],["Q392",37,"chanteur","Bob Dylan","E","Bob Dylan, né Robert Zimmermann, est un auteur-compositeur-interprète, musicien, peintre, sculpteur, cinéaste et poète américain, né le 24 mai 1941 à Duluth, dans le Minnesota. Il est l'une des figures majeures de la musique populaire mondiale.",118,"fr:Bob_Dylan","c:4/4e/Bob_Dylan_1984_Barcelona.jpg"],["Q216608",38,"chanteur","Bob Geldof","C","Robert Frederick Zenon Geldof, dit Bob Geldof est un auteur-compositeur-interprète, acteur, musicien et militant politique irlandais. Né le 5 octobre 1951, à Dún Laoghaire dans le comté de Dublin, il est d'abord le chanteur des Boomtown Rats, puis le co-organisateur avec Midge Ure du Live Aid en 1985 et de plusieurs concerts de charité; son activisme est reconnu notamment dans la lutte contre la pauvreté en Afrique.",112,"fr:Bob_Geldof","c:d/d7/BobGeldof2014_1.jpg"],["Q409",39,"chanteur","Bob Marley","R","Bob Marley, né Robert Marley le 6 février 1945 à Nine Miles en Jamaïque et mort le 11 mai 1981 à Miami, est un chanteur de reggae et musicien Jamaïcain. Il rencontre de son vivant un succès mondial, et reste le musicien le plus connu du reggae, tout en étant considéré comme celui qui a permis à la musique jamaïcaine et au mouvement rastafari de connaître une audience planétaire. Il a vendu plus de 200 millions de disques à travers le monde.",119,"fr:Bob_Marley","c:d/d6/Bob_Marley_circa_1976_%28cropped%29.jpg"],["Q204162",40,"chanteur","Bon Scott","C","Ronald Scott, dit Bon Scott, né le 9 juillet 1946 à Forfar, en Écosse, et mort le 19 février 1980 à Londres, en Angleterre, est un chanteur britannico-australien.",111,"fr:Bon_Scott","c:9/9f/Grenoble79_01_%28cropped%29.jpg",{"cats":["chanteurs_int","groupes"]}],["Q156491",41,"chanteur","Bonnie Tyler","C","Bonnie Tyler est une chanteuse britannique, née le 8 juin 1951 à Skewen et morte le 8 juillet 2026 à Faro.",null,"fr:Bonnie_Tyler","c:4/47/Bonnie_Tyler_in_Moscow_2011.jpg"],["Q834621",42,"chanteur","Bono","PC","Bono, pseudonyme de Paul David Hewson, né le 10 mai 1960 à Dublin, est un auteur-compositeur-interprète, musicien, homme d'affaires et philanthrope irlandais.",114,"fr:Bono_(chanteur)","c:9/94/Bono_singing_in_Indianapolis_on_Joshua_Tree_Tour_2017_9-10-17.jpg"],["Q569003",43,"chanteur","Brian Eno","C","Brian Eno, nom de scène de Brian Peter George St. John le Baptiste de la Salle Eno, né plus simplement Brian Peter George Eno le 15 mai 1948 à Woodbridge, est un musicien, arrangeur et producteur britannique. Eno s'est décrit comme un « non-musicien » et a contribué à introduire une variété d'approches conceptuelles et de techniques d'enregistrement dans la musique contemporaine, prônant une méthodologie de « la théorie sur la pratique, la sérendipité sur la prévoyance et la texture sur l'artisanat » selon…","Brian Eno, nom de scène de Brian Peter George St.","fr:Brian_Eno","c:7/75/Brian_Eno_II_%28Prague%2C_2017%29.jpg"],["Q15873",44,"chanteur","Brian May","PC","Brian May, né le 19 juillet 1947 à Hampton Hill, au sud-ouest de Londres, est un musicien, chanteur, auteur-compositeur et astrophysicien britannique, cofondateur et guitariste du groupe de rock Queen avec le batteur Roger Taylor et le chanteur Freddie Mercury. Ils sont ensuite rejoints par le bassiste John Deacon.",119,"fr:Brian_May","c:8/8b/TaylorHawkTributeWemb030922_%28208_copped%29.jpg",{"cats":["chanteurs_int","groupes"]}],["Q313013",45,"chanteur","Brian Wilson","PC","Brian Wilson, né le 20 juin 1942 à Inglewood et mort le 11 juin 2025, est un auteur-compositeur, chanteur et producteur américain qui a fondé le groupe The Beach Boys.",119,"fr:Brian_Wilson","c:7/70/Brian_Wilson_1976_crop.jpg"],["Q11975",46,"chanteur","Britney Spears","R","Britney Spears, née le 2 décembre 1981 à McComb, est une chanteuse, danseuse, actrice et femme d'affaires américaine. Souvent appelée la Princesse de la pop, elle est reconnue pour avoir influencé la pop à la fin des années 1990 et dans les années 2000.","Britney Spears, née le 2 décembre 1981 à McComb, est une chanteuse, danseuse, actrice et femme d'affaires américaine.","fr:Britney_Spears","c:d/da/Britney_Spears_2013_%28Straighten_Crop%29.jpg"],["Q190151",47,"chanteur","Bruce Dickinson","C","Bruce Dickinson, né le 7 août 1958 à Worksop, est un chanteur, compositeur, pilote de ligne, escrimeur, animateur radio, et ancien directeur marketing britannique, célèbre pour être le chanteur du groupe de heavy metal Iron Maiden, avec qui il a chanté sur 13 albums studios, mais qui a mené également une activité en solo.",113,"fr:Bruce_Dickinson","c:c/c2/Bruce_Dickinson_%E2%80%93_Iron_Maiden_%E2%80%93_Tons_of_Rock_2026_05.jpg",{"cats":["chanteurs_int","groupes"]}],["Q1225",48,"chanteur","Bruce Springsteen","PC","Bruce Springsteen, né le 23 septembre 1949 à Long Branch, est un auteur-compositeur-interprète et guitariste américain.",null,"fr:Bruce_Springsteen","c:6/60/Bruce_Springsteen_Springsteen-79.jpg"],["Q1450",49,"chanteur","Bruno Mars","E","Peter Eugene Hernandez, dit Bruno Mars, né le 8 octobre 1985 à Honolulu, dans l'État de Hawaï aux États-Unis, est un auteur-compositeur-interprète, musicien, danseur-chorégraphe, directeur artistique, producteur, réalisateur, styliste et homme d’affaires américain.",116,"fr:Bruno_Mars","c:2/2d/Bruno_Mars_-_24K_Magic_Tour_%2837320927992%29.jpg"],["Q482907",50,"chanteur","Bryan Adams","C","Bryan Adams, né le 5 novembre 1959 à Kingston, Ontario est un auteur-compositeur-interprète, multi-instrumentiste, photographe et acteur canado-britannique.",114,"fr:Bryan_Adams","c:7/7e/Bryan_Adams_Hamburg_MG_0631_flickr.jpg"],["Q5977",51,"chanteur","Buddy Holly","C","Buddy Holly, nom de scène de Charles Hardin Holley, né le 7 septembre 1936 à Lubbock au Texas et mort le 3 février 1959 à Clear Lake dans l'Iowa, est un chanteur, guitariste et compositeur américain de rock 'n' roll.",119,"fr:Buddy_Holly","c:1/14/Buddy_Holly_cropped.JPG"],["Q17305712",52,"chanteur","Burna Boy","C","Burna Boy, parfois surnommé Odugwu, de son vrai nom Damini Ebunoluwa Ogulu, né le 2 juillet 1991 à Port-Harcourt, est un chanteur et compositeur nigérian. Il est devenu célèbre en 2012 après avoir sorti Like to Party, le single principal de son premier album studio LIFE. Ses albums et singles s'enchaînent ensuite. En 2017, Burna Boy a signé avec Bad Habit / Atlantic Records aux États-Unis et Warner Music Group au niveau international. Son troisième album studio Outside a marqué ses débuts sur un grand label.",117,"fr:Burna_Boy","c:3/37/Untold_2024_-Burna_Boy_%2853927293629%29_%28cropped%29.jpg"],["Q81637",53,"chanteur","Calvin Harris","C","Calvin Harris, nom de scène d’Adam Wiles, est un disc jockey, chanteur, musicien et producteur britannique de musique électronique, né le 17 janvier 1984 à Dumfries. Surnommé « le nouveau roi de l'electropop » par la presse spécialisée, son premier album I Created Disco, sorti en 2007, est disque d'or au Royaume-Uni, notamment grâce aux titres à succès Acceptable in the 80s et The Girls.",117,"fr:Calvin_Harris","c:0/02/Calvin_Harris_-_Rock_in_Rio_Madrid_2012_-_09.jpg",{"cats":["chanteurs_int","electro"]}],["Q18810940",54,"chanteur","Camila Cabello","C","Camila Cabello, née le 3 mars 1997 à Cojímar, est une chanteuse et actrice cubano-mexicaine naturalisée américaine.",null,"fr:Camila_Cabello","c:8/8a/Camila_Cabello_Sundance_2024_Cropped.jpg"],["Q29033668",55,"chanteur","Cardi B","R","Belcalis Marlenis Almánzar, plus connue sous le nom de Cardi B, née le 11 octobre 1992 à New York, est une rappeuse, chanteuse et actrice américaine. Elle doit sa célébrité dans un premier temps à la viralité de vidéos diffusées sur Vine et Instagram. De 2015 à 2017, elle apparaît dans la série de téléréalité Love & Hip Hop: New York sur VH1 et commence une carrière musicale en sortant deux mixtapes: Gangsta Bitch Music, Vol. 1 et Gangsta Bitch Music, Vol. 2.",116,"fr:Cardi_B","c:2/27/Cardi_B_at_2026_Essence_Festival_of_Culture_02_%28cropped%29_%28cropped%29.jpg"],["Q229613",56,"chanteur","Carlos Gardel","C","Carlos Gardel, né Charles Romuald Gardès le 11 décembre 1890 à Toulouse ou Tacuarembó et mort le 24 juin 1935 près de Medellin en Colombie, est un chanteur-compositeur de tango et un acteur.",117,"fr:Carlos_Gardel","https://upload.wikimedia.org/wikipedia/commons/thumb/a/a5/Carlos_Gardel_signature.svg/330px-Carlos_Gardel_signature.svg.png"],["Q52583",57,"chanteur","Carly Rae Jepsen","C","Carly Rae Jepsen, née le 21 novembre 1985 à Mission, est une auteure-compositrice-interprète canadienne.",null,"fr:Carly_Rae_Jepsen","c:d/d9/Carly_Rae_Jepsen_Primavera19_-146_%2848986111926%29_%28cropped%29.jpg"],["Q215546",58,"chanteur","Carrie Underwood","PC","Carrie Marie Underwood est une autrice-compositrice-interprète et actrice américaine. Son univers musical est proche de la musique country et de la pop. Elle est la gagnante de la quatrième saison d’American Idol aux États-Unis en 2005. Son premier album, Some Hearts, sorti en novembre 2005, est certifié sept fois disque de platine par la RIAA. Il devient l’album country qui s’est vendu le plus rapidement au classement album américain.","Carrie Marie Underwood est une autrice-compositrice-interprète et actrice américaine.","fr:Carrie_Underwood","c:d/d3/Carrie_Underwood_2%2C_2012.jpg"],["Q154216",59,"chanteur","Cat Stevens","PC","Steven Demetre Georgiou, dit Cat Stevens, est un chanteur, musicien et auteur-compositeur-interprète britannique né le 21 juillet 1948 à Londres. Après avoir rencontré un grand succès dans les années 1970, il se convertit à la religion musulmane en décembre 1977 et prend le nom de Yusuf Islam. Il abandonne la musique pour se consacrer à diverses causes philanthropiques. Toutefois, il revient à la musique dans les années 1990 et entame, en 2010, une tournée internationale sous le nom de Yusuf/Cat Stevens.",118,"fr:Cat_Stevens","c:a/a0/Cat_Stevens_Glastonbury_2023_-2.jpg"],["Q474045",60,"chanteur","Celia Cruz","C","Úrsula Hilaria Celia Caridad de la Santísima Trinidad Cruz Alfonso alias Celia Cruz, née le 21 octobre 1925 à La Havane et morte le 16 juillet 2003 à Fort Lee, était une chanteuse de musique cubaine et de salsa.",119,"fr:Celia_Cruz","c:8/89/Celia_Cruz_1957_color.jpg"],["Q110281146",61,"chanteur","Chappell Roan","R","Kayleigh Rose Amstutz, dite Chappell Roan, née le 19 février 1998 à Willard, est une auteure-compositrice-interprète américaine.",116,"fr:Chappell_Roan","c:8/84/ChappellRoanRockES200825-198_%28cropped%29.jpg"],["Q5084390",62,"chanteur","Charli XCX","R","Charlotte Aitchison, dite Charli XCX, est une auteure-compositrice-interprète, actrice et productrice britannique, née le 2 août 1992 à Cambridge.",118,"fr:Charli_XCX","c:c/ca/Aidan_Zamiri_and_Charlie_XCX_at_Berlin_Film_Festival_2026%2C_%28P1230624%29_%28cropped%29.jpg"],["Q19198",64,"chanteur","Chester Bennington","R","Chester Charles Bennington est un chanteur, compositeur et acteur américain, né le 20 mars 1976 à Phoenix et mort le 20 juillet 2017 à Palos Verdes Estates.",119,"fr:Chester_Bennington","c:0/00/Linkin_Park-Rock_im_Park_2014-_by_2eight_3SC0322.jpg",{"cats":["chanteurs_int","groupes"]}],["Q155700",65,"chanteur","Chris Brown","PC","Christopher Brown, dit Chris Brown, né le 5 mai 1989 à Tappahannock en Virginie, est un chanteur, danseur-chorégraphe, auteur-compositeur-interprète, et réalisateur américain. Débutant dans le chant et la danse à un jeune âge, il signe avec le label Jive Records en 2004, et fait paraître son premier album éponyme l'année suivante. Il atteint la seconde place du Billboard 200 américain, et est plus tard certifié double disque de platine par la Recording Industry Association of America.",118,"fr:Chris_Brown","c:a/ad/Chris_Brown_in_Tampa%2C_2015.jpg"],["Q712860",66,"chanteur","Chris Martin","E","Chris Martin, né le 2 mars 1977 à Exeter dans le Devon, est un auteur-compositeur-interprète, producteur et musicien britannique.",116,"fr:Chris_Martin","c:6/68/ChrisMartinManch030623_%28cropped%29.jpg"],["Q41594",67,"chanteur","Christina Aguilera","PC","Christina Aguilera, est une auteure-compositrice-interprète, femme d'affaires, actrice et philanthrope américaine. En 1993, à seulement 12 ans, elle lance sa carrière dans The Mickey Mouse Club. Six ans plus tard, elle sort son premier album, Christina Aguilera, qui se vend à 16 millions d’exemplaires, et dont trois des singles se classent en tête des palmarès aux États-Unis.","Christina Aguilera, est une auteure-compositrice-interprète, femme d'affaires, actrice et philanthrope américaine.","fr:Christina_Aguilera","c:8/8b/Christina_Aguilera_-_What_A_Girl_Wants_%28Live_%40_Rio_de_Janeiro%29_2025_01.jpg"],["Q5921",68,"chanteur","Chuck Berry","PC","Chuck Berry, de son vrai nom Charles Edward Anderson Berry, né à Saint-Louis le 18 octobre 1926 et mort le 18 mars 2017 à Wentzville, dans le comté de Saint Charles, est un auteur-compositeur-interprète et guitariste américain, considéré comme l'un des pionniers du rock 'n' roll.",119,"fr:Chuck_Berry","c:2/20/Chuck_Berry_1957.jpg"],["Q82238",69,"chanteur","Cliff Richard","PC","Cliff Richard, né Harry Rodger Webb le 14 octobre 1940 à Lucknow, est un chanteur de rock britannique.",null,"fr:Cliff_Richard","c:1/1c/Cliff_Richard_-_Old_Royal_Naval_Yard_Greenwich_-_Saturday_1st_July_2017_CliffGreenwich010717-43_%2835672276090%29_%28cropped%29.jpg"],["Q222071",70,"chanteur","Courtney Love","PC","Courtney Michelle Love Cobain, dite Courtney Love, née Love Michelle Harrison le 9 juillet 1964 à San Francisco, puis rebaptisée Courtney Michelle Harrison en 1970, est une autrice-compositrice-interprète, actrice et artiste visuelle américaine.",117,"fr:Courtney_Love","c:4/42/Courtney_Love_%2817702467010%29.jpg"],["Q1545",71,"chanteur","Cyndi Lauper","C","Cyndi Lauper, de son vrai nom Cynthia Lauper, née le 22 juin 1953 à New York), est une chanteuse, compositrice, actrice et activiste américaine.",119,"fr:Cyndi_Lauper","c:6/69/CyndiLauper2022.jpg"],["Q12006",72,"chanteur","Dave Grohl","R","David Eric Grohl, né le 14 janvier 1969 à Warren dans l'Ohio, est un multi-instrumentiste, chanteur, compositeur et réalisateur américain.",115,"fr:Dave_Grohl","c:0/07/FoosDublin210819-2_%2848620472807%29_%28cropped%29.jpg",{"cats":["chanteurs_int","groupes"]}],["Q187165",73,"chanteur","Dave Mustaine","C","Dave Mustaine est un chanteur et guitariste américain né le 13 septembre 1961 à La Mesa. D'abord guitariste du groupe Panic, il occupe ensuite le poste de soliste au sein du groupe de thrash metal Metallica, où il signe plusieurs chansons devenues des classiques du quatuor, avant d'en être évincé à cause de problèmes d’addiction pour être remplacé par Kirk Hammett.","Dave Mustaine est un chanteur et guitariste américain né le 13 septembre 1961 à La Mesa.","fr:Dave_Mustaine","c:3/3c/HF2022Megadeth_2.jpg",{"cats":["chanteurs_int","groupes"]}],["Q5383",74,"chanteur","David Bowie","L","David Robert Jones, dit David Bowie, né le 8 janvier 1947 à Londres et mort le 10 janvier 2016 à Manhattan, est un auteur-compositeur-interprète, musicien, acteur et peintre britannique.",114,"fr:David_Bowie","c:e/e8/David-Bowie_Chicago_2002-08-08_photoby_Adam-Bielawski-cropped.jpg"],["Q178517",75,"chanteur","David Gilmour","C","David Gilmour /ɡɪlmɔːr/, né le 6 mars 1946 à Grantchester, près de Cambridge, est un guitariste et chanteur britannique. Sa célébrité est surtout liée à sa carrière au sein de Pink Floyd dont il est membre depuis 1968.","David Gilmour /ɡɪlmɔːr/, né le 6 mars 1946 à Grantchester, près de Cambridge, est un guitariste et chanteur britannique.","fr:David_Gilmour","c:5/53/DGilmourRAH111024_%2821_of_63%29_%28cropped%29.jpg",{"cats":["chanteurs_int","groupes"]}],["Q201927",76,"chanteur","David Hasselhoff","C","David Hasselhoff, né le 17 juillet 1952 à Baltimore, est un acteur et chanteur américain. Il est notamment connu pour avoir tenu les rôles principaux dans les séries K 2000 et Alerte à Malibu.","David Hasselhoff, né le 17 juillet 1952 à Baltimore, est un acteur et chanteur américain.","fr:David_Hasselhoff","c:3/3b/David_Hasselhof_at_re-publica_May_2014_%28cropped%29.jpg"],["Q215359",77,"chanteur","Dean Martin","E","Dean Martin, né Dino Crocetti le 7 juin 1917 à Steubenville et mort le 25 décembre 1995 à Beverly Hills, est un chanteur et acteur américano-italien. Il est issu d'une famille italienne originaire de Montesilvano.",111,"fr:Dean_Martin","c:e/e6/Dean_Martin_-_publicity.JPG",{"cats":["chanteurs_int","combat"]}],["Q204005",78,"chanteur","Debby Ryan","C","Deborah Ryan, dite Debby Ryan ou Debby Dun depuis son mariage, est une actrice, chanteuse, productrice, mannequin et réalisatrice américaine née le 13 mai 1993 à Huntsville dans l'Alabama.",116,"fr:Debby_Ryan","c:2/21/Debby_Ryan_presenting_at_MTV_EMAs_2018.png"],["Q41173",79,"chanteur","Demi Lovato","PC","Demi Lovato, née Demetria Devonne Lovato le 20 août 1992 à Albuquerque, est une autrice-compositrice-interprète, actrice, mannequin et entrepreneuse américaine. Elle fait ses débuts dans la comédie très jeune en jouant dans la série pour enfants Barney en 2002, mais c'est en 2008 que sa notoriété grandit avec le rôle principal dans le téléfilm de Disney Channel Camp Rock, et en 2009, dans la série à succès de la même chaîne, Sonny with a chance.",112,"fr:Demi_Lovato","c:1/1c/Demi_Lovato_Interview_Feb_2020.png"],["Q36290",80,"chanteur","Diana Ross","PC","Diana Ross, née le 26 mars 1944 à Détroit, est une chanteuse, compositrice et actrice américaine.",null,"fr:Diana_Ross","c:b/b4/DRossLongleat010722_%289_of_43%29_%2852189231585%29_%28cropped%29.jpg"],["Q202550",81,"chanteur","Dido","C","Dido, née Dido Florian Cloud de Bounevialle O'Malley Armstrong, le 25 décembre 1971 dans le quartier londonien de Kensington, en Angleterre, est une chanteuse pop britannique.",113,"fr:Dido","c:b/bc/Dido_2019_%28cropped_2%29.jpg"],["Q51120673",82,"chanteur","Doja Cat","PC","Amala Ratna Zandile Dlamini, dite Doja Cat, née le 21 octobre 1995 à Los Angeles, est une rappeuse, chanteuse, auteure-compositrice-interprète, streameuse gaming et réalisatrice artistique américaine, décrite par la presse comme « la reine du pop-rap ».",110,"fr:Doja_Cat","c:f/fa/Doja_Cat_x_Amazon1.1.jpg"],["Q180453",83,"chanteur","Dolly Parton","M","Dolly Parton est une chanteuse, autrice-compositrice-interprète, musicienne multi-instrumentiste, actrice, scénariste et productrice américaine, née le 19 janvier 1946 à Pittman Center et morte le 25 août 2026 à Nashville.",117,"fr:Dolly_Parton","c:a/a3/Young-Dolly-Parton.jpg"],["Q541599",84,"chanteur","Dolores O'Riordan","R","Dolores O'Riordan, née le 6 septembre 1971 à Ballybricken et morte le 15 janvier 2018 à Westminster, est une auteure-compositrice-interprète et musicienne de rock irlandaise. Elle est chanteuse et leader du groupe irlandais The Cranberries de 1990 jusqu'à une interruption momentanée en 2003 qui durera six ans. Le groupe se reforme en 2009 pour se séparer définitivement en avril 2019 à la suite de son décès.",108,"fr:Dolores_O'Riordan","c:9/9c/Dolores_O%27Riordan_2016_%28cropped%29.jpeg"],["Q908933",85,"chanteur","Donna Summer","C","LaDonna Adrian Gaines, connue sous son nom de scène Donna Summer, née le 31 décembre 1948 à Boston et morte le 17 mai 2012 à Naples, est une chanteuse de disco et pop américaine. Surnommée La Reine du Disco, elle en est la vedette durant les années 1970 et 1980.",117,"fr:Donna_Summer","c:7/7c/Donna_Summer_%281977_Casablanca_publicity_headshot%29.jpg"],["Q13560423",87,"chanteur","Dove Cameron","R","Dove Olivia Cameron, née Chloe Celeste Hosterman le 15 janvier 1996 à Bainbridge Island, Washington est une actrice et autrice-compositrice-interprète américaine.",118,"fr:Dove_Cameron","c:6/6e/Dove_Cameron_%40_Moroccan_Lounge_10_10_2021_%2851784366755%29_%28cropped%29.jpg"],["Q6078",88,"chanteur","Dr. Dre","C","Andre Romelle Young, dit Dr. Dre, né le 18 février 1965 à Compton, est un rappeur, producteur, compositeur, acteur, réalisateur, entrepreneur, homme d’affaires et ancien disc jockey américain. Il est le fondateur et actuel CEO d'Aftermath Entertainment et de Beats Electronics. Dre est également l'ancien codétenteur et membre de Death Row Records.","Andre Romelle Young, dit Dr.","fr:Dr._Dre","c:d/de/Dr._Dre_in_2011.jpg"],["Q33240",89,"chanteur","Drake","R","Drake, de son nom complet Aubrey Drake Graham, né le 24 octobre 1986 à Toronto, est un rappeur, chanteur, compositeur, acteur et homme d’affaires canado-américain.",118,"fr:Drake_(rappeur)","c:c/c4/Drake_and_Future_2016_Summer_Sixteen_Tour.jpg"],["Q21914464",90,"chanteur","Dua Lipa","L","Dua Lipa, née le 22 août 1995 à Londres, est une auteure-compositrice-interprète, actrice et mannequin britannique d’origine kosovare. Elle est considérée comme la reine de la pop britannique.",114,"fr:Dua_Lipa","c:6/66/Dua_Lipa-69798_%28cropped%29.jpg"],["Q222818",91,"chanteur","Eartha Kitt","C","Eartha Mae Kitt, surnommée « Miss Kitt », est une danseuse, chanteuse de variétés, de comédies musicales et de jazz, actrice de théâtre et de cinéma américaine.",116,"fr:Eartha_Kitt","c:e/e8/Eartha_Kitt.jpg"],["Q47447",92,"chanteur","Ed Sheeran","PC","Edward Christopher Sheeran, dit Ed Sheeran, né le 17 février 1991 à Halifax dans le Yorkshire de l'Ouest, est un chanteur, auteur-compositeur-interprète et guitariste britannique.",112,"fr:Ed_Sheeran","c:a/a2/Ed_Sheeran_%288508826576%29.jpg"],["Q31164",93,"chanteur","Ellie Goulding","C","Ellie Goulding, est une auteure-compositrice-interprète britannique, née le 30 décembre 1986 à Hereford en Angleterre.",null,"fr:Ellie_Goulding","c:b/b2/%D0%A3%D1%87%D0%B0%D1%81%D1%82%D1%8C_%D0%9F%D1%80%D0%B5%D0%B7%D0%B8%D0%B4%D0%B5%D0%BD%D1%82%D0%B0_%D0%A3%D0%BA%D1%80%D0%B0%D1%97%D0%BD%D0%B8_%D1%83_%D0%B4%D1%80%D1%83%D0%B3%D0%BE%D0%BC%D1%83_%D0%A1%D0%B0%D0%BC%D1%96%D1%82%D1%96_%D0%BF%D0%B5%D1%80%D1%88%D0%B8%D1%85_%D0%BB%D0%B5%D0%B4%D1%96_%D1%82%D0%B0_%D0%B4%D0%B6%D0%B5%D0%BD%D1%82%D0%BB%D1%8C%D0%BC%D0%B5%D0%BD%D1%96%D0%B2_95_%28cropped%29_%28cropped%29.jpg"],["Q2808",94,"chanteur","Elton John","R","Elton John, né Reginald Dwight le 25 mars 1947 à Pinner, est un auteur-compositeur-interprète, pianiste, claviériste et acteur britannique naturalisé américain.",119,"fr:Elton_John","c:6/61/EltonDocBFILFF101024_%284_of_17%29_%28cropped%29.jpg",{"cats":["chanteurs_int","lgbt"]}],["Q303",95,"chanteur","Elvis Presley","L","Elvis Presley, né le 8 janvier 1935 à Tupelo dans le Mississippi, aux États-Unis, et mort le 16 août 1977 à Memphis dans le Tennessee, est un chanteur et acteur américain. Surnommé « The King of Rock and Roll » ou plus simplement « The King » en raison de son immense succès international et pour son rôle dans l'expansion de ce style musical à l'échelle mondiale, il est l'une des icônes culturelles majeures du XXe siècle.",115,"fr:Elvis_Presley","c:9/99/Elvis_Presley_promoting_Jailhouse_Rock.jpg"],["Q5608",96,"chanteur","Eminem","E","Eminem, de son vrai nom Marshall Bruce Mathers III, est un rappeur, auteur-compositeur, producteur et acteur américain. Il est reconnu pour avoir popularisé le hip-hop parmi les classes moyennes et supérieures des États-Unis et est acclamé par la critique comme l'un des plus grands rappeurs de tous les temps.","Eminem, de son vrai nom Marshall Bruce Mathers III, est un rappeur, auteur-compositeur, producteur et acteur américain.","fr:Eminem","c:0/0f/Eminem_2021_Color_Corrected.jpg"],["Q47122",97,"chanteur","Enrique Iglesias","PC","Enrique Iglesias, né le 8 mai 1975 à Madrid, est un chanteur de pop latino et de RnB, guitariste et acteur espagnol. Il commence sa carrière au Mexique, sous le label discographique indépendant Fonovisa Records, et devient ensuite un des artistes les plus célèbres d'Amérique latine. À la fin des années 1990, il quitte sa maison de disques pour signer un contrat avec Universal Music.","Enrique Iglesias, né le 8 mai 1975 à Madrid, est un chanteur de pop latino et de RnB, guitariste et acteur espagnol.","fr:Enrique_Iglesias","c:3/30/Enrique_Iglesias_2015_%28Cropped%29_%28cropped%29.jpg"],["Q38257",98,"chanteur","Enya","C","Eithne Patricia Ní Bhraonáin, dite Enya, née le 17 mai 1961 à Gaoth Dobhair est une chanteuse, compositrice et musicienne irlandaise. Elle est l'une des artistes irlandaises ayant vendu le plus de disques au monde. « Enya » est une approximation phonétique de la prononciation de « Eithne » en gaélique irlandais.",110,"fr:Enya","c:f/f4/Enya_-_The_Orlando_Sentinel_%281989%29_%28cropped%29.jpg"],["Q48187",99,"chanteur","Eric Clapton","R","Eric Clapton, né le 30 mars 1945 à Ripley, est un guitariste, chanteur, auteur-compositeur-interprète britannique, de blues rock. En 2011, dans son classement « les 100 plus grands guitaristes de tous les temps », le mensuel Rolling Stone le place en deuxième position, juste derrière Jimi Hendrix.",117,"fr:Eric_Clapton","c:b/b1/Eric_Clapton_1.jpg"],["Q44398",100,"chanteur","Falco","C","Johann « Hans » Hölzel, dit Falco, né le 19 février 1957 à Vienne et mort le 6 février 1998 à Puerto Plata en République dominicaine dans un accident de la route, est un musicien, chanteur pop rock et rappeur autrichien. Il est parfois surnommé « le premier rappeur blanc ».",109,"fr:Falco_(chanteur)","c:b/ba/Falco_1986.jpg"],["Q464650",101,"chanteur","Faye Wong","C","Faye Wong, née le 8 août 1969 à Pékin sous le nom Xia Lin, est une actrice et une chanteuse de cantopop et de pop. Elle est très populaire en Asie, plus connue en Occident pour ses rôles dans les films de Wong Kar-wai 2046 et Chungking Express, ainsi que pour sa participation à la bande originale du jeu Final Fantasy VIII pour laquelle elle interprète le thème du jeu Eyes on Me.","Faye Wong, née le 8 août 1969 à Pékin sous le nom Xia Lin, est une actrice et une chanteuse de cantopop et de pop.","fr:Faye_Wong","c:4/45/Faye_Wong.jpg"],["Q180004",102,"chanteur","Fergie","C","Stacy Ann Ferguson, nom de scène Fergie, née le 27 mars 1975 à Hacienda Heights, Californie est une chanteuse et actrice américaine.",112,"fr:Fergie_(chanteuse)","c:4/42/Fergie_%282014%29.jpg"],["Q202859",103,"chanteur","Flea","C","Michael Balzary, dit Flea, né le 16 octobre 1962 à Melbourne, est un bassiste, pianiste, trompettiste et acteur australo-américain.",111,"fr:Flea","c:1/15/2016_Red_Hot_Chili_Peppers_-_Michael_Flea_Balzary_%28cropped%29.jpg"],["Q40912",104,"chanteur","Frank Sinatra","L","Frank Sinatra, né le 12 décembre 1915 à Hoboken et mort le 14 mai 1998 à Los Angeles au centre médical Cedars-Sinaï, est un chanteur, acteur et producteur de musique américain.",116,"fr:Frank_Sinatra","c:4/43/Frank_Sinatra_%281957_Pal_Joey_publicity_photo%29.jpg"],["Q127330",105,"chanteur","Frank Zappa","R","Frank Vincent Zappa, né le 21 décembre 1940 à Baltimore et mort le 4 décembre 1993 à Los Angeles, est un compositeur, musicien, guitariste, cinéaste, producteur et satiriste américain.",117,"fr:Frank_Zappa","c:6/63/Frank_Zappa_-_Capt._Beefheart_-_crop.jpg"],["Q15869",106,"chanteur","Freddie Mercury","L","Freddie Mercury, né Farrokh Bulsara le 5 septembre 1946 à Stone Town dans le protectorat de Zanzibar et mort le 24 novembre 1991 à Kensington, est un auteur-compositeur-interprète, chanteur, musicien et producteur britannique.",114,"fr:Freddie_Mercury","c:e/ef/Freddie_Mercury_performing_in_New_Haven%2C_CT%2C_November_1977.jpg",{"cats":["chanteurs_int","groupes","lgbt"]}],["Q2643",107,"chanteur","George Harrison","E","George Harrison, né le 25 février 1943 à Liverpool et mort le 29 novembre 2001 à Los Angeles, est un musicien britannique, guitariste, organiste, auteur-compositeur-interprète, producteur de cinéma et le plus jeune membre des Beatles.",109,"fr:George_Harrison","c:4/45/George_Harrison_1974_%28cropped%29.jpg"],["Q130311",108,"chanteur","George Michael","E","George Michael, né le 25 juin 1963 à East Finchley et mort le 25 décembre 2016 à Goring-on-Thames, est un auteur-compositeur-interprète et producteur britannique.",105,"fr:George_Michael","c:0/06/George_Michael_%282011%29.jpg"],["Q19845",109,"chanteur","Geri Halliwell","PC","Geraldine Estelle « Geri » Horner alias Geri Horner, née Halliwell le 6 août 1972 à Watford, dans la banlieue de Londres, est une chanteuse, danseuse, auteur-interprète, styliste, écrivain et actrice britannique, surtout connue pour être l'un des membres du groupe Spice Girls. Son surnom y est alors Ginger Spice. Entre 1996 et 1998, les Spice Girls connaissent un énorme succès, avec plus de 85 millions de disques vendus.",112,"fr:Geri_Halliwell","c:3/34/SpiceGirlWembley150619-22_%2849000567242%29_%28cropped%29.jpg"],["Q184697",110,"chanteur","Gloria Estefan","C","Gloria Estefan, née Gloria Fajardo García le 1er septembre 1957 à La Havane, est une chanteuse, auteure-compositrice-interprète, actrice et entrepreneuse cubano-américaine.",95,"fr:Gloria_Estefan","c:3/36/Gloria_Estefan_in_2017.jpg"],["Q450429",111,"chanteur","Grace Jones","C","Grace Jones, née le 19 mai 1948 à Spanish Town en Jamaïque, est une chanteuse, auteur-compositeur, actrice et ancien mannequin jamaïcaine.",116,"fr:Grace_Jones","c:7/7f/Grace_Jones_at_Carriageworks_%28Vivid%29_-_1st_June_2015_08.jpg"],["Q106301562",112,"chanteur","Gracie Abrams","PC","Gracie Madigan Abrams, née le 7 septembre 1999 à Los Angeles, est une autrice-compositrice-interprète américaine et la fille du réalisateur J. J. Abrams.",118,"fr:Gracie_Abrams","c:9/98/Gracie_Abrams_at_the_2026_Met_Gala_268_%28cropped%29.jpg"],["Q483379",113,"chanteur","Gwen Stefani","R","Gwen Stefani, est une chanteuse, auteure-compositrice-interprète et styliste américaine. Elle se fait connaître en tant que chanteuse du groupe No Doubt depuis 1986, dont le premier album No Doubt est sorti en 1992, suivi de The Beacon Street Collection et Tragic Kingdom tous les deux sortis en 1995. Le groupe est de retour en 2000 avec Return of Saturn suivi en 2001 de Rock Steady, qui comprend la chanson Hey Baby.","Gwen Stefani, est une chanteuse, auteure-compositrice-interprète et styliste américaine.","fr:Gwen_Stefani","c:7/79/Barack_Obama_and_Gwen_Stefani_State_Dinner_performance_%28cropped%29_%28cropped%29.jpg"],["Q206181",114,"chanteur","Hank Williams","C","Hiram King « Hank » Williams, né le 17 septembre 1923 et mort le 1er janvier 1953, est un chanteur, guitariste et compositeur américain, icône de la musique country, et un musicien influent du XXe siècle.",113,"fr:Hank_Williams","c:6/62/Hank_Williams_Promotional_Photo.jpg"],["Q214959",115,"chanteur","Harry Belafonte","C","Harold George Bellanfanti Jr., dit Harry Belafonte, né le 1er mars 1927 à Harlem dans la ville de New York et mort le 25 avril 2023 dans la même ville, est un chanteur, acteur et militant des droits civiques américain.",117,"fr:Harry_Belafonte","https://upload.wikimedia.org/wikipedia/commons/thumb/5/53/Harry_Belafonte_1970_%28cropped%29.tif/330px-Harry_Belafonte_1970_%28cropped%29.tif.png"],["Q3626966",116,"chanteur","Harry Styles","E","Harry Styles, né le 1er février 1994 à Redditch, est un auteur-compositeur-interprète, musicien et acteur britannique.",null,"fr:Harry_Styles","c:b/b2/HarryStylesWembley170623_%2865_of_93%29_%2852982678051%29_%28cropped_2%29.jpg"],["Q552682",117,"chanteur","Hatsune Miku","C","Hatsune Miku, est une chanteuse virtuelle japonaise tenant lieu d'avatar commercial des premiers opus de la série des Vocaloid, s'exprimant par le biais d'une application de synthèse vocale développée par Crypton Future Media. Cette banque de voix utilise les logiciels Vocaloid 2, Vocaloid 3 ou encore Vocaloid 4 de Yamaha. Sa voix est synthétisée à partir de celle de l'actrice Saki Fujita.",117,"fr:Hatsune_Miku","c:7/73/Christmas_Theme_Hatsune_Miku.jpg"],["Q201562",118,"chanteur","Hayley Williams","R","Hayley Nichole Williams, née le 27 décembre 1988 à Meridian est une chanteuse et auteure-compositrice américaine.",null,"fr:Hayley_Williams","c:e/e0/Hayley_Williams_at_Royal_Albert_Hall_-_19th_June_2017_-_09_%28cropped%29.jpg",{"cats":["chanteurs_int","groupes"]}],["Q236549",119,"chanteur","Helene Fischer","C","Helene Fischer, née le 5 août 1984 à Krasnoïarsk, est une chanteuse, danseuse et actrice russo-allemande. Avec ses douze millions d'albums vendus, elle est la chanteuse allemande la plus célèbre. Ses albums Farbenspiel et Best of font partie des albums les plus vendus en Allemagne. Elle connaît aussi beaucoup de succès en Autriche, en Suisse et, dans une certaine mesure, aux Pays-Bas et en Belgique.","Helene Fischer, née le 5 août 1984 à Krasnoïarsk, est une chanteuse, danseuse et actrice russo-allemande.","fr:Helene_Fischer","c:e/ef/Helene_Fischer_2016.jpg"],["Q234598",120,"chanteur","Hikaru Utada","C","Hikaru Utada, dont le nom est Utada aux États-Unis et le surnom Hikki par ses fans au Japon, est une chanteuse, compositrice, arrangeur et productrice de musique américano-japonaise, enfant de l'ancienne chanteuse de enka Keiko Fuji et du producteur de musique Teruzane Utada.",111,"fr:Hikaru_Utada","c:d/d2/Utada_Hikaru_2026.png"],["Q16233232",122,"chanteur","Hozier","C","Andrew Hozier-Byrne, dit Hozier, né le 17 mars 1990 à Bray, dans le comté de Wicklow, est un auteur-compositeur-interprète et musicien irlandais.",92,"fr:Hozier","c:1/15/Hozier_2015_01_%28cropped%29.jpg"],["Q2748803",123,"chanteur","Iggy Azalea","C","Iggy Azalea, de son vrai nom Amethyst Kelly, née le 7 juin 1990 à Sydney, est une rappeuse et mannequin australienne.",null,"fr:Iggy_Azalea","c:0/02/Iggy_Azalea%2C_Main_Stage_EXIT_Festival_2022_1_%28cropped%29.jpg"],["Q182665",124,"chanteur","Iggy Pop","PC","James Newell Osterberg Jr., dit Iggy Pop, est un chanteur, compositeur et acteur américain né le 21 avril 1947 à Muskegon dans le Michigan.",112,"fr:Iggy_Pop","c:4/4d/IggyChesterRocks.jpg"],["Q483907",125,"chanteur","Jack Black","R","Jack Black est un acteur, chanteur, compositeur, producteur musical, humoriste et scénariste américain, né le 28 août 1969 à Santa Monica.",117,"fr:Jack_Black","c:9/92/TenaciousDO2160623_%2838_of_62%29_Jack_Black.jpg"],["Q130799",126,"chanteur","James Blunt","M","James Blunt, né Blount le 22 février 1974 à Tidworth, dans le Wiltshire, est un auteur-compositeur-interprète et guitariste britannique, reconnaissable à sa voix de ténor léger.",112,"fr:James_Blunt","c:0/0d/2017_James_Blunt_-_by_2eight_-_DSC7939.jpg"],["Q5950",127,"chanteur","James Brown","C","James Joseph Brown, Jr, est un musicien, chanteur, auteur-compositeur, danseur et producteur américain. Il est l'une des figures majeures du rhythm and blues, de la soul music, du funk et du mouvement Black Power.","James Joseph Brown, Jr, est un musicien, chanteur, auteur-compositeur, danseur et producteur américain.","fr:James_Brown","c:9/99/James_Brown_Live_Hamburg_1973_1702730029.jpg"],["Q484302",128,"chanteur","James Hetfield","PC","James Hetfield est un musicien américain, né le 3 août 1963 à Downey, en Californie. Avec Lars Ulrich il est le cofondateur, chanteur et guitariste rythmique du groupe de thrash metal Metallica.","James Hetfield est un musicien américain, né le 3 août 1963 à Downey, en Californie.","fr:James_Hetfield","c:8/8f/James_Hetfield_live_in_Amesterdam_29_April_2023.jpg",{"cats":["chanteurs_int","groupes"]}],["Q171905",129,"chanteur","Jamie Foxx","PC","Jamie Foxx, est un acteur, humoriste, musicien et chanteur américain, né le 13 décembre 1967 à Terrell.",null,"fr:Jamie_Foxx","c:6/6e/TIFF_2019_jamie_foxx_%28cropped%29.jpg"],["Q131324",130,"chanteur","Janet Jackson","R","Janet Jackson, née le 16 mai 1966 à Gary, est une auteure-compositrice-interprète, danseuse et actrice américaine.",null,"fr:Janet_Jackson","c:9/9c/JanetJacksonUnbreakableTourSanFran2015_%28cropped%29.jpg"],["Q1514",131,"chanteur","Janis Joplin","PC","Janis Joplin, née le 19 janvier 1943 à Port Arthur et morte le 4 octobre 1970 à Los Angeles, est une chanteuse américaine.",110,"fr:Janis_Joplin","c:9/92/Janis_Joplin_1970.JPG"],["Q238819",133,"chanteur","Jay Chou","C","Jay Chou est un chanteur, auteur-compositeur, acteur et producteur musical chinois, né le 18 janvier 1979 à Linkou, Taïwan, Chine.",115,"fr:Jay_Chou","c:5/5d/Jay_Chou_in_Seoul.jpg"],["Q192410",134,"chanteur","Jennifer Hudson","C","Jennifer Hudson, née le 12 septembre 1981 à Chicago, est une chanteuse et actrice américaine.",null,"fr:Jennifer_Hudson","c:e/eb/Jennifer_Hudson_at_MVAAFF_2025.jpg"],["Q40715",135,"chanteur","Jennifer Lopez","E","Jennifer Lopez, née le 24 juillet 1969 à New York, est une actrice, chanteuse, productrice, danseuse et femme d'affaires américaine.",109,"fr:Jennifer_Lopez","c:6/6e/Jennifer_Lopez_at_the_2025_Sundance_Film_Festival_%28cropped_3%29.jpg"],["Q202729",136,"chanteur","Jerry Lee Lewis","C","Jerry Lee Lewis, né le 29 septembre 1935 à Ferriday et mort le 28 octobre 2022 dans le comté de DeSoto, est un chanteur-pianiste américain de rock 'n' roll, rockabilly, gospel, honky tonk, blues et de country.",110,"fr:Jerry_Lee_Lewis","c:e/ef/Jerry_Lee_Lewis_1950s_publicity_photo_cropped_retouched.jpg"],["Q168992",137,"chanteur","Jessica Simpson","C","Jessica Simpson, est une chanteuse, actrice, styliste et personnalité de la télévision américaine, née le 10 juillet 1980 à Abilene, au Texas. Son succès commence en 1999 avec la sortie de son premier single I Wanna Love You Forever qui atteint le Top 5 du Billboard Hot 100. Son premier album intitulé Sweet Kisses est certifié double disque de platine aux États-Unis et s'est vendu à plus de 4 millions de copies à travers le monde entier.",116,"fr:Jessica_Simpson","c:f/f2/Jessica_Simpson_Joining_Forces_with_the_Rockies_April_2011_%28cropped%29.jpg"],["Q44301",138,"chanteur","Jim Morrison","PC","James Morrison, dit Jim Morrison, né le 8 décembre 1943 à Melbourne et mort le 3 juillet 1971 à Paris, est un chanteur et poète américain, cofondateur du groupe de rock américain The Doors, dont il fut membre de 1965 à sa mort.",118,"fr:Jim_Morrison","c:7/7f/Jim_Morrison_1969.JPG"],["Q131725",139,"chanteur","Joan Baez","C","Joan Baez, née le 9 janvier 1941 à Staten Island, est une auteure-compositrice-interprète américaine de musique folk.",null,"fr:Joan_Baez","c:4/4d/Joan_Baez_at_The_Egg_%28Albany%2C_NY%29%2C_March_2016_%28cropped%29.jpg"],["Q190076",140,"chanteur","Joe Cocker","C","John Robert Cocker, dit Joe Cocker, né le 20 mai 1944 à Sheffield et mort le 22 décembre 2014 à Crawford, est un chanteur de blues-rock britannique, et dans une moindre mesure, acteur et compositeur.",112,"fr:Joe_Cocker","c:6/6c/Joe_Cocker_-_Festival_du_Bout_du_Monde_2013_-_050_%28cropped%29.jpg"],["Q105460",141,"chanteur","John Denver","R","Henry John Deutschendorf, Jr., dit John Denver, né le 31 décembre 1943 à Roswell et mort le 12 octobre 1997 dans la baie de Monterey, est un chanteur américain, également compositeur, musicien et acteur.",115,"fr:John_Denver","c:b/b0/John_Denver_1975.JPG"],["Q1203",142,"chanteur","John Lennon","L","John Lennon, né le 9 octobre 1940 à Liverpool et mort assassiné le 8 décembre 1980 à New York, est un auteur-compositeur-interprète, guitariste, multi-instrumentiste, écrivain et militant pacifiste britannique.",101,"fr:John_Lennon","c:8/85/John_Lennon_%22Walls_and_Bridges%22_1974_press_photo_2_%28color%29_%28cropped%29.jpg"],["Q106662",143,"chanteur","John Lydon","C","John Joseph Lydon, dit Johnny Rotten, né à Londres le 31 janvier 1956, est un musicien britannique, chanteur du groupe punk emblématique les Sex Pistols, formé fin 1975, puis fondateur du groupe Public Image Limited en 1978.",118,"fr:John_Lydon","c:4/4e/John_Lydon_-_2010.jpg"],["Q42775",144,"chanteur","Johnny Cash","R","J. R. Cash, dit Johnny Cash, né le 26 février 1932 à Kingsland et mort le 12 septembre 2003 à Nashville, est un chanteur, acteur, guitariste et auteur-compositeur de musique country américain qui a également pratiqué les styles rock 'n' roll, rockabilly, blues, folk ou encore gospel.","J.","fr:Johnny_Cash","c:f/f2/JohnnyCash1969.jpg"],["Q150916",145,"chanteur","Jon Bon Jovi","R","John Bongiovi, dit Jon Bon Jovi, est un auteur-compositeur-interprète, producteur, philanthrope et acteur américain, né le 2 mars 1962 à Perth Amboy. Il est principalement connu comme étant le fondateur et leader du groupe de rock Bon Jovi, formé en 1983.",119,"fr:Jon_Bon_Jovi","c:4/49/Jon_Bon_Jovi_at_the_2009_Tribeca_Film_Festival_3.jpg",{"cats":["chanteurs_int","groupes"]}],["Q205721",146,"chanteur","Joni Mitchell","PC","Roberta Joan Anderson, dite Joni Mitchell, est une autrice-compositrice-interprète, musicienne, chanteuse et peintre canado-américaine née le 7 novembre 1943 à Fort Macleod.",116,"fr:Joni_Mitchell","c:a/aa/Joni_Mitchell_1983.jpg"],["Q122003",148,"chanteur","Julio Iglesias","PC","Julio Iglesias, né le 23 septembre 1943 à Madrid, est un chanteur, compositeur, musicien, footballeur et homme d’affaires espagnol.",110,"fr:Julio_Iglesias","c:e/ef/Julio_Iglesias09.jpg"],["Q34086",149,"chanteur","Justin Bieber","L","Justin Bieber, né le 1er mars 1994 à London, est un auteur-compositeur-interprète, danseur, musicien et acteur canadien.",null,"fr:Justin_Bieber","c:6/6c/P20260719DT-1213_President_Donald_J._Trump_and_First_Lady_Melania_Trump_attend_the_FIFA_World_Cup_Final_%28cropped_2%29.jpg"],["Q15935",150,"chanteur","Kanye West","E","Ye depuis 2021, anciennement Kanye West, né le 8 juin 1977 à Atlanta, est un rappeur, chanteur, compositeur, réalisateur artistique, designer et directeur artistique américain originaire de Chicago, dans l'Illinois. Il est l'une des figures les plus importantes du hip-hop et est connu pour son style musical varié ainsi que ses commentaires culturels et politiques polarisants.",108,"fr:Kanye_West","c:2/21/Kanye_West_at_the_Met_Gala_in_2019.png"],["Q22001324",151,"chanteur","Karol G","PC","Karol G, de son vrai nom Carolina Giraldo Navarro, née le 14 février 1991 à Medellín, est une chanteuse colombienne de latin trap et de reggaeton, produite par le label Universal Music Latin Entertainment.",118,"fr:Karol_G","c:c/cb/2023-11-16_Gala_de_los_Latin_Grammy%2C_15.jpg"],["Q636",152,"chanteur","Kate Bush","PC","Catherine Bush, dite Kate Bush, née le 30 juillet 1958 à Bexleyheath, est une auteure, compositrice, chanteuse, danseuse, musicienne multi-instrumentiste et productrice britannique.",111,"fr:Kate_Bush","c:d/df/Kate_Bush_1985_Publicity_Photo.jpg"],["Q42493",153,"chanteur","Katy Perry","E","Katheryn Hudson, dite Katy Perry, est une auteure-compositrice-interprète américaine de musique pop et dance, née le 25 octobre 1984 à Santa Barbara, en Californie.",119,"fr:Katy_Perry","c:a/a1/Katy_Perry_2026_Tribeca_Film_Festival_%28cropped_1%29.jpg"],["Q189599",154,"chanteur","Keith Richards","PC","Keith Richards, né le 18 décembre 1943 à Dartford dans le Kent, est un musicien, auteur-compositeur, guitariste britannique, cofondateur, en 1962, avec Mick Jagger, Brian Jones et Ian Stewart, du groupe rock The Rolling Stones. Avec Mick Jagger, au sein d'un partenariat qu'ils ont baptisé The Glimmer Twins, il est le compositeur de la grande majorité du répertoire original du groupe. Il est aussi acteur, ayant notamment joué le père de Jack Sparrow dans deux films de la série Pirates des Caraïbes.",111,"fr:Keith_Richards","c:9/97/Keith_Richards_Photo_Jerzy_Bednarski.jpg"],["Q483507",155,"chanteur","Kelly Clarkson","E","Kelly Brianne Clarkson, née le 24 avril 1982 à Fort Worth, est une chanteuse américaine. Elle fait ses débuts chez RCA Records après avoir remporté la première saison de l’émission American Idol aux États-Unis. En 2017, elle compte un total de six albums studio dont le dernier, Piece by Piece, est sorti le 3 mars 2015.","Kelly Brianne Clarkson, née le 24 avril 1982 à Fort Worth, est une chanteuse américaine.","fr:Kelly_Clarkson","c:1/14/Kelly_Clarkson_2018_DoD_Warrior_Games_Opening_Ceremony_11.jpg"],["Q130798",156,"chanteur","Kendrick Lamar","PC","Kendrick Lamar né le 17 juin 1987 à Compton, est un rappeur, chanteur, parolier, réalisateur artistique et acteur américain. Souvent considéré comme l'un des plus grands rappeurs de tous les temps, il est le seul musicien, en dehors des genres classique et jazz, à avoir reçu le prix Pulitzer de musique. Les critiques estiment généralement que son infusion régulière de critiques politiques et de commentaires sociaux a influencé l'émergence d'une conscience sociale au sein de sa génération.",113,"fr:Kendrick_Lamar","c:3/32/Pulitzer2018-portraits-kendrick-lamar.jpg"],["Q217160",157,"chanteur","Kenny Rogers","PC","Kenny Rogers, né Kenneth Donald Rogers le 21 août 1938 à Houston et mort le 20 mars 2020 à Sandy Springs, est un acteur, chanteur notamment de musique country et compositeur américain.",112,"fr:Kenny_Rogers","c:8/8c/KennyRogers.jpg"],["Q33605",158,"chanteur","Kesha","C","Kesha, de son nom complet Kesha Sebert, née le 1er mars 1987 à Los Angeles, est une chanteuse, rappeuse et danseuse américaine.",115,"fr:Kesha","c:f/f6/Kesha_au_Z%C3%A9nith_de_Paris_en_2026.jpg"],["Q208681",159,"chanteur","Kris Kristofferson","PC","Kris Kristofferson, né le 22 juin 1936 à Brownsville et mort le 28 septembre 2024 à Maui, est un chanteur et acteur américain.",115,"fr:Kris_Kristofferson","c:d/d2/Kris_Kristofferson_SXSW_2006_crop.jpg"],["Q8446",160,"chanteur","Kurt Cobain","R","Kurt Cobain, né le 20 février 1967 à Aberdeen et mort entre le 2 et le 5 avril 1994 à Seattle, est un musicien et auteur-compositeur-interprète américain.",113,"fr:Kurt_Cobain","c:1/1e/Photo_of_Kurt_Cobain_from_US_Embassy_in_Bern.jpg",{"cats":["chanteurs_int","groupes"]}],["Q11998",161,"chanteur","Kylie Minogue","R","Kylie Minogue, née le 28 mai 1968 à Melbourne, est une chanteuse, compositrice et actrice australo-britannique.",null,"fr:Kylie_Minogue","c:6/62/KylieMinogue-byPhilipRomano.jpg",{"cats":["chanteurs_int","lgbt"]}],["Q19848",162,"chanteur","Lady Gaga","E","Lady Gaga, de son vrai nom Stefani Joanne Angelina Germanotta, née le 28 mars 1986 à New York, est une chanteuse, auteure-compositrice-interprète, productrice et actrice américaine. Artiste majeure de la culture populaire du XXIe siècle, elle se distingue par ses transformations artistiques, son approche de la performance et sa polyvalence musicale, faisant d'elle l'une des artistes les plus marquantes de sa génération.",113,"fr:Lady_Gaga","c:8/85/Lady_Gaga_at_Mayhem_Requiem_premiere_2_%28cropped_2%29.png",{"cats":["chanteurs_int","lgbt"]}],["Q37150",163,"chanteur","Lana Del Rey","E","Elizabeth Woolridge Grant, dite Lana Del Rey, née le 21 juin 1985 à New York, est une autrice-compositrice-interprète et poétesse américaine. À travers ses chansons, elle explore les thèmes de la tristesse, de la romance tragique, du glamour et de la mélancolie, puisant ses références dans la littérature et la culture pop, en particulier dans l'Americana des années 1950 et 1960.",117,"fr:Lana_Del_Rey","c:f/f9/Lana_Del_Rey_at_KROQ_Weenie_Roast_2017_%28cropped%29.jpg"],["Q309926",164,"chanteur","Lemmy Kilmister","C","Ian Fraser Kilmister, dit Lemmy Kilmister, né le 24 décembre 1945 à Burslem et mort le 28 décembre 2015 à Los Angeles, est un musicien britannique, célèbre pour avoir été le fondateur, bassiste, chanteur, parolier principal et seul membre permanent du groupe de heavy metal Motörhead jusqu'à sa mort, et pour avoir été membre du groupe de space rock Hawkwind.",118,"fr:Lemmy_Kilmister","c:8/84/Lemmy-02.jpg",{"cats":["chanteurs_int","groupes"]}],["Q7013",165,"chanteur","Lena Meyer-Landrut","C","Lena Meyer-Landrut, de son vrai nom Lena Johanna Therese Meyer-Landrut ou simplement Lena, née le 23 mai 1991 à Hanovre, est une auteure-compositrice-interprète et chanteuse allemande.",111,"fr:Lena_Meyer-Landrut","c:e/e3/MJK_67923_Lena_Meyer-Landrut_%28Berlinale_2020%29.jpg"],["Q180224",166,"chanteur","Lenny Kravitz","PC","Lenny Kravitz, né le 26 mai 1964 à New York, est un auteur-compositeur-interprète, musicien, producteur et acteur américain.",113,"fr:Lenny_Kravitz","c:b/b7/Untold_2024_-_Lenny_Kravitz_57_%28cropped%29.jpg"],["Q1276",167,"chanteur","Leonard Cohen","PC","Leonard Cohen /leɔnaʁ kɔˈɛn/, né le 21 septembre 1934 à Westmount et mort le 7 novembre 2016 à Los Angeles, est un auteur-compositeur-interprète, musicien, poète, romancier et peintre québécois.",114,"fr:Leonard_Cohen","c:b/b4/Leonard_Cohen%2C_1988_01.jpg"],["Q313596",168,"chanteur","Leslie Cheung","C","Leslie Cheung, né le 12 septembre 1956 à Hong Kong et mort le 1er avril 2003 à Hong Kong, est un chanteur et acteur hongkongais.",115,"fr:Leslie_Cheung","c:b/bb/Leslie_Cheung_in_Madame_Tussauds_Hong_Kong_%28cropped%29.jpg"],["Q42315001",169,"chanteur","Lewis Capaldi","C","Lewis Capaldi est un chanteur, musicien et auteur-compositeur-interprète écossais, né le 7 octobre 1996 à Glasgow.",null,"fr:Lewis_Capaldi","c:1/17/Lewis_Capaldi-8107-2.jpg"],["Q216708",170,"chanteur","Liam Gallagher","R","William John Paul Gallagher, dit Liam Gallagher, est un chanteur et musicien britannique d'origine irlandaise, né le 21 septembre 1972 à Longsight, Manchester. Il est le chanteur principal du groupe de rock Oasis, de sa formation en 1991 jusqu'à sa dissolution en 2009. Le groupe annonce sa reformation le 27 août 2024.",119,"fr:Liam_Gallagher","c:4/48/Liam_Gallagher2.jpg"],["Q2756349",171,"chanteur","Liam Payne","R","Liam Payne, né le 29 août 1993 à Wolverhampton et mort le 16 octobre 2024 à Buenos Aires, est un chanteur britannique. Il est surtout connu comme membre du boys band One Direction.","Liam Payne, né le 29 août 1993 à Wolverhampton et mort le 16 octobre 2024 à Buenos Aires, est un chanteur britannique.","fr:Liam_Payne","c:0/07/Liam_Payne_for_UNICEF_2023.png"],["Q15615",172,"chanteur","Lil Wayne","PC","Lil Wayne, de son vrai nom Dwayne Michael Carter Jr., est un rappeur, chanteur, auteur-compositeur, producteur et entrepreneur américain. En 1991, à l'âge de neuf ans, Lil Wayne se joint à Cash Money Records en tant que plus jeune membre du label, et membre du duo The B.G.'z, aux côtés du rappeur Lil' Doogie. En 1996, Lil Wayne forme le groupe de hip-hop, les Hot Boys, avec ses collègues de Cash Money Juvenile, Young Turk et Lil' Doogie. Les Hot Boys se lancent avec l'album Get It How U Live!, la même année.",113,"fr:Lil_Wayne","c:1/12/Lil_Wayne_Feb._2020.jpg"],["Q58735",173,"chanteur","Lily Allen","PC","Lily Allen, née le 2 mai 1985 à Hammersmith, à Londres, est une chanteuse, musicienne et actrice britannique. Elle est la fille de l'acteur Keith Allen et de la productrice de films Alison Owen. Allen quitte l'école à 15 ans afin d'améliorer ses talents vocaux.","Lily Allen, née le 2 mai 1985 à Hammersmith, à Londres, est une chanteuse, musicienne et actrice britannique.","fr:Lily_Allen","c:1/10/El_Rey_Theatre_-_Lily_Allen_04_25_2018_-4_%2828125957447%29_%28cropped%29.jpg"],["Q26695",174,"chanteur","Lionel Richie","C","Lionel Richie né le 20 juin 1949 à Tuskegee, en Alabama, est un chanteur, musicien et acteur américain.",null,"fr:Lionel_Richie","c:d/d6/Lionel_Richie_2019_b.jpg"],["Q82222",175,"chanteur","Little Richard","C","Little Richard — nom de scène de Richard Wayne Penniman, né le 5 décembre 1932 à Macon et mort le 9 mai 2020 à Tullahoma — est un pianiste, auteur-compositeur-interprète et acteur américain. Il est l'un des pionniers du rock 'n' roll dans les années 1950.",110,"fr:Little_Richard","c:1/16/Little_Richard_in_2007.jpg"],["Q13476175",176,"chanteur","Lorde","C","Ella Marija Lani Yelich-O'Connor, dite Lorde, née le 7 novembre 1996 à Auckland, est une auteure-compositrice-interprète et productrice néozélando-croate.",88,"fr:Lorde","c:3/30/Lorde_Glasto2025-9_%28cropped%29.jpg"],["Q189080",177,"chanteur","Lou Reed","C","Lewis Alan Reed plus connu sous le nom de Lou Reed, né le 2 mars 1942 à Brooklyn et mort le 27 octobre 2013 à East Hampton, est un auteur-compositeur-interprète américain connu pour avoir été le leader du groupe The Velvet Underground.",114,"fr:Lou_Reed","c:3/3d/Lou_Reed_at_the_Hop_Farm_Music_Festival.jpg"],["Q1779",178,"chanteur","Louis Armstrong","C","Louis Armstrong (prononcé en anglais:; surnommé « Dippermouth », « Satchmo », « Satch » ou « Pops ») né le 4 août 1901 à La Nouvelle-Orléans et mort le 6 juillet 1971 à New York, est un musicien et chanteur de jazz afro-américain, considéré comme un des jazzmen les plus emblématiques de l'histoire du jazz.",118,"fr:Louis_Armstrong","c:1/16/Louis_Armstrong_in_Color_%28restored%29.jpg"],["Q3624971",179,"chanteur","Louis Tomlinson","C","Louis Tomlinson, le 24 décembre 1991 à Doncaster en Angleterre, est un chanteur et auteur-compositeur britannique.",null,"fr:Louis_Tomlinson","c:6/6a/Louis_Tomlinson_November_2014.jpg"],["Q37615",180,"chanteur","Luciano Pavarotti","PC","Luciano Pavarotti, né le 12 octobre 1935 à Modène et mort le 6 septembre 2007 dans la même ville, est un ténor italien.",null,"fr:Luciano_Pavarotti","c:d/d9/Luciano_Pavarotti_in_Saint_Petersburg.jpg"],["Q1744",181,"chanteur","Madonna","L","Madonna, mononyme de Madonna Louise Ciccone, née le 16 août 1958 à Bay City, est une autrice-compositrice-interprète, danseuse, actrice, productrice de cinéma, réalisatrice et femme d'affaires américaine. Considérée comme l'une des plus grandes stars internationales depuis les années 1980, elle est souvent citée comme une influence majeure sur de nombreux artistes du XXIe siècle.",117,"fr:Madonna","c:3/3c/MadonnaO2171023_%285_of_133%29_%2853270847219%29_%28cropped%29.jpg",{"cats":["chanteurs_int","lgbt"]}],["Q17517186",182,"chanteur","Maluma","C","Maluma, de son vrai nom Juan Luis Londoño Arias, né le 28 janvier 1994 à Medellín, dans la région andine, en Colombie, est un auteur-compositeur-interprète de reggaeton, guitariste colombien et acteur, labellisé chez Sony Music Entertainment. Maluma devient l'un des artistes les plus influents sur la scène latine, acquiert une popularité mondiale à compter de 2016 à l'instar de ses confrères J. Balvin, Bad Bunny ou encore Daddy Yankee, et participe à l'expansion du reggaeton.",118,"fr:Maluma","c:2/29/Maluma_attends_the_2026_American_Music_Awards_at_MGM_Grand_Garden_Arena_on_May_25%2C_2026_in_Las_Vegas%2C_Nevada.jpg"],["Q187832",183,"chanteur","Mandy Moore","PC","Amanda Moore, dite Mandy Moore, est une auteur-compositrice-interprète, actrice, réalisatrice et styliste américaine, née le 10 avril 1984 à Nashua. Elle s'est fait connaître en 1999 grâce au single pop Candy issu de son premier album So Real, certifié disque de platine. Durant la décennie, elle sort les albums I Wanna Be with You en 2000 et Mandy Moore en 2001, qui sont certifiés disques d'or.",117,"fr:Mandy_Moore","c:5/5e/Mandy_Moore_%2840733718782%29.jpg"],["Q26625",184,"chanteur","Marc Anthony","C","Marco Antonio Muñiz, dit Marc Anthony, né le 16 septembre 1968 à New York, est un chanteur auteur-interprète américano-portoricain, populaire dans l'ensemble des Amériques pour ses musiques salsa et pop latino.",108,"fr:Marc_Anthony","c:6/66/Interview_with_Marc_Anthony_%28cropped%29.png"],["Q41076",185,"chanteur","Mariah Carey","R","Mariah Carey, née le 27 mars 1969 à Huntington, est une auteure-compositrice-interprète, productrice de musique et actrice américaine. Elle est révélée en 1990 par son premier album Mariah Carey porté par la chanson Vision of Love qui fait d'elle une artiste reconnue dans son pays et à l'international.",114,"fr:Mariah_Carey","c:9/94/Mariah_Carey_Library_of_Congress_2023_2_%28cropped%2902.jpg"],["Q186327",186,"chanteur","Marilyn Manson","R","Marilyn Manson, de son vrai nom Brian Hugh Warner, né le 5 janvier 1969 à Canton, est un musicien, chanteur rock, peintre, poète, acteur et plasticien américain. Il est mondialement connu pour être le leader du groupe de metal industriel Marilyn Manson, portant son nom. Son nom de scène est une référence à l'actrice Marilyn Monroe et au gourou et criminel américain Charles Manson.",113,"fr:Marilyn_Manson","c:1/1d/Marilyn_Manson_Live_in_Moscow_2012.JPG"],["Q185343",187,"chanteur","Mark Knopfler","PC","Mark Knopfler (prononcé en anglais: /ˈnɒflə/) est un auteur, compositeur, guitariste et chanteur britannique né le 12 août 1949 à Glasgow.",117,"fr:Mark_Knopfler","c:e/ec/Pensa-MK-2.jpg"],["Q189758",188,"chanteur","Marvin Gaye","PC","Marvin Gaye, né le 2 avril 1939 à Washington et mort le 1er avril 1984 à Los Angeles, est un chanteur et auteur-compositeur américain. Il rencontre un grand succès dans les années 1960 en tant qu'un des chanteurs vedettes du label Motown et publie en solo ou en duo plusieurs classiques de la musique populaire du XXe siècle.",104,"fr:Marvin_Gaye","c:8/88/Marvin_Gaye_1966.jpg"],["Q153694",189,"chanteur","Michael Bublé","C","Michael Bublé, né le 9 septembre 1975 à Burnaby en Colombie-Britannique, est un chanteur de jazz canadien d'origine italienne, de soul, de rock et de pop, mais aussi un acteur. Il possède la double citoyenneté canadienne et italienne depuis 2005.",115,"fr:Michael_Bublé","c:f/f8/Michael_Bubl%C3%A9.jpg"],["Q2831",190,"chanteur","Michael Jackson","M","Michael Jackson, né le 29 août 1958 à Gary et mort le 25 juin 2009 à Los Angeles, est un auteur-compositeur-interprète, danseur-chorégraphe et acteur américain. Célébrité planétaire, artiste le plus récompensé de l'histoire de la musique, il est une figure principale de l'histoire de l'industrie du spectacle et l'une des icônes culturelles internationales majeures du xxe siècle.",119,"fr:Michael_Jackson","c:4/45/Michael_Jackson_with_Grammy_Awards_in_1984.jpg"],["Q128121",191,"chanteur","Mick Jagger","E","Michael Philip Jagger dit Mick Jagger, né le 26 juillet 1943 à Dartford, est un auteur-compositeur-interprète, musicien et acteur britannique, cofondateur en 1962, avec Brian Jones, Keith Richards, Dick Taylor, Mick Avory et Ian Stewart du célèbre groupe de rock britannique The Rolling Stones, dont la formation se stabilise l'année suivante avec l'arrivée de Charlie Watts à la batterie qui a remplacé Mick Avory.",119,"fr:Mick_Jagger","c:a/a8/Mick_Jagger_onstage_in_Warsaw_2018.jpg"],["Q19201",192,"chanteur","Mike Shinoda","C","Michael « Mike » Kenji Shinoda, né le 11 février 1977 à Agoura Hills, est un auteur-compositeur-interprète, rappeur, musicien et producteur américain.",116,"fr:Mike_Shinoda","c:d/d1/Linkin_Park_-_From_Zero_Lead_Press_Photo_-_James_Minchin_III_%28Mike_Shinoda%29.jpg",{"cats":["chanteurs_int","groupes"]}],["Q4235",193,"chanteur","Miley Cyrus","E","Miley parfois appelée par son nom complet Miley Cyrus, née le 23 novembre 1992 à Franklin dans le Tennessee, est une auteure-compositrice-interprète, musicienne, productrice et actrice américaine. Elle rencontre la célébrité à l'adolescence en incarnant Miley Stewart / Hannah Montana dans une série de Disney Channel, Hannah Montana, où elle joue avec son père, le chanteur de country Billy Ray Cyrus, entre 2006 et 2011.",116,"fr:Miley_Cyrus","c:d/d2/Miley_Cyrus_2025.png"],["Q202246",194,"chanteur","Morrissey","PC","Steven Patrick Morrissey, dit Morrissey, parfois abrégé en « Moz », né le 22 mai 1959 à Davyhulme, dans le district métropolitain de Trafford, est un chanteur, parolier et auteur britannique.",115,"fr:Morrissey","c:4/44/Morrissey-Alexander-Film-.jpg"],["Q154662",195,"chanteur","Nana Mouskouri","C","Nana Mouskouri, née le 13 octobre 1934 à La Canée, est une chanteuse et femme politique grecque.",null,"fr:Nana_Mouskouri","c:2/22/Nana_Mouskouri_1966.jpg"],["Q137042",196,"chanteur","Nat King Cole","C","Nat King Cole est un chanteur et pianiste américain de jazz et de rhythm and blues né le 17 mars 1919 à Montgomery et mort le 15 février 1965 à Santa Monica.",117,"fr:Nat_King_Cole","c:1/15/The_Nat_King_Cole_Show_premiere_1956.JPG"],["Q488353",197,"chanteur","Natalie Imbruglia","C","Natalie Imbruglia est une chanteuse et actrice australo-britannique d'origine italienne, née Natalia Imbruglia, le 4 février 1975 à Sydney.",116,"fr:Natalie_Imbruglia","c:1/1f/Natalie_Imbruglia_Cannes.jpg"],["Q633",198,"chanteur","Neil Young","PC","Neil Percival Young, né le 12 novembre 1945 à Toronto, est un auteur-compositeur, chanteur et guitariste de folk, country et rock canado-américain. L'apogée de sa popularité se situe au début des années 1970 avec les albums After the Gold Rush et Harvest et son rôle dans le groupe Crosby, Stills, Nash and Young.",113,"fr:Neil_Young","c:5/5d/DesertTrip2016-140_%2829685063324%29_%28cropped%29.jpg"],["Q80424",199,"chanteur","Nelly Furtado","C","Nelly Furtado, née le 2 décembre 1978 à Victoria, en Colombie-Britannique, est une autrice-compositrice-interprète, musicienne et actrice canado-portugaise. Furtado se fait d'abord connaître avec son premier album studio inspiré du trip hop, Whoa, Nelly!, qui remporte un succès critique et commercial, et donne naissance à deux singles classés dans le top 10 du Billboard Hot 100, I'm Like a Bird et Turn Off the Light.",115,"fr:Nelly_Furtado","c:a/aa/Nelly_Furtado_at_Radio_Regenbogen_Award_2017_%286%29.jpg"],["Q775231",200,"chanteur","Niall Horan","C","Niall Horan, né le 13 septembre 1993 à Mullingar, est un chanteur et musicien irlandais. Il est membre du boys band One Direction, formé en 2010 dans l'émission X-Factor.","Niall Horan, né le 13 septembre 1993 à Mullingar, est un chanteur et musicien irlandais.","fr:Niall_Horan","c:1/11/President_Biden_celebrates_2023_Saint_Patrick%27s_Day_at_the_White_House_%284%29_%28cropped%29.jpg"],["Q192668",201,"chanteur","Nick Cave","C","Nicholas Edward Cave, dit Nick Cave, AO, né le 22 septembre 1957 à Warracknabeal, en Australie, est un artiste pluridisciplinaire australien ayant acquis sa notoriété en tant que chanteur, auteur et compositeur du groupe Nick Cave and the Bad Seeds.",110,"fr:Nick_Cave","c:f/f4/Nick_Cave_in_New_York_City_2009_portrait_by_DS.jpg"],["Q201656",202,"chanteur","Nick Jonas","PC","Nicholas Jonas, dit Nick Jonas, né le 16 septembre 1992 à Dallas, est auteur-compositeur-interprète et acteur américain, qui s'est fait connaître grâce à la série télévisée Jonas mettant en scène le groupe Jonas Brothers auquel il appartient avec ses frères Joe et Kevin.",109,"fr:Nick_Jonas","c:f/f5/Nick_Jonas_at_DIFF_2026.jpg"],["Q167696",203,"chanteur","Nicole Scherzinger","R","Nicole Scherzinger, née le 29 juin 1978 à Honolulu, est une chanteuse, danseuse, parolière et actrice américaine.",null,"fr:Nicole_Scherzinger","c:0/09/Nicole_Scherzinger_at_78th_Tony_Awards_01.png"],["Q174957",204,"chanteur","Nina Simone","C","Eunice Kathleen Waymon, dite Nina Simone /ˈni.nə sɪ.ˈmoʊn/, née le 21 février 1933 à Tryon et morte le 21 avril 2003 à Carry-le-Rouet, est une pianiste, chanteuse, compositrice et arrangeuse musicale américaine. Elle fut également militante pour les droits civiques. Elle est considérée, avec Ella Fitzgerald, Sarah Vaughan et Billie Holiday, comme l'une des quatre plus grandes chanteuses de jazz de l'histoire.",118,"fr:Nina_Simone","c:8/83/Nina_Simone_1965_-_restoration1.jpg"],["Q193459",205,"chanteur","Noel Gallagher","PC","Noel Gallagher, né le 29 mai 1967 à Burnage, Manchester, est un multi-instrumentiste et auteur-compositeur-interprète britannique.",117,"fr:Noel_Gallagher","c:9/97/Glastonbury2022_%28235_of_413%29_%2852181386307%29_%28cropped%29.jpg"],["Q549981",206,"chanteur","Norah Jones","C","Norah Jones, née Geethali Norah Jones-Shankar le 30 mars 1979 à New York, est une auteure-compositrice-interprète, musicienne et actrice américaine.",114,"fr:Norah_Jones","c:7/74/NorahJones-byPhilipRomano2.jpg"],["Q185165",207,"chanteur","Olivia Newton-John","R","Olivia Newton-John, née le 26 septembre 1948 à Cambridge et morte le 8 août 2022 en Californie du Sud, est une chanteuse, actrice, productrice et militante australo-britannique. Avec plus de 100 millions de disques vendus à l’échelle mondiale, elle fait partie des artistes ayant vendu le plus de disques de tous les temps. Elle est également l’artiste australienne féminine ayant vendu le plus de disques de l’histoire et est notamment célèbre pour son rôle de Sandy Olsson dans le film Grease sorti en 1978.",110,"fr:Olivia_Newton-John","c:5/5e/Olivia_Newton_John_%286707495311%29_%28cropped_to_look_large%29.jpg"],["Q63243883",208,"chanteur","Olivia Rodrigo","L","Olivia Rodrigo, née le 20 février 2003 à Murrieta, est une auteure-compositrice-interprète, musicienne et actrice américaine.",113,"fr:Olivia_Rodrigo","c:4/42/Olivia_at_the_Unraveled_Tour.jpg"],["Q133151",209,"chanteur","Ozzy Osbourne","E","Ozzy Osbourne est un chanteur britannique de heavy metal, né le 3 décembre 1948 à Marston Green, village près de Birmingham, Midlands de l'Ouest, et mort le 22 juillet 2025 à Jordans, Buckinghamshire. Il est surnommé « The Prince of Darkness » en référence aux frasques de sa vie privée et de ses prestations sur scène. Il est connu à la fois pour sa carrière musicale en solo et comme chanteur au sein de Black Sabbath, l'un des groupes fondateurs du heavy metal et créateur du titre emblématique War Pigs.",112,"fr:Ozzy_Osbourne","c:4/4c/Ozzy_Osbourne_in_1975_%28cropped%29.jpg",{"cats":["chanteurs_int","groupes"]}],["Q557",210,"chanteur","Patti Smith","PC","Patricia Lee Smith dite Patti Smith, née le 30 décembre 1946 à Chicago, est une chanteuse et guitariste punk rock américaine, elle est aussi poétesse, écrivaine, artiste-peintre et photographe.",113,"fr:Patti_Smith","c:a/a2/Patti_Smith_at_the_81st_Venice_International_Film_Festival_in_2024.jpg"],["Q216563",211,"chanteur","Paul Anka","C","Paul Anka, né le 30 juillet 1941 à Ottawa, est un auteur-compositeur-interprète canadien naturalisé américain.",null,"fr:Paul_Anka","c:9/9a/PaulAnka07.jpg"],["Q2599",212,"chanteur","Paul McCartney","M","Paul McCartney (prononcé en anglais:), né le 18 juin 1942 à Liverpool, est un auteur-compositeur-interprète et multi-instrumentiste britannique, jouant aussi bien de la basse et de la contrebasse, de la guitare et du piano, que de la batterie et des percussions.",110,"fr:Paul_McCartney","c:2/22/Paul_McCartney_2021_%28cropped%29.jpg"],["Q4028",213,"chanteur","Paul Simon","PC","Paul Simon, né le 13 octobre 1941 à Newark, dans le New Jersey, est un auteur-compositeur-interprète et musicien américain. Il forme d'abord un duo avec Art Garfunkel, puis continue une carrière soliste.",112,"fr:Paul_Simon_(chanteur)","c:b/b6/Paul_Simon_at_the_9-30_Club_%28b%29.jpg"],["Q185465",214,"chanteur","Paula Abdul","C","Paula Abdul est une chanteuse, danseuse et chorégraphe américano-canado-syrienne, née le 19 juin 1962 à Los Angeles.",null,"fr:Paula_Abdul","c:8/82/PaulaTrip0526.jpg"],["Q175195",215,"chanteur","Peter Gabriel","PC","Peter Gabriel, né le 13 février 1950 à Chobham dans le Surrey, est un auteur-compositeur-interprète et producteur de disques britannique. Chanteur et instrumentiste, il joue de la flûte traversière, du piano, des claviers, des percussions et de la batterie. Il est occasionnellement acteur.",116,"fr:Peter_Gabriel","c:a/a7/Peter_Gabriel_-_Back_To_Front_2014_2_%28cropped%29.jpg"],["Q14313",216,"chanteur","Pharrell Williams","C","Pharrell Williams, ou simplement appelé Pharrell, est un auteur-compositeur-interprète, réalisateur artistique, musicien, styliste, rappeur et producteur américain. Avec Chad Hugo, ils forment le duo de production musicale The Neptunes. Il est également le chanteur et le batteur du groupe N.E.R.D qu'il forme avec Hugo et son ami d'enfance Shay Haley. Son premier single Frontin’ est sorti en 2003 et son premier album solo, In My Mind, en 2006.",111,"fr:Pharrell_Williams","c:4/4f/Pharrell_Williams_2024_%2854133384149%29.jpg"],["Q144622",217,"chanteur","Phil Collins","E","Phil Collins, né le 30 janvier 1951 à Chiswick, est un auteur-compositeur-interprète, acteur et producteur britannique. Connu en tant que batteur et chanteur du groupe Genesis, il a eu une carrière solo prolifique, de 1981 à 1996, qu'il mène en parallèle. C'est également un musicien accompli qui joue de plusieurs instruments: la batterie et les percussions sont ses instruments de base, mais il joue aussi des claviers, de la guitare et de la basse.","Phil Collins, né le 30 janvier 1951 à Chiswick, est un auteur-compositeur-interprète, acteur et producteur britannique.","fr:Phil_Collins","c:8/8f/Phil_Collins%2C_2025_for_%22Eras%22.jpg"],["Q160009",218,"chanteur","Pink","PC","Alecia Moore, dite Pink, née le 8 septembre 1979 à Doylestown, est une chanteuse et actrice américaine. En 2014, elle compte plus de 60 millions d'albums et 75 millions de singles vendus, ainsi que trois Grammy Awards.","Alecia Moore, dite Pink, née le 8 septembre 1979 à Doylestown, est une chanteuse et actrice américaine.","fr:Pink_(chanteuse)","c:7/7f/PinkSpurs160624_%2833_of_156%29_%28cropped%29.jpg"],["Q7542",219,"chanteur","Prince","E","Prince, de son vrai nom Prince Rogers Nelson,, est un auteur-compositeur-interprète, multi-instrumentiste, producteur, danseur et acteur américain. Il a exploré durant sa carrière une grande variété de styles musicaux, de la pop au funk en passant par la soul, le rock ou le RnB. La carrière de Prince démarre en 1978 et sa discographie compte plus de trente albums studio parus en un peu moins de quarante ans.",118,"fr:Prince_(musicien)","c:d/d6/Prince_at_Coachella_%28cropped%29.jpg"],["Q1112005",220,"chanteur","Queen Latifah","E","Queen Latifah, de son vrai nom Dana Elaine Owens, née le 18 mars 1970 à Newark, dans le New Jersey, est une rappeuse, productrice, mannequin, animatrice de télévision et actrice américaine.",117,"fr:Queen_Latifah","c:9/96/Queen_Latifah_by_Gage_Skidmore.jpg"],["Q193645",221,"chanteur","Quincy Jones","PC","Quincy Jones, parfois surnommé « Q », est un trompettiste, arrangeur, compositeur, réalisateur et producteur américain, né le 14 mars 1933 à Chicago et mort le 3 novembre 2024 à Los Angeles.",119,"fr:Quincy_Jones","c:2/20/Quincy_Jones_May_2014.jpg"],["Q273055",222,"chanteur","R. Kelly","PC","R. Kelly, nom de scène de Robert Sylvester Kelly, né le 8 janvier 1967 à Chicago dans l'Illinois, est un chanteur de RnB et de musique soul, producteur et auteur-compositeur américain.","R.","fr:R._Kelly","c:4/46/R._Kelly_mug_shot.jpg"],["Q544387",223,"chanteur","Ray Charles","C","Ray Charles (né le 23 septembre 1930 à Albany et mort le 10 juin 2004 à Beverly Hills) est un chanteur, compositeur, arrangeur et pianiste américain.",116,"fr:Ray_Charles","c:e/e8/Ray_Charles_classic_piano_pose.jpg"],["Q28071144",224,"chanteur","Raye","E","Rachel Agatha Keen, née le 24 octobre 1997 à Londres, connue sous le nom de scène de Raye, est une auteure-compositrice-interprète britannique.",98,"fr:Raye_(chanteuse)","c:1/12/Raye8888.jpg"],["Q229430",225,"chanteur","Reba McEntire","R","Reba McEntire est une chanteuse, actrice, productrice américaine née le 28 mars 1955 à McAlester, dans l'Oklahoma. Elle est principalement connue dans le monde de la musique country depuis le début des années 1980, avec plus de 20 albums studio classés dans les premières places des classements américains.","Reba McEntire est une chanteuse, actrice, productrice américaine née le 28 mars 1955 à McAlester, dans l'Oklahoma.","fr:Reba_McEntire","c:e/e0/Reba_McEntire_by_Gage_Skidmore.jpg"],["Q219237",226,"chanteur","Rick Astley","C","Richard Paul Astley, dit Rick Astley, né le 6 février 1966 à Newton-le-Willows, est un chanteur et auteur-compositeur-interprète britannique.",98,"fr:Rick_Astley","c:e/e5/Rick_Astley-cropped.jpg"],["Q128799",227,"chanteur","Ricky Martin","C","Ricky Martin, de son vrai nom Enrique Martín Morales (, né le 24 décembre 1971 à San Juan, est un chanteur et acteur portoricain, naturalisé espagnol. Ricky Martin est considéré comme le « roi de la pop latino-américaine ». Il a vendu plus de 90 millions d'albums.",116,"fr:Ricky_Martin","c:d/df/Ricky_Martin-4262.jpg"],["Q36844",228,"chanteur","Rihanna","E","Robyn Rihanna Fenty dite Rihanna, est une chanteuse, parolière, actrice, styliste et femme d'affaires barbadienne, née le 20 février 1988 à Saint-Michael.",118,"fr:Rihanna","c:c/c2/Rihanna_Fenty_2018.png"],["Q229760",229,"chanteur","Rita Ora","PC","Rita Ora, est une chanteuse, mannequin et actrice kosovare naturalisé britannique née le 26 novembre 1990 à Pristina.",null,"fr:Rita_Ora","c:5/57/Rita_Ora_performing_at_Car_festival_2025.jpg"],["Q47875",230,"chanteur","Robbie Williams","PC","Robert Peter Williams, dit Robbie Williams, né le 13 février 1974 à Stoke-on-Trent, est un auteur-compositeur-interprète britannique, principalement de pop rock.",90,"fr:Robbie_Williams","c:d/d9/Robbie_Williams_at_the_2024_Toronto_International_Film_Festival_%28cropped%29.jpg"],["Q428223",231,"chanteur","Robert Plant","R","Robert Plant est un chanteur et harmoniciste britannique, né le 20 août 1948 à West Bromwich.",null,"fr:Robert_Plant","c:d/d4/RPlantSavGraceIpswich140324_%285_of_12%29_%2853589044022%29_%28cropped%29.jpg",{"cats":["chanteurs_int","groupes"]}],["Q182655",232,"chanteur","Rod Stewart","PC","Roderick David Stewart, dit Rod Stewart, né le 10 janvier 1945 à Londres, est un chanteur et auteur-compositeur-interprète britannique.",92,"fr:Rod_Stewart","c:f/f7/Rod_Stewart_86.jpg"],["Q15880",233,"chanteur","Roger Taylor","C","Roger Taylor, né le 26 juillet 1949 à King's Lynn, est un musicien, auteur-compositeur-interprète britannique, connu pour sa carrière avec le groupe Queen en tant que batteur.",116,"fr:Roger_Taylor","c:5/5a/Queen_And_Adam_Lambert_-_The_O2_-_Tuesday_12th_December_2017_QueenO2121217-47_%2839066610085%29_Cropped.jpg"],["Q180861",234,"chanteur","Roger Waters","PC","Roger Waters /ˈɹɒd͡ʒə ˈwɔːtəz/, est un auteur-compositeur-interprète britannique né le 6 septembre 1943 à Great Bookham. En 1965, il est un des fondateurs du groupe de rock Pink Floyd, dont il est au départ le bassiste, mais en devient après le départ du chanteur principal et compositeur Syd Barrett, en 1968, le parolier et l'un des chanteurs avec David Gilmour et Richard Wright, ainsi que le leader conceptuel du groupe.","Roger Waters /ˈɹɒd͡ʒə ˈwɔːtəz/, est un auteur-compositeur-interprète britannique né le 6 septembre 1943 à Great Bookham.","fr:Roger_Waters","c:5/50/Roger_Waters_Newport_Folk_Festival_2015.jpg",{"cats":["chanteurs_int","groupes"]}],["Q28843759",235,"chanteur","Rosalía","L","Rosalía, née le 25 septembre 1992 à Sant Esteve Sesrovires, est une auteure-compositrice-interprète, musicienne, productrice et actrice espagnole.",112,"fr:Rosalía","c:4/4e/2023-11-16_Gala_de_los_Latin_Grammy%2C_27_%28cropped%29.jpg"],["Q188426",236,"chanteur","Roy Orbison","C","Roy Kelton Orbison, né le 23 avril 1936 à Vernon, Texas, et mort le 6 décembre 1988 à Hendersonville, Tennessee, est un auteur-compositeur-interprète américain, un pionnier du rock 'n' roll, surnommé « The Big O ».",119,"fr:Roy_Orbison","c:d/d9/Roy_Orbison_1965.jpg"],["Q7396400",237,"chanteur","Sabrina Carpenter","R","Sabrina Carpenter, née le 11 mai 1999 à Quakertown en Pennsylvanie, est une chanteuse, autrice-compositrice-interprète et actrice américaine.",118,"fr:Sabrina_Carpenter","c:6/61/Sabrina_Carpenter_-_O2_Arena_2025_-_086_%28cropped_2%29.jpg"],["Q15123969",238,"chanteur","Sam Smith","C","Samuel Smith, dit Sam Smith, né le 19 mai 1992 à Londres, est un chanteur, auteur, musicien, producteur britannique.",null,"fr:Sam_Smith","c:f/f1/SamSmith-byPhilipRomano.jpg",{"cats":["chanteurs_int","lgbt"]}],["Q216936",239,"chanteur","Sean Combs","E","Sean Combs, né le 4 novembre 1969 à New York, État de New York est un rappeur, chanteur, acteur, danseur, homme d'affaires, producteur de musique et styliste américain. Il devient directeur chez Uptown Records avant de fonder le label Bad Boy Records en 1993.",111,"fr:Sean_Combs","c:7/7c/Sean_Combs_Cannes_2012_%28cropped%29_3.jpg"],["Q23543",240,"chanteur","Selena","PC","Selena Quintanilla-Pérez, simplement dite Selena, est une chanteuse, compositrice, porte-parole, femme d'affaires, mannequin, actrice et créatrice de mode américaine, née le 16 avril 1971 à Lake Jackson et morte assassinée le 31 mars 1995 à Corpus Christi.",114,"fr:Selena_(chanteuse)","c:8/81/Selena_Quintanilla_1987_%28cropped%29.jpg"],["Q83287",241,"chanteur","Selena Gomez","R","Selena Gomez, née le 22 juillet 1992 à Grand Prairie, au Texas, est une auteure-compositrice-interprète, actrice, productrice et entrepreneuse américaine.",113,"fr:Selena_Gomez","c:f/fb/Selena_Gomez_at_the_2024_Toronto_International_Film_Festival_3_%28Cropped%29.jpg"],["Q486063",242,"chanteur","Serj Tankian","C","Serj Tankian, né le 21 août 1967 à Beyrouth, est un chanteur, auteur-compositeur, musicien, producteur musical, peintre et poète américano-arménien, surtout connu en tant que membre du groupe américain de metal System of a Down.",119,"fr:Serj_Tankian","c:3/3e/Serj_Tankian_in_Artsakh_%28cropped%29.jpg",{"cats":["chanteurs_int","groupes"]}],["Q34424",243,"chanteur","Shakira","L","Shakira, de son nom complet Shakira Isabel Mebarak Ripoll, est une auteure-compositrice-interprète colombienne, née le 2 février 1977 à Barranquilla en Colombie.",118,"fr:Shakira","c:b/b8/2023-11-16_Gala_de_los_Latin_Grammy%2C_03_%28cropped%2902.jpg"],["Q131433",244,"chanteur","Shania Twain","PC","Eilleen Edwards, dite Shania Twain, née le 28 août 1965 à Windsor, est une chanteuse de country canadienne.",null,"fr:Shania_Twain","c:d/d9/Shania_Twain_Glaston2024_2806_300624_%2833_of_173%29_%2853838111535%29_%28cropped%29.jpg"],["Q17198340",245,"chanteur","Shawn Mendes","C","Shawn Mendes, né le 8 août 1998 à Pickering, est un auteur-compositeur-interprète, musicien, acteur, mannequin et producteur canadien.",113,"fr:Shawn_Mendes","c:a/a4/191125_Shawn_Mendes_at_the_2019_American_Music_Awards.png"],["Q181484",246,"chanteur","Sia","PC","Sia, mononyme de Sia Furler, née le 18 décembre 1975 à Adélaïde, en Australie-Méridionale, est une auteure-compositrice-interprète, réalisatrice, scénariste et productrice australienne. Elle débute au sein du groupe australien Crisp durant les années 1990 et contribue à trois albums du groupe britannique Zero 7. Depuis 2000, elle mène une carrière solo et collabore avec d'autres artistes.",98,"fr:Sia_(chanteuse)","c:6/6e/Sia_Seattle_%28cropped%29.jpg"],["Q193982",247,"chanteur","Sinéad O'Connor","R","Sinéad O'Connor, devenue Magda Davitt en 2017 puis Shuhada' Davitt ou Shuhada' Sadaqat en 2018, née le 8 décembre 1966 à Dublin et morte le 26 juillet 2023 à Londres, est une auteure-compositrice-interprète et musicienne irlandaise.",118,"fr:Sinéad_O'Connor","c:2/2f/Sinead_O%27Connor_%2814828633401%29_%28cropped%29.jpg"],["Q6096",248,"chanteur","Snoop Dogg","PC","Snoop Dogg, né Calvin Cordozar Broadus, Jr. le 20 octobre 1971 à Long Beach Californie, est un rappeur, chanteur, producteur musical et acteur américain. Sa popularité commence comme MC dans le milieu du rap West Coast, devenant l'un des protégés du rappeur-producteur Dr. Dre. Sa mère le surnomme « Snoopy », en raison de sa ressemblance avec le célèbre chien, personnage principal du comic strip Peanuts; il adopte par la suite le nom de Snoop Doggy Dogg lorsqu'il se lance dans la musique.","Snoop Dogg, né Calvin Cordozar Broadus, Jr.","fr:Snoop_Dogg","c:1/17/Snoop_Dogg_2019_by_Glenn_Francis.jpg"],["Q194045",249,"chanteur","Steven Tyler","PC","Steven Victor Tallarico, dit Steven Tyler, né le 26 mars 1948 à Yonkers, est un chanteur et musicien américain. Il est le chanteur du groupe hard rock américain Aerosmith. Il y joue également des claviers et de l'harmonica.","Steven Victor Tallarico, dit Steven Tyler, né le 26 mars 1948 à Yonkers, est un chanteur et musicien américain.","fr:Steven_Tyler","c:4/48/Steven_Tyler_performing.jpg",{"cats":["chanteurs_int","groupes"]}],["Q714",250,"chanteur","Stevie Wonder","E","Stevie Wonder, de son vrai nom Stevland Judkins, est un auteur-compositeur-interprète, producteur et multi-instrumentiste américain, également naturalisé ghanéen en 2024, né le 13 mai 1950 à Saginaw, aveugle depuis sa petite enfance. Il est considéré comme l'un des plus grands artistes américains de la seconde moitié du XXe siècle et possède une des carrières les plus prolifiques de la musique populaire américaine.",100,"fr:Stevie_Wonder","c:4/41/Stevie_Wonder_June_30%2C_Montreal.jpg"],["Q483203",251,"chanteur","Sting","R","Sting, nom de scène de Gordon Sumner, est un auteur-compositeur-interprète, musicien, producteur et acteur britannique, né le 2 octobre 1951 à Wallsend. Multi-instrumentiste, il joue notamment de la basse, de la guitare et des claviers.",119,"fr:Sting","c:7/7f/Sting_at_2026_Montreux_Jazz_Festival-12-CA.jpg"],["Q83493",252,"chanteur","Susan Boyle","C","Susan Boyle, née le 1er avril 1961 dans le West Lothian en Écosse, est une chanteuse britannique qui s'est fait connaître par sa participation à l'émission de télévision Britain's Got Talent en 2009. Son album sorti la même année, I Dreamed a Dream, est un des plus grands succès de la décennie et s'est écoulé à 10 300 000 exemplaires.",111,"fr:Susan_Boyle","c:6/66/Susan_Boyle.jpg"],["Q173061",253,"chanteur","Syd Barrett","PC","Roger Keith Barrett, dit Syd Barrett, est un auteur-compositeur-interprète britannique né le 6 janvier 1946 à Cambridge où il est mort le 7 juillet 2006. Il est le cofondateur et le leader du groupe Pink Floyd de ses débuts à son éviction en 1968.",119,"fr:Syd_Barrett","c:f/fb/Pink_Floyd_1967_with_Syd_Barrett_%28higher_quality%29_%28cropped%29_%28b%29.jpg"],["Q16210722",254,"chanteur","SZA","C","SZA, de son vrai nom Solána Imani Rowe, née le 8 novembre 1989 à Saint-Louis, dans l'État du Missouri, est une auteure-compositrice-interprète de R&B américaine. Grandissant à Maplewood, dans le New Jersey, SZA autoproduit son premier EP en octobre 2012, SEE.SZA.Run, puis son deuxième EP, intitulé S, en avril 2013. En juillet 2013, elle signe chez le label indépendant américain Top Dawg Entertainment. En avril 2014, elle sort son troisième EP, intitulé Z.",110,"fr:SZA","c:f/f4/KendrickSZASPurs230725-19_-_54683179509_%28cropped%29_%28cropped%29.jpg"],["Q9619",255,"chanteur","Tame Impala","R","Tame Impala est le projet musical psychédélique du multi-instrumentiste australien Kevin Parker, fondé en 2007 à Perth.",null,"fr:Tame_Impala","c:1/13/Tame_Impala_at_Flow_Festival_Helsinki_Aug_10_2019_-24.jpg"],["Q95129121",256,"chanteur","Tate McRae","E","Tate Rosner McRae, dite Tate McRae, née le 1er juillet 2003 à Calgary, est une autrice-compositrice-interprète et danseuse canadienne.",113,"fr:Tate_McRae","c:d/d7/Tate_McRae_Live_at_Lollapalooza_2026.jpg"],["Q193509",257,"chanteur","Taylor Momsen","PC","Taylor Michel Momsen est une chanteuse et musicienne américaine de rock, ex-actrice et mannequin née le 26 juillet 1993 à Saint-Louis dans le Missouri.",119,"fr:Taylor_Momsen","c:a/ab/Hellfest2026ThePrettyReckless_4.jpg"],["Q26876",258,"chanteur","Taylor Swift","L","Taylor Swift, née le 13 décembre 1989 à West Reading, est une auteure-compositrice-interprète, musicienne, actrice et réalisatrice de clips musicaux américaine.",117,"fr:Taylor_Swift","c:d/d7/Taylor_Swift_at_the_2023_MTV_Video_Music_Awards_4.png"],["Q105542333",259,"chanteur","Teddy Swims","R","Teddy Swims, de son vrai nom Jaten Collin Dimsdale, né le 25 septembre 1992 à Conyers dans l’État de Georgie, est un chanteur et auteur-compositeur-interprète américain, dont la musique mélange des genres tels que le R&B, la soul, la country et la pop. Il a initialement attiré des fans grâce à des reprises de chansons sur sa chaîne YouTube tout au long de 2019 et 2020. Son troisième EP, Tough Love, lui a permis d'entrer dans le Billboard 200 pour la première fois.",116,"fr:Teddy_Swims","c:0/08/Teddy_Swims_Warner_Records.jpg"],["Q171235",260,"chanteur","Thalía","C","Ariadna Thalía Sodi Miranda, surnommée Thalía, est une actrice et chanteuse mexicaine, née à Mexico le 26 août 1971. Elle est connue comme l'une des figures les plus importantes du genre telenovela au niveau international.","Ariadna Thalía Sodi Miranda, surnommée Thalía, est une actrice et chanteuse mexicaine, née à Mexico le 26 août 1971.","fr:Thalía","c:d/d2/ThaliaSodi_cropped.jpg"],["Q2121062",261,"chanteur","The Weeknd","R","The Weeknd, nom de scène d'Abel Makkonen Tesfaye est un chanteur, acteur, auteur-compositeur-interprète et producteur canadien, né le 16 février 1990 à Toronto.",117,"fr:The_Weeknd","c:a/a0/The_Weeknd_Portrait_by_Brian_Ziff.jpg"],["Q188668",262,"chanteur","Thom Yorke","PC","Thomas Yorke, dit Thom Yorke, est un musicien auteur-compositeur, chanteur et guitariste britannique, né le 7 octobre 1968 à Wellingborough dans le Northamptonshire. Il est le chanteur et le principal compositeur de Radiohead, groupe fondé au milieu des années 1980 avec ses camarades du lycée d'Abingdon dans l'Oxfordshire, Colin Greenwood, Jonny Greenwood, Ed O'Brien et Phil Selway, devenu, à partir du début de sa carrière discographique en 1992, une des formations de rock les plus importantes et célébrées de son…",117,"fr:Thom_Yorke","c:2/29/Thom_Yorke_2016.jpg"],["Q131814",263,"chanteur","Tina Turner","E","Anna Mae Bullock, dite Tina Turner, née le 26 novembre 1939 à Brownsville et morte le 24 mai 2023 à Küsnacht, est une chanteuse, compositrice et actrice américano-suisse.",117,"fr:Tina_Turner","c:0/0b/Tina_Turner_Breaks_All_the_Rules.png"],["Q180850",264,"chanteur","Tom Jones","R","Tom Jones est un chanteur et acteur britannique, né le 7 juin 1940 à Treforest.",null,"fr:Tom_Jones_(chanteur)","c:e/ee/Sir_Tom_Jones_at_The_Queen%27s_Birthday_Party_%28cropped%29.jpg"],["Q184805",265,"chanteur","Tom Waits","PC","Thomas Waits, dit Tom Waits, est un auteur-compositeur, musicien, chanteur, réalisateur musical et acteur américain, né le 7 décembre 1949 à Pomona en Californie.",119,"fr:Tom_Waits","c:5/5a/TomWaits-byPhilipRomano3.jpg"],["Q187814",266,"chanteur","Tracy Chapman","C","Tracy Chapman est une autrice-compositrice-interprète américaine née le 30 mars 1964 à Cleveland.",null,"fr:Tracy_Chapman","c:5/5e/Tracy_Chapman_3.jpg"],["Q1362028",267,"chanteur","Troye Sivan","PC","Troye Sivan Mellet dit Troye Sivan, né le 5 juin 1995 à Johannesbourg, est un auteur-compositeur-interprète, acteur et ancien youtubeur australo-sud-africain.",118,"fr:Troye_Sivan","c:0/00/Troye_Sivan_-_1999_-_Primavera_Sound_Barcelona_-_2024.jpg",{"cats":["chanteurs_int","lgbt"]}],["Q165911",268,"chanteur","Usher","C","Usher, de son nom complet Usher Raymond IV, né le 14 octobre 1978 à Dallas, au Texas, est un chanteur de RnB, danseur, parolier et acteur américain.",118,"fr:Usher","c:f/fa/Usher_Cannes_2016_retusche.jpg"],["Q207824",269,"chanteur","Varg Vikernes","C","Varg Vikernes, né Kristian Larsson Vikernes le 11 février 1973 à Bergen en Norvège, est un musicien et un auteur norvégien. Il est essentiellement connu pour son appartenance à des mouvements néopaïens, néonazis et d'extrême droite, il est condamné pour des incendies criminels et, en 1993, à 21 ans de prison pour meurtre. Il fait l'objet de multiples controverses.",112,"fr:Varg_Vikernes","c:9/9c/Varg_Vikernes.jpg"],["Q19810",270,"chanteur","Victoria Beckham","C","Victoria Beckham, Lady Beckham, née Adams le 17 avril 1974 à Harlow dans l'Essex en Angleterre, est une chanteuse, danseuse, styliste, designer et femme d'affaires britannique. Elle est surtout connue pour être l'une des célèbres Spice Girls; son surnom dans le groupe est Posh Spice. Entre 1996 et 1998, Spice Girls est considéré comme le plus grand groupe musical féminin, avec plus de 86 millions de disques vendus en l'espace de deux opus et 10 singles classés numéros 1 dans le monde.",114,"fr:Victoria_Beckham","c:a/a8/VictoriaBeckham2018-2-Crop.jpg"],["Q34389",271,"chanteur","Whitney Houston","E","Whitney Houston, née le 9 août 1963 à Newark et morte le 11 février 2012 à Beverly Hills, est une chanteuse, actrice, productrice de musique et mannequin américaine. Elle débute en tant que mannequin mais est révélée en 1985 par la sortie de son premier album intitulé Whitney Houston. Cet album devient très vite un succès dans son pays et à l'international, porté notamment par la chanson Saving All My Love for You.",117,"fr:Whitney_Houston","c:0/02/Whitney_Houston_Welcome_Heroes_7a.JPEG"],["Q206112",273,"chanteur","Willie Nelson","R","Willie Nelson, né le 29 avril 1933 à Abbott, au Texas, est un acteur, producteur, chanteur et guitariste de musique country américain. Son nom est plus spécialement attaché au style « outlaw country ».",115,"fr:Willie_Nelson","c:e/ea/Willie_Nelson.jpg"],["Q117139",274,"chanteur","Wiz Khalifa","C","Wiz Khalifa, de son vrai nom Cameron Jibril Thomaz, est un rappeur, auteur-compositeur-interprète et acteur américain. Il publie son premier album, Show and Prove, en 2006, puis signe avec la maison de disque Warner Bros en 2007.","Wiz Khalifa, de son vrai nom Cameron Jibril Thomaz, est un rappeur, auteur-compositeur-interprète et acteur américain.","fr:Wiz_Khalifa","c:6/6f/Wiz_Khalifa_Stavernfestivalen_2018_%28231822%29.jpg"],["Q4061",275,"chanteur","Woody Guthrie","C","Woody Guthrie, né le 14 juillet 1912 à Okemah, Oklahoma, et mort le 3 octobre 1967 à New York, est un chanteur et guitariste folk américain.",113,"fr:Woody_Guthrie","c:e/e0/Woody_Guthrie_NYWTS.jpg"],["Q28561969",276,"chanteur","XXXTentacion","E","XXXTentacion, de son vrai nom Jahseh Onfroy, était un rappeur, chanteur, auteur-compositeur-interprète et vidéaste américain, né le 23 janvier 1998 à Plantation et mort assassiné le 18 juin 2018 à Deerfield Beach. Il est une figure populaire du rap SoundCloud.",114,"fr:XXXTentacion","c:e/ee/Xxxtentacion_%28cropped%29.jpg"],["Q117012",277,"chanteur","Yoko Ono","R","Yoko Ono, née le 18 février 1933 à Tokyo au Japon, est une artiste plasticienne, poétesse, performeuse, musicienne, chanteuse, compositrice, écrivaine, comédienne et cinéaste japonaise.",115,"fr:Yoko_Ono","c:f/f9/Yokoono_%28cropped%29.JPG"],["Q4177928",278,"chanteur","Zara Larsson","L","Zara Larsson, née le 16 décembre 1997 dans le comté de Stockholm, est une auteure-compositrice-interprète suédoise. Elle est également coréalisatrice de certains de ses clips.","Zara Larsson, née le 16 décembre 1997 dans le comté de Stockholm, est une auteure-compositrice-interprète suédoise.","fr:Zara_Larsson","c:3/39/GreenDayIOW230624_%28147_of_367%29_%2853817339617%29_%28Zara_Larsson%29.jpg"],["Q3626950",279,"chanteur","Zayn Malik","PC","Zayn Malik ou simplement Zayn stylisé ZAYN, né le 12 janvier 1993 à Bradford est un chanteur, compositeur, mannequin et acteur britannique.",119,"fr:Zayn_Malik","c:1/10/Zayn_Wiki_%28cropped%29.jpg"],["Q44479972",280,"rappeur","6ix9ine","C","6ix9ine,, de son vrai nom Daniel Hernandez, est un rappeur et chanteur américain, né le 8 mai 1996 à New York. Il se fait mondialement connaître en 2017 avec le morceau Gummo, qui accumule près de 426 millions de vues sur YouTube et plus de 81 millions d'écoutes sur Spotify. La chanson devient un hit national, atteignant la 12e place du Billboard Hot 100 et étant certifiée disque de platine aux États-Unis.","6ix9ine,, de son vrai nom Daniel Hernandez, est un rappeur et chanteur américain, né le 8 mai 1996 à New York.","fr:6ix9ine","c:4/4c/6ix9ine_June_2018_side_%28cropped_x2%29.jpg"],["Q301818",281,"rappeur","Aaron Carter","C","Aaron Carter, né le 7 décembre 1987 à Tampa en Floride et mort le 5 novembre 2022 à Lancaster en Californie, est un chanteur, compositeur et acteur américain, devenu populaire vers la fin des années 1990, et plus encore dans les années 2000. Il est le frère cadet de Nick Carter, membre du groupe pop Backstreet Boys.",115,"fr:Aaron_Carter","c:6/6e/Aaron_Carter_Performing_at_the_Gramercy_Theatre_-_Photo_by_Peter_Dzubay_%28cropped%29.jpg"],["Q204751",282,"rappeur","Anthony Kiedis","C","Anthony Kiedis est un chanteur, acteur et producteur américain né le 1er novembre 1962, à Grand Rapids, dans le Michigan.",111,"fr:Anthony_Kiedis","c:7/7e/AnthonyKiedis18-10-2016.jpg",{"cats":["chanteurs_int","groupes"]}],["Q129910",283,"rappeur","ASAP Rocky","PC","ASAP Rocky,, de son vrai nom Rakim Mayers, est un rappeur, chanteur, auteur-compositeur-interprète, mannequin, producteur, homme d’affaires, réalisateur et acteur américain, né le 3 octobre 1988 à New York.",110,"fr:ASAP_Rocky","c:2/20/A%24AP_Rocky_at_the_2025_Cannes_Film_Festival_%28cropped%29.jpg"],["Q1393997",284,"rappeur","Becky G","C","Becky G, de son vrai nom Rebbeca Marie Gomez, née le 2 mars 1997 à Inglewood, en Californie, est une chanteuse, rappeuse, danseuse, auteur-compositrice-interprète et actrice américaine d’origine mexicaine.",111,"fr:Becky_G","c:c/ce/Becky_G.jpg"],["Q311241",285,"rappeur","Bobby Brown","C","Robert Barisford Brown dit Bobby Brown, né le 5 février 1969 à Boston, est un chanteur, compositeur, producteur et acteur américain.",114,"fr:Bobby_Brown_(chanteur)","c:c/c0/Bobby_Brown_on_Sister_Circle_Live.jpg"],["Q59185",286,"rappeur","Busta Rhymes","C","Busta Rhymes, de son vrai nom Trevor George Smith, Jr., né le 20 mai 1972 à Brooklyn, New York, est un rappeur, producteur et acteur américain. Chuck D du groupe Public Enemy lui attribue le nom de Busta Rhymes, en s'inspirant du receveur de la NFL, George « Buster » Rhymes. Au début de sa carrière, il est connu pour son mode vestimentaire, puis mieux connu actuellement pour sa technique de rap ou pour ses nombreuses nominations aux Grammy Awards.",111,"fr:Busta_Rhymes","c:9/9a/Busta_rhymes-06-mika.jpg"],["Q127362",287,"rappeur","Chief Keef","C","Chief Keef, de son vrai nom Keith Farrelle Cozart, est un rappeur, chanteur, producteur américain né le 15 août 1995 à Chicago dans l'Illinois. Chief Keef grandit dans le quartier de Front$reet/O'Block précisément au Parkway Gardens à Chicago et se lance très jeune dans le rap. Il est un si ce n'est littéralement le précurseur de la drill; qu'il popularise à travers le monde avec ses titres I Don't Like, Love Sosa et Hate Bein' Sober.",118,"fr:Chief_Keef","c:6/64/Chief_Keef_2019_performance.jpg"],["Q230501",288,"rappeur","Christina Milian","C","Christina Milian, de son vrai nom Christine Flores, née le 26 septembre 1981 à Jersey City, dans l'État du New Jersey, aux États-Unis, est une autrice-interprète et actrice américaine, issue de parents d’ascendance cubaine.",118,"fr:Christina_Milian","c:c/c4/Christina_Milian_2011.jpg"],["Q286022",289,"rappeur","Common","C","Lonnie Lynn, Jr., dit Common et anciennement Common Sense, né le 13 mars 1972 à Chicago, est un rappeur et acteur américain.",113,"fr:Common","c:7/73/9.13.11CommonByLuigiNovi2.jpg"],["Q310357",290,"rappeur","Coolio","C","Artis Leon Ivey Jr., dit Coolio, né le 1er août 1963 à Monessen, Pennsylvanie et mort le 28 septembre 2022 à Los Angeles, Californie est un rappeur, chanteur, producteur et acteur américain.",112,"fr:Coolio","c:c/c8/Coolio.jpg"],["Q80805",291,"rappeur","DJ Khaled","C","DJ Khaled, de son vrai nom Khaled Mohamed, né le 26 novembre 1975 à La Nouvelle-Orléans en Louisiane, est un disc jockey et producteur américain d’origine palestinienne. Il est DJ et animateur de la station de radio WEDR, à Miami, qui diffuse plusieurs styles musicaux. Il est également le DJ du groupe Terror Squad. En 2010, il fonde son propre label discographique, We the Best Music, dont l'artiste le plus populaire est Ace Hood.",113,"fr:DJ_Khaled","c:9/92/DJ_KHALED_Press_exclusive_-1_%28cropped%29.jpg"],["Q223769",292,"rappeur","DMX","C","DMX, de son vrai nom Earl Simmons, né le 18 décembre 1970 à Mount Vernon et mort le 9 avril 2021 à White Plains, dans le même État, est un rappeur et acteur américain. DMX est le deuxième artiste dont deux des albums se sont classés no 1 au Billboard 200 le jour de leur sortie – le premier étant Tupac Shakur. Jusqu'à Grand Champ, tous ses albums ont atteint la première place des classements américains.",117,"fr:DMX_(rappeur)","c:3/38/Academy_Awards_afterparty_CUN_DMX.jpg"],["Q1239933",293,"rappeur","Donald Glover","PC","Donald Glover, également connu sous les pseudonymes Childish Gambino et mcDJ pour ses activités musicales, est un acteur, scénariste, réalisateur, producteur, humoriste, beatmaker, musicien, rappeur et DJ américain, né le 25 septembre 1983 à l'Edwards Air Force Base en Californie.",113,"fr:Donald_Glover","c:2/2a/Donald_Glover_TIFF_2015.jpg"],["Q36804",294,"rappeur","Eazy-E","C","Eric Wright, dit Eazy-E, né le 7 septembre 1964 à Compton et mort le 26 mars 1995 à Los Angeles, est un rappeur et producteur américain, membre et fondateur du groupe N.W.A. Il est considéré comme le parrain du gangsta rap, ayant créé Ruthless Records, le premier label spécialisé dans ce genre musical.",114,"fr:Eazy-E","c:0/0a/Eazy-E.jpg"],["Q388785",295,"rappeur","Flavor Flav","C","Flavor Flav, de son vrai nom William Jonathan Drayton, Jr., né le 16 mars 1959 à Roosevelt, New York, est un rappeur américain. Il est un des leaders du groupe Public Enemy. Il est facilement reconnaissable à la grosse horloge qu'il porte autour de son cou ainsi qu'à ses chapeaux et lunettes tous plus excentriques les uns que les autres.",116,"fr:Flavor_Flav","c:e/ee/Flavor_Flav_of_Public_Enemy_Way_Out_West_2013.jpg"],["Q357645",296,"rappeur","Frank Ocean","C","Christopher Francis Ocean, né Christopher Edwin Breaux le 28 octobre 1987 à Long Beach, plus connu sous son nom de scène Frank Ocean, est un auteur-compositeur-interprète américain.",114,"fr:Frank_Ocean","c:e/e3/Frank_Ocean_2022_Blonded.jpg"],["Q44707",297,"rappeur","Fred Durst","C","Fred Durst est un musicien et réalisateur américain originaire de Jacksonville. Durst a grandi à Gastonia, Caroline du Nord et a joué dans un nombre de groupes musicaux en Floride durant la même période dans laquelle il travaillait en tant que tatoueur. Durst est mieux connu comme chanteur dans le groupe Limp Bizkit, formé en 1994, avec lequel il a publié six albums.","Fred Durst est un musicien et réalisateur américain originaire de Jacksonville.","fr:Fred_Durst","c:a/ac/Limp_Bizkit_Full_Force_2019_18.jpg",{"cats":["chanteurs_int","groupes"]}],["Q3445057",298,"rappeur","Future","C","Future, de son vrai nom Nayvadius Wilburn, né le 20 novembre 1983 à Atlanta, est un rappeur, chanteur, compositeur et producteur américain. Après la publication de plusieurs mixtapes à succès variable entre 2010 et 2011, Future signe aux labels Epic Records et A1 Recordings dirigé par son ami et rappeur Rocko, qui l'aidera à lancer son propre label, Freebandz. Future publie son premier album Pluto en avril 2012. L'album contient cinq singles, tous classés au Billboard Hot 100.",117,"fr:Future_(rappeur)","c:9/93/Future_-_Openair_Frauenfeld_2019_01_%28cropped%29.jpg"],["Q173637",299,"rappeur","Ice Cube","PC","O'Shea Jackson, Sr., dit Ice Cube, est un rappeur, acteur, scénariste, réalisateur et producteur de cinéma américain, né le 15 juin 1969 à Crenshaw. Il est membre du groupe de hip-hop N.W.A de 1987 à 1989, puis de la Westside Connection de 1995 à 2005, avant de poursuivre une carrière solo dans la musique.",117,"fr:Ice_Cube","c:2/2c/Ice-Cube_2014-01-09-Chicago-photoby-Adam-Bielawski.jpg"],["Q114114977",300,"rappeur","Ice Spice","C","Ice Spice, de son vrai nom Isis Naija Gaston née le 1er janvier 2000 à New York, est une rappeuse américaine. Elle a grandi dans le Bronx, à New York, et a commencé sa carrière en 2021. Après avoir rencontré le producteur de disques Riot USA alors qu'elle fréquentait l'Université d'État de New York à Purchase. Elle s'est fait connaître fin 2022 avec sa chanson Munch.","Ice Spice, de son vrai nom Isis Naija Gaston née le 1er janvier 2000 à New York, est une rappeuse américaine.","fr:Ice_Spice","c:9/9b/IceSpiceOuternet041124_%2880_of_81%29_%28cropped%29.jpg"],["Q309941",301,"rappeur","Ice-T","PC","Tracy Marrow, dit Ice-T, est un rappeur et acteur américain, né le 16 février 1958 à Newark, dans le New Jersey.",null,"fr:Ice-T","c:d/d7/Body_Count_feat._Ice-T_-_2019214172411_2019-08-02_Wacken_-_2311_-_AK8I3133_%28cropped%29.jpg"],["Q204018",302,"rappeur","J. Cole","C","J. Cole, de son vrai nom Jermaine Lamarr Cole, né le 28 janvier 1985 à Francfort-sur-le-Main en Allemagne, est un rappeur, chanteur, basketteur et producteur américain. Il se fait connaître du grand public par le biais de sa signature sur le label Roc Nation de Jay-Z. Son premier album studio, Cole World: The Sideline Story, est sorti en septembre 2011 aux États-Unis.","J.","fr:J._Cole","c:6/69/HOTSPOTATL_-_21_Savage_%26_J.Cole_Light_Birthday_Bash_ATL_2023_On_FIRE_%28xu6HKf40MX0_-_2m38s%29_%28cropped%29.jpg"],["Q221364",303,"rappeur","Jaden Smith","C","Jaden Smith est un acteur, mannequin, rappeur, danseur et compositeur américain, né le 8 juillet 1998 à Los Angeles. Il est le fils de l'acteur Will Smith et de l'actrice Jada Pinkett Smith.","Jaden Smith est un acteur, mannequin, rappeur, danseur et compositeur américain, né le 8 juillet 1998 à Los Angeles.","fr:Jaden_Smith","c:4/4e/2019_-_Opening_Night_SM1_0502_%2849014567373%29.jpg"],["Q234356",304,"rappeur","Janelle Monáe","C","Janelle Robinson, dite Janelle Monáe, est auteure-compositrice-interprète de soul music et actrice américaine, née le 1er décembre 1985 à Kansas City. Ses maisons de disques sont Bad Boy Records et Atlantic Records. Janelle est nommée aux Grammy Awards en 2009, pour son titre Many Moons.",117,"fr:Janelle_Monáe","c:a/ae/Janelle_Monae_Paris_Fashion_Week_Autumn_Winter_2019.jpg",{"cats":["chanteurs_int","lgbt"]}],["Q62766",305,"rappeur","Jay-Z","R","Jay-Z, stylisé JAŸ-Z, de son vrai nom Shawn Corey Carter, né le 4 décembre 1969, à New York, est un rappeur et homme d'affaires américain. Il est marié avec la chanteuse Beyoncé depuis 2008.",116,"fr:Jay-Z","c:5/5a/Jay-Z_2%2C_2011.jpg"],["Q52151598",306,"rappeur","Juice Wrld","C","Juice Wrld, stylisé Juice WRLD, de son vrai nom Jarad Anthony Higgins, né le 2 décembre 1998 à Chicago et mort le 8 décembre 2019 à Oak Lawn, est un rappeur, chanteur, parolier, compositeur et musicien américain.",115,"fr:Juice_Wrld","c:3/35/Juice_WRLD_-_Les_Ardentes_2019_%28cropped%29.jpg"],["Q299138",307,"rappeur","Kid Cudi","C","Kid Cudi, parfois transcrit KiD CuDi, né le 30 janvier 1984 à Cleveland, est un rappeur, chanteur, guitariste, réalisateur artistique et acteur américain. Il est reconnu comme une influence sur plusieurs groupes hip hop et alternatifs contemporains. Après avoir emménagé à Brooklyn, New York, dans l'espoir de devenir rappeur, Kid Cudi gagne initialement en popularité grâce à sa première mixtape, publiée en 2008. Celle-ci attire l'attention de Kanye West, qui signe l'artiste sur son label fin 2008.",110,"fr:Kid_Cudi","c:4/44/Kid_Cudi_2010_2_%28crop%29.jpg"],["Q158175",308,"rappeur","Kid Rock","R","Kid Rock, de son vrai nom Robert James Ritchie, est un chanteur américain né le 17 janvier 1971 à Romeo, un village du comté de Macomb dans le Michigan.",118,"fr:Kid_Rock","c:1/18/Kid_Rock_Dec_2013.jpg"],["Q94579368",309,"rappeur","King Von","PC","King Von, de son vrai nom Dayvon Bennett, né le 9 août 1994 à Chicago et mort assassiné le 6 novembre 2020 à Atlanta, est un rappeur américain.",117,"fr:King_Von","c:d/d6/King_Von.png"],["Q214226",310,"rappeur","Lauryn Hill","C","Lauryn Hill est une chanteuse, rappeuse, auteure-compositrice-interprète, productrice et actrice américaine de hip-hop et de RnB, née le 26 mai 1975 à East Orange. Elle a été membre du groupe Fugees.",118,"fr:Lauryn_Hill","c:d/dc/Lauryn_Hill_-_2014.jpg"],["Q62591281",311,"rappeur","Lil Nas X","C","Lil Nas X, de son vrai nom Montero Lamar Hill, né le 9 avril 1999 à Atlanta, en Géorgie, est un chanteur, rappeur, auteur-compositeur-interprète et danseur-chorégraphe américain.",114,"fr:Lil_Nas_X","c:8/8a/Lil_Nas_X_Talks_About_Gaining_His_Father%27s_Acceptance%2C_Growing_Up_in_Atlanta%2C_%26_FINDING_HIMSELF_7-32_screenshot_%28headshot%29.jpg",{"cats":["chanteurs_int","lgbt"]}],["Q29388200",312,"rappeur","Lil Peep","C","Lil Peep, de son vrai nom Gustav Elijah Åhr, né le 1er novembre 1996 à Allentown et mort le 15 novembre 2017 à Tucson est un chanteur, rappeur et musicien américain. Pionnier de l'emo rap, il est membre du collectif GothBoiClique.",117,"fr:Lil_Peep","c:2/23/Lil-Peep_PrettyPuke_Photoshoot.png"],["Q1646482",313,"rappeur","Lin-Manuel Miranda","PC","Lin-Manuel Miranda est un acteur, chanteur, réalisateur, auteur-compositeur et dramaturge américain, né le 16 janvier 1980 à New York.",117,"fr:Lin-Manuel_Miranda","c:f/fa/Lin-Manuel_Miranda_during_an_interview%2C_March_2022_%283%29_%28cropped%29.jpg"],["Q233541",314,"rappeur","Lisa Lopes","C","Lisa Lopes, aussi connue sous les noms Left Eye, N.I.N.A. et Nikki, est une rappeuse, chanteuse, parolière et actrice américaine, née le 27 mai 1971 à Philadelphie et morte le 25 avril 2002 à La Ceiba, au Honduras.","Lisa Lopes, aussi connue sous les noms Left Eye, N.I.N.A.","fr:Lisa_Lopes","https://upload.wikimedia.org/wikipedia/en/thumb/6/65/LisaLopesImg.jpg/330px-LisaLopesImg.jpg"],["Q52440",315,"rappeur","LL Cool J","R","James Todd Smith III, dit LL Cool J, est un rappeur et acteur américain, né le 14 janvier 1968 à Islip, à New York.",null,"fr:LL_Cool_J","c:b/b4/LLCoolJ-byPhilipRomano.jpg"],["Q193676",316,"rappeur","Ludacris","C","Ludacris, nom de scène de Christopher Bridge, est un rappeur, entrepreneur et acteur américano-gabonais, né le 11 septembre 1977 à Champaign dans l'Illinois. Aux côtés de son manager, Ludacris est cofondateur de Disturbing tha Peace, label affiliée à Def Jam Recordings. Durant sa carrière, Ludacris remporte les prix Screen Actors Guild, Critic's Choice, MTV, et Grammy Award.",113,"fr:Ludacris","c:7/73/Ludacris_at_NAS_Pax_River_2_%28cropped%29.jpg"],["Q324726",317,"rappeur","Mac Miller","PC","Mac Miller, de son vrai nom Malcolm James McCormick, né le 19 janvier 1992 à Pittsburgh et mort le 7 septembre 2018 à Los Angeles, est un rappeur, chanteur et producteur américain.",117,"fr:Mac_Miller","c:6/6c/Mac_Miller_%2820%29_%E2%80%93_splash%21_Festival_20_%282017%29_%28cropped%29.jpg"],["Q1354843",318,"rappeur","Machine Gun Kelly","R","Colson Baker, dit Machine Gun Kelly, aussi connu sous le sigle MGK, est un chanteur et acteur américain, né le 22 avril 1990 à Houston, au Texas.",119,"fr:Machine_Gun_Kelly_(chanteur)","c:2/23/MGK_2021_VMA.jpg"],["Q484874",319,"rappeur","Macklemore","PC","Macklemore, anciennement Professor Mack Lemore, de son vrai nom Benjamin Haggerty, né le 19 juin 1983 à Seattle, est un rappeur, chanteur, danseur et DJ américain.",119,"fr:Macklemore","c:f/f7/260830220856_NF5_6892_NathanFabry.jpg"],["Q59268408",320,"rappeur","Megan Thee Stallion","PC","Megan Thee Stallion, de son vrai nom Megan Jovon Ruth Pete, est née le 15 février 1995 à San Antonio, est une rappeuse américaine. Elle publie son EP Tina Snow en juin 2018, puis signe chez 300 Entertainment en novembre 2018, faisant d'elle la première rappeuse du label. Son premier projet musical complet, nommé Fever, a été publié le 17 mai 2019.",118,"fr:Megan_Thee_Stallion","c:a/a3/Megan_Thee_Stallion_Adweek_pose.jpg"],["Q298694",321,"rappeur","Method Man","C","Method Man, de son vrai nom Clifford Smith, né le 2 mars 1971 à Hempstead, dans l'État de New York, est un rappeur et acteur américain. Membre du Wu-Tang Clan, il conduit parallèlement une carrière solo ou en collaboration avec d'autres rappeurs tels que Redman. En 2012, le magazine The Source classe Method Man dans sa liste des 50 meilleurs paroliers de tous les temps.",117,"fr:Method_Man","c:2/26/Methodman_at_TIFF_2025_-_2_%28cropped%29.jpg"],["Q304675",322,"rappeur","MF DOOM","PC","MF DOOM, de son vrai nom Daniel Dumile, né le 13 juillet 1971 à Londres et mort le 31 octobre 2020 à Leeds, est un rappeur et producteur musical britannique, principalement actif au sein de la scène hip-hop de New York. Il a la particularité d'avoir utilisé plusieurs noms de scène dans sa carrière comme MF DOOM, en référence au personnage de comics docteur Doom, Zev Love X, King Geedorah, Metal Fingers, Viktor Vaughn ou encore DOOM.",114,"fr:MF_DOOM","c:0/08/MF_Doom_-_Hultsfred_2011.jpg"],["Q194220",323,"rappeur","Nas","C","Nasir Bin Olu Dara Jones, dit Nas, est un rappeur, compositeur et acteur américain, né le 14 septembre 1973 à Brooklyn, New York. Fils du musicien de jazz Olu Dara, Nas compte huit albums certifiés consécutivement disques de platine, et compte plus de 25 millions d'albums écoulés depuis 1994. Il est également entrepreneur à son propre label. Il est actuellement signé aux labels Def Jam Recordings et Mass Appeal Records",119,"fr:Nas_(rappeur)","c:b/be/Nas_%2852380600682%29_%28cropped%29.jpg"],["Q218992",324,"rappeur","Nelly","C","Nelly, de son vrai nom Cornell Iral Haynes, Jr., né le 2 novembre 1974 à Austin, au Texas, est un rappeur, chanteur, acteur, entrepreneur américain. Nelly se joint au groupe de hip-hop St. Lunatics en 1993 et signe au label Universal Records en 1999. Sous Universal, Nelly se lance en solo en 2000, avec son premier album Country Grammar, qui contient la chanson homonyme à succès. L'album débute troisième du Billboard 200 puis atteint la première place.",116,"fr:Nelly_(rappeur)","c:2/20/Cornell-Haynes-Jr_Nelly_2010-06-05_photoby_Adam-Bielawski.jpg"],["Q348533",325,"rappeur","Nick Cannon","C","Nicholas Cannon, dit Nick Cannon, né le 8 octobre 1980 à San Diego, est un rappeur, scénariste, acteur, présentateur, producteur de musique et producteur exécutif de films américain. Il anime de la quatrième à la onzième saison de l'émission américaine America's Got Talent. Il épouse la chanteuse Mariah Carey en 2008 et demande le divorce en 2014.",117,"fr:Nick_Cannon","c:6/60/Nick_Cannon_by_David_Shankbone.jpg"],["Q162202",326,"rappeur","Nicki Minaj","M","Nicki Minaj, née Onika Tanya Maraj le 8 décembre 1982 à Port-d'Espagne, est une rappeuse, chanteuse, parolière, compositrice, mannequin et actrice trinidadienne.",111,"fr:Nicki_Minaj","c:a/a4/Nicki_Minaj_2025_%283x4_cropped%29.jpg"],["Q2073970",327,"rappeur","Nipsey Hussle","C","Nipsey Hussle, de son vrai nom Ermias Joseph Asghedom, né le 15 août 1985 à Los Angeles, en Californie, et mort assassiné le 31 mars 2019 dans la même ville, est un rappeur, auteur-compositeur-interprète, entrepreneur et acteur américain.",111,"fr:Nipsey_Hussle","c:5/5c/Soundtrack_Beat_Battle_Judging_Panel_March2011_%28cropped%29.jpg"],["Q336924",328,"rappeur","Ol' Dirty Bastard","C","Ol' Dirty Bastard, de son vrai nom Russell Tyrone Jones, né le 15 novembre 1968 à Brooklyn et mort le 13 novembre 2004 à New York, est un rappeur américain. Il est l'un des membres fondateurs du groupe Wu-Tang Clan, originaire de Staten Island, qui se popularisera grâce à son premier album Enter the Wu-Tang.",118,"fr:Ol'_Dirty_Bastard","c:8/8e/ODB_Mural.jpg"],["Q55956050",329,"rappeur","Oliver Tree","R","Oliver Tree, né le 29 juin 1993 à Santa Cruz et mort le 14 juin 2026 à Rio de Janeiro, est un auteur-compositeur-interprète, chanteur, rappeur, compositeur, musicien, humoriste et réalisateur américain.",93,"fr:Oliver_Tree","c:f/f7/Oliver_Tree_Feb_2019_cropped.jpg"],["Q187844",330,"rappeur","Pitbull","PC","Pitbull, également appelé Mr. Worldwide, ou encore Mr. 305, de son vrai nom Armando Pérez, est un rappeur, chanteur, producteur, acteur et entrepreneur américano-cubain, né le 15 janvier 1981 à Miami. Il se fait connaître du public en participant à la production de l'album Kings of Crunk de Lil Jon publié en 2002. En 2004, Pitbull publie son premier album M.I.A.M.I., au label TVT Records; l'album fait participer Lil Jon et Jim Jonsin à la production.","Pitbull, également appelé Mr.","fr:Pitbull_(rappeur)","c:3/36/Pitbull_in_Concert_in_Las_Vegas_%2826904123617%29.jpg"],["Q27671080",331,"rappeur","Playboi Carti","C","Playboi Carti est un rappeur et mannequin américain né le 13 septembre 1996 à Atlanta. Il est l'un des rappeurs les plus célèbres de la génération SoundCloud et a notamment aidé à populariser le sous-genre de la rage.","Playboi Carti est un rappeur et mannequin américain né le 13 septembre 1996 à Atlanta.","fr:Playboi_Carti","c:0/0f/Playboi_Carti%2C_Clout_Festival_2024_05_%28cropped%29.jpg"],["Q21621919",332,"rappeur","Post Malone","C","Post Malone, de son vrai nom Austin Richard Post, né le 4 juillet 1995 à Syracuse dans l'État de New York, est un chanteur, rappeur et réalisateur artistique américain. Il se fait mondialement connaître en 2015 avec le titre White Iverson qui se classe à la 14e place du Billboard Hot 100.",113,"fr:Post_Malone","c:3/3a/Post_Malone_July_2021.jpg"],["Q30072039",333,"rappeur","Quavo","C","Quavious Keyate Marshall, dit Quavo, est un rappeur et chanteur américain né le 2 avril 1991 à Athens, dans l'État de Géorgie. Il est l'un des trois membres du groupe de rap Migos, actif entre 2009 et 2022.",117,"fr:Quavo","c:5/57/Quavo_Veld_festival_2017.jpg"],["Q2938630",334,"rappeur","Redfoo","C","Stefan Kendal Gordy, mieux connu sous le nom de Redfoo, né le 3 septembre 1975 à Los Angeles, est un chanteur, danseur, disc jockey, rappeur et joueur de tennis américain, connu comme membre du duo musical LMFAO formé en 2006 avec son neveu, Sky Blu. Ils sortent deux albums studio, puis Redfoo entame une carrière solo avec son album Party Rock Mansion en 2016.",119,"fr:Redfoo","c:8/8b/LMFAO%2C_2011.jpg"],["Q297831",335,"rappeur","Rick Ross","C","Rick Ross, de son vrai nom William Leonard Roberts II, né le 28 janvier 1976 à Clarksdale, est un rappeur américain. Il se fait connaître du grand public grâce à son single Hustlin'. Son nom de scène Rick Ross est une référence à Rick « Freeway » Ross, l'un des plus importants trafiquants de cocaïne de Los Angeles des années 1980, avec lequel il n'entretient aucun lien. Ce dernier portera d'ailleurs plainte contre lui, demandant 10 millions de dollars pour l'usage de son nom.","Rick Ross, de son vrai nom William Leonard Roberts II, né le 28 janvier 1976 à Clarksdale, est un rappeur américain.","fr:Rick_Ross","c:1/13/Rick_Ross_in_the_trap%21_%28cropped%29.jpg"],["Q52447",336,"rappeur","RZA","C","RZA, de son vrai nom Robert Fitzgerald Diggs, est un rappeur, producteur, acteur et réalisateur américain, membre fondateur et leader du groupe Wu-Tang Clan. Il participe à la production de presque tous les albums du Wu-Tang Clan, ainsi que des affiliés et membres du groupe.",113,"fr:RZA","c:0/0c/RZA_by_Gage_Skidmore.jpg"],["Q313080",337,"rappeur","Soulja Boy","C","Soulja Boy, de son véritable nom DeAndre Cortez Way, né le 28 juillet 1990 à Chicago, dans l'Illinois, est un rappeur, producteur, entrepreneur et acteur américain. Il connait un grand succès grâce au tube Crank That et à son album Souljaboytellem.com en 2007, certifié disque de platine par la Recording Industry Association of America.",118,"fr:Soulja_Boy","c:3/38/Soulja.jpg"],["Q20055659",338,"rappeur","Stormzy","C","Stormzy, de son vrai nom Michael Ebenazeree Kwadjo Omari Owuo Jr., né le 26 juillet 1993 à Thornton Heath est un rappeur et auteur-compositeur-interprète anglais.",112,"fr:Stormzy","c:a/ac/Stormzy_-_Openair_Frauenfeld_2019_03.jpg"],["Q214227",339,"rappeur","T.I.","C","T.I., de son vrai nom Clifford Joseph Harris Jr., est un rappeur et acteur américain. Il signe son premier contrat de distribution au label LaFace Records en 1999, une division d'Arista Records. En 2001, T.I. forme le groupe Pimp Squad Click, aux côtés d'amis et rappeurs. Bien que membre d'Arista, T.I. signe également au label Atlantic Records et devient directeur général de son propre label, Grand Hustle Records, qu'il lance en 2003. T.I.","T.I., de son vrai nom Clifford Joseph Harris Jr., est un rappeur et acteur américain.","fr:T.I.","c:9/9f/T.I._performing_in_concert%2C_wearing_a_Phoenix_Suns_cap.jpg"],["Q48719890",340,"rappeur","Takeoff","C","Takeoff, nom de scène de Kirsnick Khari Ball, est un rappeur, chanteur et auteur-compositeur américain né le 18 juin 1994 à Lawrenceville en Géorgie et mort assassiné le 1er novembre 2022 à Houston au Texas.",116,"fr:Takeoff","c:8/8b/Takeoff_performing_with_Migos_in_2017_%2836471054572%29.jpg"],["Q7708542",341,"rappeur","Teyana Taylor","PC","Teyana Taylor, née le 10 décembre 1990, est une auteure-compositrice-interprète, actrice, danseuse, chorégraphe et réalisatrice américaine.",114,"fr:Teyana_Taylor","c:7/7c/Teyana_Taylor_at_2026_Essence_Festival_of_Culture_01.jpg"],["Q179157",342,"rappeur","The Notorious B.I.G.","PC","The Notorious B.I.G., également surnommé Biggie Smalls, de son vrai nom Christopher George Latore Wallace, né le 21 mai 1972 à New York et mort assassiné le 9 mars 1997 à Los Angeles, est un rappeur et chanteur américain. Personnage phare du rap new-yorkais des années 1990, il se classe troisième MC de l'histoire par MTV en 2006. Il est considéré comme l'un des plus grands rappeurs de tous les temps.",119,"fr:The_Notorious_B.I.G.","https://upload.wikimedia.org/wikipedia/en/thumb/8/8c/Biggie_Smalls_1997.jpg/330px-Biggie_Smalls_1997.jpg"],["Q13605596",343,"rappeur","Travis Scott","R","Jacques Bermon Webster II, dit Travis Scott, est un rappeur, chanteur, producteur, musicien, mixeur, acteur, mannequin et réalisateur américain, né le 30 avril 1991 à Houston, au Texas.",118,"fr:Travis_Scott","c:3/3f/TravisScott-byPhilipRomano.jpg"],["Q6107",344,"rappeur","Tupac Shakur","E","Parish Lesane Crooks, dit Tupac Shakur et connu sous les noms de scène 2Pac et Makaveli, est un rappeur, chanteur, poète et acteur américain, né le 16 juin 1971 à New York et mort assassiné le 13 septembre 1996 à Las Vegas. Il est souvent considéré comme étant l'un des plus grands rappeurs de tous les temps.",114,"fr:Tupac_Shakur","c:f/f9/Tupac_Shakur_passport_photo.png"],["Q358087",345,"rappeur","Tyga","C","Tyga, nom de scène de Michael Ray Nguyen-Stevenson, né le 19 novembre 1989 à Gardena, en Californie, est un rappeur américain. Il est signé sous les labels Young Money Entertainment, Cash Money Records et Universal Motown Records.",115,"fr:Tyga","c:9/98/Tyga_-_Openair_Frauenfeld_2019_02.jpg"],["Q167635",346,"rappeur","Tyler, The Creator","C","Tyler, The Creator, de son vrai nom Tyler Okonma, né le 6 mars 1991 à Hawthorne, est un rappeur, producteur de musique, acteur, designer, graphiste, réalisateur, scénariste, styliste, et directeur artistique américain.",119,"fr:Tyler,_The_Creator","c:f/fa/Tyler_the_Creator_2022_cropped.png"],["Q311232",347,"rappeur","Tyrese Gibson","C","Tyrese Gibson, ou simplement Tyrese, est un chanteur de R'n'B, acteur et mannequin américain, né le 30 décembre 1978 dans le quartier de Watts à Los Angeles.",116,"fr:Tyrese_Gibson","c:e/e3/Tyrese_Gibson_%282M1sAU997YY%29.png"],["Q185610",348,"rappeur","Will.i.am","C","will.i.am, de son vrai nom William James Adams Jr., né le 15 mars 1975 à Los Angeles,, est un rappeur, chanteur, auteur-compositeur, disc jockey, producteur et acteur américain d'origine jamaïcaine et martiniquaise.",112,"fr:Will.i.am","c:0/0e/Will.i.am_in_2018.jpg"],["Q139933",349,"rappeur","Zack de la Rocha","C","Zacharias Manuel « Zack » de la Rocha, né le 12 janvier 1970 à Long Beach, est un chanteur, musicien, poète, activiste américain, connu en tant que chanteur du groupe Rage Against the Machine, groupe politiquement engagé et influent, sur le plan des idéaux politiques autant qu'en musique, réussissant notamment la fusion entre rap et metal.",118,"fr:Zack_de_la_Rocha","c:d/d9/Zach_de_la_Rocha_at_2007_Coachella_Valley_Music_and_Arts_Festival.jpg"],["Q18233",350,"groupe","ABBA","R","ABBA, souvent stylisé AꓭBA, est un groupe suédois de pop, originaire de Stockholm. Formé le 1er novembre 1971, le groupe est originellement composé d'Agnetha Fältskog, Benny Andersson, Björn Ulvaeus et Anni-Frid « Frida » Lyngstad. Lors de leur formation, ils sont deux couples mariés: Agnetha et Björn, Frida et Benny. Le nom du groupe est à la fois un acronyme et un palindrome, composé des initiales des prénoms des membres. À partir de 1976 l'ambigramme — AꓭBA, avec un B inversé — est utilisé comme logo.","ABBA, souvent stylisé AꓭBA, est un groupe suédois de pop, originaire de Stockholm.","fr:ABBA","c:c/cb/ABBA_-_TopPop_1974_5.png"],["Q27593",351,"groupe","AC/DC","R","AC/DC est un groupe australo-britannique de hard rock, originaire de Sydney, fondé par les frères Angus et Malcolm Young. Son premier concert a eu lieu le 31 décembre 1973. Bien que classé comme un groupe de hard rock et parfois associé au heavy metal, les membres du groupe ont toujours préféré décrire leur style musical comme du rock 'n' roll. Ils revendiquent également une influence notable du blues.",114,"fr:AC/DC","c:8/80/ACDC_Tacoma.jpg",{"cats":["chanteurs_int","groupes"]}],["Q126826",352,"groupe","Aerosmith","C","Aerosmith est un groupe de rock américain originaire de Boston dans le Massachusetts.",null,"fr:Aerosmith","c:e/e7/Aerosmith_member.png",{"cats":["chanteurs_int","groupes"]}],["Q51118",353,"groupe","AKB48","C","AKB48 est un groupe féminin japonais de J-pop créé en 2005, à l'effectif changeant, composé à l'origine de vingt jeunes chanteuses et idoles réparties en cinq équipes: Team A, Team K, Team B, Team 4 et Team 8. La Team 4, qui avait été dissoute en 2012, a été reformée l'année suivante. Le 29 avril 2023, toutes les Team ont été dissoutes à part la Team 8.",119,"fr:AKB48","c:f/fa/AKB48_at_the_2010_Asia_Song_Festival_%282%29.jpg"],["Q484255",354,"groupe","Alice in Chains","PC","Alice in Chains est un groupe américain de metal alternatif, originaire de Seattle, dans l'État de Washington. Formé en 1987 par le guitariste et chanteur Jerry Cantrell et le chanteur Layne Staley, il s'agit de l'un des groupes de grunge les plus notoires, faisant partie du Big Four of Seattle aux côtés de Nirvana, Pearl Jam et Soundgarden.","Alice in Chains est un groupe américain de metal alternatif, originaire de Seattle, dans l'État de Washington.","fr:Alice_in_Chains","c:9/94/Alice_In_Chains.jpg"],["Q109871",355,"groupe","Anthrax","C","Anthrax est un groupe américain de thrash metal, originaire de New York. Formé en 1981 par les guitaristes Scott Ian et Danny Lilker, le groupe recense, en 2016, douze albums studio, vingt singles, et un split EP avec Public Enemy. Le groupe est l'un des plus populaires de la scène thrash metal des années 1980, dont il contribue à l'émergence au milieu et à la fin des années 1980, faisant partie du « Big Four of Thrash » aux côtés de Metallica, Megadeth et Slayer.","Anthrax est un groupe américain de thrash metal, originaire de New York.","fr:Anthrax_(groupe)","c:b/ba/Anthrax_at_Wacken_Open_Air_2013_02.jpg"],["Q170599",356,"groupe","Arctic Monkeys","C","Arctic Monkeys est un groupe britannique de rock indépendant, originaire de Sheffield, Yorkshire du Sud, en Angleterre. Il est formé en 2002, plus précisément à High Green, une banlieue de Sheffield. Le groupe est composé d'Alex Turner, de Jamie Cook, de Nick O'Malley, et de Matt Helders. Ancien membre du groupe, Andy Nicholson quitte la formation en 2006, peu après la sortie du premier album.","Arctic Monkeys est un groupe britannique de rock indépendant, originaire de Sheffield, Yorkshire du Sud, en Angleterre.","fr:Arctic_Monkeys","c:0/04/Arctic_Monkeys_-_Orange_Stage_-_Roskilde_Festival_2014.jpg",{"cats":["chanteurs_int","groupes"]}],["Q486830",357,"groupe","Audioslave","C","Audioslave est un supergroupe américain de rock alternatif originaire de Los Angeles, en Californie. Formé en 2001 et dissous en 2007, le quartette se composait du chanteur et guitariste Chris Cornell, ancien membre de Soundgarden, du guitariste Tom Morello, du bassiste Tim Commerford, et du batteur Brad Wilk, anciens membres de Rage Against the Machine.","Audioslave est un supergroupe américain de rock alternatif originaire de Los Angeles, en Californie.","fr:Audioslave","c:b/b5/Audioslave_2005.jpg"],["Q165193",358,"groupe","Avenged Sevenfold","C","Avenged Sevenfold est un groupe américain de heavy metal, originaire de Huntington Beach, en Californie. Le groupe a longtemps été un pilier de la scène underground californienne avant d'évoluer vers une musique plus mélodique qui a permis au groupe de connaître le succès avec l'album City of Evil et l'album éponyme Avenged Sevenfold. Fondé par M. Shadows, Zacky Vengeance, The Rev et Matt Wendt à la fin des années 1990, la composition actuelle du groupe est: M.","Avenged Sevenfold est un groupe américain de heavy metal, originaire de Huntington Beach, en Californie.","fr:Avenged_Sevenfold","c:c/cb/Avenged_Sevenfold-Rock_im_Park_2014_by_2eight_DSC5963.jpg",{"cats":["chanteurs_int","groupes"]}],["Q11190781",359,"groupe","Babymetal","C","Babymetal, stylisé BABYMETAL, est un groupe de J-pop et heavy metal japonais, originaire de Tokyo. Formé en 2010, il est composé de trois jeunes idoles japonaises et produit par l'agence de talent Amuse, Inc. Il s'agit du deuxième sous-groupe, après les Twinklestars, du groupe féminin Sakura Gakuin dont les membres faisaient partie en parallèle.","Babymetal, stylisé BABYMETAL, est un groupe de J-pop et heavy metal japonais, originaire de Tokyo.","fr:Babymetal","c:9/99/Babymetal_waving_flags_-_Z%C3%A9nith_Paris.jpg"],["Q17140",360,"groupe","Backstreet Boys","R","Les Backstreet Boys est un groupe de pop américain formé en 1993 à Orlando, en Floride. Le boys band est originellement composé de Brian Littrell, Nick Carter, Kevin Richardson, Howie Dorough et A. J. McLean. Ils ont vendu plus de 130 millions d'albums à travers le monde et ont gagné un nombre important de prix de l'industrie de la musique et du disque. Il s'agit du boys band le plus vendeur de toute l'histoire de la musique de tous les temps.","Les Backstreet Boys est un groupe de pop américain formé en 1993 à Orlando, en Floride.","fr:Backstreet_Boys","c:9/9a/Backstreet_Boys_2019_by_Glenn_Francis.jpg"],["Q214039",361,"groupe","Beastie Boys","C","Beastie Boys est un groupe de hip-hop américain, originaire des quartiers de Manhattan et de Brooklyn, à New York. Pendant la majeure partie de son existence, le groupe se compose de Michael « Mike D » Diamond, Adam « MCA » Yauch et Adam « Ad-Rock » Horovitz. Plusieurs autres musiciens et disc jockeys, tels que Michael « Mix Master Mike » Schwartz, jouent également au sein du groupe, certains d'entre eux pendant une durée importante, tels DJ Hurricane ou Eric Bobo.","Beastie Boys est un groupe de hip-hop américain, originaire des quartiers de Manhattan et de Brooklyn, à New York.","fr:Beastie_Boys","c:0/08/Beastie_Boys_Compo.jpg"],["Q133405",362,"groupe","Bee Gees","PC","Bee Gees est un groupe australo-britannique de pop, originaire de Brisbane, dans le Queensland, en Australie. Il est formé en 1958 par trois des frères Gibb, originaires de Douglas au Royaume-Uni: Barry et les jumeaux Robin et Maurice, initialement associés à un guitariste et un batteur, tous australiens. Le total des ventes de disques du groupe sur toute sa carrière est estimé à 220 millions, faisant de lui l'un des plus grands vendeurs de disques.","Bee Gees est un groupe australo-britannique de pop, originaire de Brisbane, dans le Queensland, en Australie.","fr:Bee_Gees","c:d/d0/The_Bee_Gees.png"],["Q134541",363,"groupe","Black Eyed Peas","C","Black Eyed Peas est un groupe de hip-hop américain formé à Los Angeles, en Californie. Le groupe est à l'origine et actuellement composé de will.i.am, apl.de.ap et de Taboo. Le groupe est principalement influencé par le hip-hop et la musique électronique.","Black Eyed Peas est un groupe de hip-hop américain formé à Los Angeles, en Californie.","fr:Black_Eyed_Peas","c:3/3d/Black_Eyed_Peas_at_Walmart_meeting.jpg"],["Q47670",364,"groupe","Black Sabbath","PC","Black Sabbath est un groupe britannique de rock orienté hard rock, originaire de Birmingham, en Angleterre. Il est souvent considéré aujourd'hui, autant par la presse spécialisée que par le public contemporain, comme l'un des groupes fondateurs et précurseurs du heavy metal, voire comme le premier groupe de ce genre de musique.","Black Sabbath est un groupe britannique de rock orienté hard rock, originaire de Birmingham, en Angleterre.","fr:Black_Sabbath","c:4/42/Sabs.jpg",{"cats":["chanteurs_int","groupes"]}],["Q482477",365,"groupe","Blink-182","PC","Blink-182 est un groupe américain de pop punk, originaire de Poway, en Californie. Formé en 1992, le groupe se compose actuellement du chanteur et guitariste Tom Delonge, du chanteur et bassiste Mark Hoppus et du batteur Travis Barker.","Blink-182 est un groupe américain de pop punk, originaire de Poway, en Californie.","fr:Blink-182","c:d/d8/Blink-182_2011-12-11_10.jpg",{"cats":["chanteurs_int","groupes"]}],["Q202741",366,"groupe","Blondie","C","Blondie est un groupe américain de rock, originaire de New York. Il est formé en 1974 par Deborah Harry et Chris Stein. Pionnier de la scène punk new yorkaise des années 1970, le groupe devient célèbre pour son mélange électrique de styles musicaux intégrant des éléments disco, pop, funk, reggae tout en conservant une base new wave.","Blondie est un groupe américain de rock, originaire de New York.","fr:Blondie_(groupe)","c:f/fc/Blondie1977.jpg"],["Q485820",367,"groupe","Blur","C","Blur est un groupe de rock britannique, originaire de Londres, en Angleterre. Formé en 1989, il est composé du chanteur Damon Albarn, du guitariste Graham Coxon, du bassiste Alex James et du batteur Dave Rowntree. Comme Oasis, ce groupe est emblématique de la britpop des années 1990, les deux groupes étant alors décrits comme rivaux. Blur est connu pour des chansons comme Song 2 ou Girls and Boys.","Blur est un groupe de rock britannique, originaire de Londres, en Angleterre.","fr:Blur","c:d/d5/Blur_%28band%29.png"],["Q259254",368,"groupe","Bon Jovi","C","Bon Jovi est un groupe américain de rock, originaire de Sayreville, dans le New Jersey. Son nom provient du leader et chanteur principal, Jon Bon Jovi.","Bon Jovi est un groupe américain de rock, originaire de Sayreville, dans le New Jersey.","fr:Bon_Jovi","c:7/70/Bon_Jovi_1.jpg",{"cats":["chanteurs_int","groupes"]}],["Q156298",369,"groupe","Boney M.","PC","Boney M. est un groupe de disco et pop, originaire d'Allemagne de l'Ouest. Il est formé et dirigé par le compositeur et producteur allemand Frank Farian. Les quatre membres originels du groupe sont Bobby Farrell, Liz Mitchell, Maizie Williams et Marcia Barrett. Reggie Tsiboe se joint au groupe en 1982, après le départ de Bobby Farell et jusqu'à son retour.","Boney M.","fr:Boney_M.","c:c/c8/Boney_M_1981.jpg"],["Q494784",370,"groupe","Bring Me the Horizon","C","Bring Me the Horizon, parfois abrégé BMTH, est un groupe de metal britannique, originaire de Sheffield, dans le Yorkshire. Bring Me the Horizon est devenu au fil des années une figure emblématique de la scène post-hardcore et rock en général.",111,"fr:Bring_Me_the_Horizon","c:0/0a/2016_RiP_Bring_Me_the_Horizon_-_by_2eight_-_DSC6735.jpg",{"cats":["chanteurs_int","groupes"]}],["Q371938",371,"groupe","Chicago","C","Chicago est un groupe américain de pop rock et jazz-rock originaire de la ville de Chicago, troisième métropole des États-Unis, au nord-est de l'Illinois.",115,"fr:Chicago_(groupe)","c:d/df/Chicago_1975_press_photo.jpg"],["Q45188",372,"groupe","Coldplay","C","Coldplay est un groupe britannique de pop rock, originaire de Londres, en Angleterre. Il est formé en 1996 par l'auteur-compositeur-interprète Chris Martin et le guitariste Jonny Buckland. Le bassiste Guy Berryman rejoint ensuite le groupe, avant que le batteur Will Champion ne vienne compléter le quatuor. Le producteur Phil Harvey s'associe à leur projet en tant que manager.","Coldplay est un groupe britannique de pop rock, originaire de Londres, en Angleterre.","fr:Coldplay","c:c/cc/ColdplayWembley120925_%28cropped%29.jpg"],["Q203736",373,"groupe","Cream","C","Cream est un supergroupe britannique de rock originaire de Londres, en Angleterre. Il est actif de 1966 à 1968 et composé du guitariste chanteur Eric Clapton, du bassiste chanteur Jack Bruce et du batteur Ginger Baker. À la suite de la mort de Jack Bruce en 2014 et de celle de Ginger Baker en 2019, Eric Clapton est l'unique membre encore vivant du groupe.","Cream est un supergroupe britannique de rock originaire de Londres, en Angleterre.","fr:Cream","c:5/58/Cream_Clapton_Bruce_Baker_1960s.jpg"],["Q192463",374,"groupe","Creedence Clearwater Revival","PC","Creedence Clearwater Revival est un groupe américain de rock aux influences blues et country, originaire d'El Cerrito au nord de la baie de San Francisco.",117,"fr:Creedence_Clearwater_Revival","c:e/ee/Creedence_Clearwater_Revival_1968.jpg"],["Q101505",375,"groupe","Deep Purple","PC","Deep Purple est un groupe britannique de rock, originaire de Hertford en Angleterre. Formé en 1968, il compte parmi les pionniers du genre hard rock.","Deep Purple est un groupe britannique de rock, originaire de Hertford en Angleterre.","fr:Deep_Purple","c:9/92/2022_Lieder_am_See_-_Deep_Purple_-_by_2eight_-_7DS2745.jpg",{"cats":["chanteurs_int","groupes"]}],["Q182890",376,"groupe","Def Leppard","C","Def Leppard est un groupe de rock anglais, formé en 1976 à Sheffield. Depuis 1992, il est composé de Rick Savage, Joe Elliott, Rick Allen, Phil Collen et Vivian Campbell. Le groupe s'est fait connaître au sein de la new wave of British heavy metal au début des années 1980, avec un succès commercial maximal entre les années 1980 et le milieu des années 1990.","Def Leppard est un groupe de rock anglais, formé en 1976 à Sheffield.","fr:Def_Leppard","c:7/7b/DefLeppard1.JPG"],["Q485039",377,"groupe","Deftones","C","Deftones est un groupe de métal alternatif américain, originaire de Sacramento. Avec Korn, ils sont considérés comme les fondateurs du nu metal, et également considérés comme l'un des groupes les plus novateurs et les plus influents du genre.","Deftones est un groupe de métal alternatif américain, originaire de Sacramento.","fr:Deftones","c:4/4d/Deftones_live_brixton_academy_2007.jpg",{"cats":["chanteurs_int","groupes"]}],["Q482964",378,"groupe","Depeche Mode","PC","Depeche Mode est un groupe britannique de musique électronique et de rock alternatif, affilié à la new wave, originaire de Basildon, dans l'Essex. Formé en 1980, il apparaît au sein du courant de la synthpop et devient rapidement influent et populaire sur la scène internationale. Son nom est issu du magazine français Dépêche Mode.",119,"fr:Depeche_Mode","c:4/47/Tierecke_dm.jpg"],["Q153056",379,"groupe","Destiny's Child","C","Destiny's Child est un groupe féminin américain de R'n'B composé au sommet de sa gloire par LaTavia Roberson, LeToya Luckett, Michelle Williams, Farrah Franklin, Kelly Rowland et Beyoncé Knowles.",116,"fr:Destiny's_Child","c:c/cc/Destiny_Child_at_Super_Bowl_XLVII_halftime_show.jpg"],["Q50040",380,"groupe","Dire Straits","C","Dire Straits est un groupe britannique de rock créé à Deptford durant l'été 1977 par Mark Knopfler, son frère David Knopfler, John Illsley et Pick Withers. Considéré comme l'un des plus grands groupes rock de tous les temps à l'instar de Pink Floyd ou Queen, Dire Straits a vendu plus de 140 millions d'albums depuis ses débuts.",115,"fr:Dire_Straits","c:a/a2/Dire_straits_22101985_23_800.jpg"],["Q58381",381,"groupe","Duran Duran","PC","Duran Duran est un groupe de new wave britannique, originaire de Birmingham dans les Midlands de l'Ouest. Il fait partie un temps de la vague Nouveaux Romantiques associée à la new wave des années 1980. Le groupe est formé en 1978 par Nick Rhodes et John Taylor. Ils sont ensuite rejoints par Roger Taylor, Andy Taylor et Simon Le Bon. Les trois Taylor du groupe n'ont aucun lien de parenté entre eux, ni avec Roger Taylor.","Duran Duran est un groupe de new wave britannique, originaire de Birmingham dans les Midlands de l'Ouest.","fr:Duran_Duran","c:f/f6/Duran_Duran.jpg"],["Q189635",382,"groupe","Eagles","E","Eagles est un groupe américain de rock, originaire de Los Angeles, en Californie. Le groupe se forme en 1971 et adopte un style aux influences country et bluegrass, connu sous le nom de « West Coast Sound ».","Eagles est un groupe américain de rock, originaire de Los Angeles, en Californie.","fr:Eagles","c:1/11/The_Eagles_in_performance%2C_2008.jpg"],["Q28974",383,"groupe","Earth, Wind and Fire","C","Earth, Wind and Fire est un groupe de funk disco américain originaire de Chicago dans l'Illinois. Le groupe est formé en 1969 à l'initiative de Maurice White. Il est notamment connu pour les tubes Fantasy, September, Boogie Wonderland ou Let's Groove.","Earth, Wind and Fire est un groupe de funk disco américain originaire de Chicago dans l'Illinois.","fr:Earth,_Wind_and_Fire","c:4/4d/Earth_Wind_and_Fire.jpg"],["Q218255",384,"groupe","Electric Light Orchestra","C","Electric Light Orchestra, souvent abrégé ELO, est un groupe britannique de rock originaire de Birmingham en Angleterre.",null,"fr:Electric_Light_Orchestra","c:2/2c/Elo_27041978_04_800.jpg"],["Q185144",385,"groupe","Europe","PC","Europe est un groupe suédois de Glam metal et de hard rock, originaire de Upplands Väsby, en Suède. Depuis sa formation en 1979, Europe compte onze albums studio, plusieurs albums live, ainsi que de nombreuses compilations de leurs meilleures chansons. Europe s'inspire de plusieurs groupes de hard rock comme Iron Maiden, Scorpions, AC/DC, Led Zeppelin, UFO, Deep Purple, Whitesnake, Rainbow, Michael Schenker Group, Thin Lizzy, Kiss...","Europe est un groupe suédois de Glam metal et de hard rock, originaire de Upplands Väsby, en Suède.","fr:Europe_(groupe)","c:b/b1/Europe_the_band_in_Stockholm_2016.jpg"],["Q1777698",386,"groupe","Evanescence","C","Evanescence est un groupe américain de metal alternatif, originaire de Little Rock. Il est formé en 1995 par la chanteuse Amy Lee et le guitariste Ben Moody.","Evanescence est un groupe américain de metal alternatif, originaire de Little Rock.","fr:Evanescence","c:0/09/Evanescence_at_The_Wiltern_theatre_in_Los_Angeles%2C_California_08.jpg",{"cats":["chanteurs_int","groupes"]}],["Q485811",387,"groupe","Fall Out Boy","C","Fall Out Boy est un groupe de rock américain, originaire de Wilmette, près de Chicago. Formé en 2001, il est composé de Patrick Stump, Pete Wentz, Joe Trohman et Andrew Hurley. Ils connaissent un certain succès dès leurs débuts sous label discographique avec leur deuxième album From Under the Cork Tree. Sorti en 2005, cet album s'est vendu à plus de 2,5 millions d'exemplaires rien qu'aux États-Unis, où il a été certifié double disque de platine.","Fall Out Boy est un groupe de rock américain, originaire de Wilmette, près de Chicago.","fr:Fall_Out_Boy","c:5/58/Fall_Out_Boy%2C_Heaven%2C_London_%2852755936394%29.jpg",{"cats":["chanteurs_int","groupes"]}],["Q106648",388,"groupe","Fleetwood Mac","R","Fleetwood Mac est un groupe de pop-rock britannique originaire de Londres.",null,"fr:Fleetwood_Mac","c:8/8b/Fleetwood_Mac_2009.jpg"],["Q483718",389,"groupe","Foo Fighters","PC","Foo Fighters est un groupe américain de rock, formé à Seattle, Washington. Il est formé en 1994 durant la dissolution de Nirvana, à la suite de la mort de son leader Kurt Cobain. Dave Grohl, le batteur du groupe, se lance alors dans son projet, un album intitulé Foo Fighters sur lequel il enregistre tous les instruments à l'exception de quelques titres enregistrés avec l'aide de Krist Novoselic, ancien bassiste de Nirvana, et Pat Smear, ancien guitariste live de ce même groupe et membre des Germs.","Foo Fighters est un groupe américain de rock, formé à Seattle, Washington.","fr:Foo_Fighters","c:4/4b/FoosLondonStad220618-124_%2842989552522%29.jpg",{"cats":["chanteurs_int","groupes"]}],["Q275059",390,"groupe","Foreigner","C","Foreigner est un groupe américano-britannique de hard rock, originaire de New York. Il est formé en 1976 par deux musiciens britanniques reconnus, Mick Jones anciennement guitariste pour Spooky Tooth et Ian McDonald, multi-instrumentiste ayant joué avec King Crimson et McDonald and Giles, ainsi qu'un chanteur américain jusqu'alors inconnu, Lou Gramm. En 2014, le groupe compte plus de 80 millions d'albums vendus à travers le monde. Ce qui fait de ce groupe l'un des meilleurs vendeurs de tous les temps.","Foreigner est un groupe américano-britannique de hard rock, originaire de New York.","fr:Foreigner","c:7/72/Foreigner2009.jpg"],["Q151012",391,"groupe","Genesis","PC","Genesis est un groupe britannique de rock, considéré comme un des pionniers du genre progressif. Il connaît un succès important à partir des années 1970, culminant dans les décennies 1980 et 1990. Peter Gabriel et Phil Collins, initialement batteur du groupe et remplaçant le premier au chant après son départ en 1975, en sont les figures emblématiques. Avec environ 150 millions d'albums vendus à travers le monde, Genesis se classe parmi les trente artistes et groupes ayant vendu le plus d'albums de tous les temps.","Genesis est un groupe britannique de rock, considéré comme un des pionniers du genre progressif.","fr:Genesis_(groupe)","c:b/bc/GenesisO2260322_%2813_of_42%29_%2851963210611%29.jpg"],["Q189991",392,"groupe","Gorillaz","R","Gorillaz est un groupe musical britannique dit « virtuel », formé à Londres en 1998 par Damon Albarn et Jamie Hewlett. Il est composé de quatre personnages de fiction: Stuart Tusspot, dit 2D, au chant, au piano ainsi qu'à tout instrument avec des touches; Murdoc Niccals à la basse; Russel Hobbs à la batterie; et Noodle à la guitare. En réalité, la musique est une collaboration entre de nombreux musiciens, mais implique en permanence Damon Albarn.","Gorillaz est un groupe musical britannique dit « virtuel », formé à Londres en 1998 par Damon Albarn et Jamie Hewlett.","fr:Gorillaz","https://upload.wikimedia.org/wikipedia/commons/thumb/c/c7/Gorillaz_logo.svg/330px-Gorillaz_logo.svg.png"],["Q212533",393,"groupe","Grateful Dead","C","Grateful Dead est un groupe de rock américain, originaire de Palo Alto.",null,"fr:Grateful_Dead","c:6/6b/Grateful_Dead_%281970%29.png"],["Q47871",394,"groupe","Green Day","PC","Green Day est un groupe de punk rock américain, originaire de Berkeley, en Californie. Formé en 1987 sous le nom de Sweet Children avant de prendre son nom définitif en 1989, le groupe est composé à l'origine du chanteur, guitariste et leader du groupe Billie Joe Armstrong et du bassiste Mike Dirnt. Ils sont rejoints en 1988 par le batteur John Kiffmeyer, qui sera remplacé à partir de 1992 par Tré Cool en raison d'une trop faible implication de sa part dans le groupe.","Green Day est un groupe de punk rock américain, originaire de Berkeley, en Californie.","fr:Green_Day","c:0/00/Green_Day_2017_Germany.png",{"cats":["chanteurs_int","groupes"]}],["Q11895",395,"groupe","Guns N' Roses","PC","Guns N' Roses est un groupe américain de hard rock, originaire de Los Angeles.",null,"fr:Guns_N'_Roses","c:a/a3/GNR_London_Stadium_2017_3_%28cropped%29.jpg",{"cats":["chanteurs_int","groupes"]}],["Q391348",396,"groupe","Imagine Dragons","C","Imagine Dragons est un groupe de pop rock américain, originaire de Las Vegas dans le Nevada, et formé en 2008. Avec sept albums au total, le groupe totalise 74 millions d’albums vendus et 160 milliards de streams dans le monde entier. Remportant trois American Music Awards, dix Billboard Music Awards et un Grammy Award en 2014, Imagine Dragons est devenu l'un des groupes de pop-rock les plus emblématiques de cette dernière décennie.","Imagine Dragons est un groupe de pop rock américain, originaire de Las Vegas dans le Nevada, et formé en 2008.","fr:Imagine_Dragons","c:b/b9/Imagine_Dragons_-_Untold_2023_-_53114967442.jpg",{"cats":["chanteurs_int","groupes"]}],["Q489801",397,"groupe","INXS","C","INXS est un groupe de rock australien, originaire de Sydney, formé en 1977 et séparé en 2012. Avec des titres à succès tels qu'Original Sin, Need You Tonight, Devil Inside, Never Tear Us Apart ou Suicide Blonde, il constitue l'un des incontournables de la musique australienne, aux côtés, entre autres, de Midnight Oil, d'AC/DC, de Nick Cave et de Kylie Minogue.","INXS est un groupe de rock australien, originaire de Sydney, formé en 1977 et séparé en 2012.","fr:INXS","c:5/5e/INXS_performs_at_Campbelltown_RSL_Club%2C_Sydney.jpg"],["Q42482",398,"groupe","Iron Maiden","PC","Iron Maiden est un groupe britannique de heavy metal formé en décembre 1975 par le bassiste Steve Harris, rejoint très rapidement par le guitariste Dave Murray. Il figure parmi les pionniers de la new wave of British heavy metal. Sa formation, qui a changé à plusieurs reprises, est depuis 1999 composée de Steve Harris à la basse, Bruce Dickinson au chant, Dave Murray, Adrian Smith et Janick Gers aux guitares, et Nicko McBrain à la batterie.",118,"fr:Iron_Maiden","c:0/0d/Iron_Maiden_in_the_Palais_Omnisports_of_Paris-Bercy_%28France%29.jpg",{"cats":["chanteurs_int","groupes"]}],["Q202041",399,"groupe","Jamiroquai","C","Jamiroquai est un groupe britannique d'acid jazz et funk, originaire de Londres, en Angleterre. Mené par le chanteur Jay Kay, il se fait une place dans la capitale, au début des années 1990, dans le mouvement acid jazz, alors en plein essor. Jamiroquai se démarque vite parmi les groupes de l'époque (Incognito, Brand New Heavies, Galliano ou Corduroy). Le groupe acquiert une renommée mondiale, tout en faisant évoluer sa musique.","Jamiroquai est un groupe britannique d'acid jazz et funk, originaire de Londres, en Angleterre.","fr:Jamiroquai","c:3/3e/JamiroquaiAtChicago.jpg"],["Q488260",400,"groupe","Jefferson Airplane","C","Jefferson Airplane est un groupe américain de rock psychédélique, originaire de San Francisco, en Californie. Rattaché au San Francisco Sound, il est l'un des précurseurs du mouvement psychédélique. Le groupe est entré au Rock and Roll Hall of Fame en 1996.","Jefferson Airplane est un groupe américain de rock psychédélique, originaire de San Francisco, en Californie.","fr:Jefferson_Airplane","c:f/fa/Jefferson_Airplane_photo_1967.JPG"],["Q192353",401,"groupe","Jethro Tull","C","Jethro Tull est un groupe britannique de rock, originaire de Blackpool, en Angleterre, formé dans la seconde partie des années 1960. Sa musique est marquée par le style vocal très particulier du leader Ian Anderson et son travail unique de flûtiste, et par des constructions de chansons inhabituelles et souvent complexes. La musique du groupe incorpore des éléments de musique classique, celtique, hard rock, blues ainsi que des phases d'art rock alternatif et de rock progressif.",119,"fr:Jethro_Tull_(groupe)","c:c/cf/Jethro_Tull%2C_Iceland_2023.jpg"],["Q134233",402,"groupe","Jonas Brothers","C","Les Jonas Brothers est un groupe américain de pop rock constitué de trois frères originaires de Wyckoff dans le New Jersey: Kevin Jonas, Joe Jonas et Nick Jonas. Ils ont sorti six albums: It's About Time en 2006, Jonas Brothers en 2007, puis A Little Bit Longer en 2008, Lines, Vines and Trying Times en 2009, Happiness Begins en 2019, et enfin The Album en 2023. Ils ont aussi sorti, en 2010, un album réunissant les chansons de leur série Jonas L. A..",115,"fr:Jonas_Brothers","c:8/83/Jonas_Brothers_Happiness_Begins_Tour_2019.png"],["Q464749",403,"groupe","Journey","PC","Journey est un groupe américain de rock fondé en 1973 à San Francisco autour de Neal Schon et Gregg Rolie, anciens musiciens du groupe Santana. Le plus fort de son succès commercial a eu lieu entre 1978 et 1987, après quoi le groupe s'est temporairement séparé. Le groupe s'est ensuite reformé dans les années 1990 avec une succession de chanteurs.",114,"fr:Journey_(groupe)","c:7/73/Journey_band.JPG"],["Q172763",404,"groupe","Joy Division","C","Joy Division est un groupe de rock britannique, originaire de Manchester, en Angleterre, formé en 1976 par Ian Curtis, Peter Hook, Stephen Morris et Bernard Sumner.",118,"fr:Joy_Division","https://upload.wikimedia.org/wikipedia/en/thumb/a/a0/Joy_Division_promo_photo.jpg/330px-Joy_Division_promo_photo.jpg"],["Q83468",405,"groupe","Judas Priest","C","Judas Priest est un groupe britannique de heavy metal traditionnel, originaire de Birmingham. Formé en 1969 par le guitariste K. K. Downing et le bassiste Ian Hill, Judas Priest est l'un des groupes les plus influents de la scène heavy metal, notamment grâce à la voix au registre très étendu du chanteur Rob Halford, à son style musical caractérisé par l'utilisation de deux guitaristes solistes, et à ses performances scéniques hautes en pyrotechnie.","Judas Priest est un groupe britannique de heavy metal traditionnel, originaire de Birmingham.","fr:Judas_Priest","c:2/2d/Judas_Priest%2C_p%C3%A4%C3%A4lava%2C_Sauna_Open_Air_2011%2C_Tampere%2C_11.6.2011_%2825%29.JPG"],["Q189382",406,"groupe","King Crimson","C","King Crimson est un groupe britannique de rock, originaire de Londres, en Angleterre. Il est considéré comme l'un des représentants majeurs du rock progressif, sa musique mêlant aussi jazz-rock et rock expérimental. Sa composition change continuellement tout au long de son histoire. Le guitariste Robert Fripp en est le seul membre permanent, mais il déclare qu'il ne se considère pas nécessairement comme son chef.","King Crimson est un groupe britannique de rock, originaire de Londres, en Angleterre.","fr:King_Crimson","c:3/3c/King_crimson_1974_press_photo.jpg"],["Q192486",407,"groupe","Kings of Leon","C","Kings of Leon est un groupe de rock alternatif américain, originaire de Nashville, dans le Tennessee. Formé en 1999, le groupe est composé de trois frères et d'un cousin, le nom du groupe provient du père et du grand-père de Nathan, Caleb et Jared, appelés tous deux Leon. Ils sont considérés comme le pendant sudiste des Strokes, proposant un mélange de rock sudiste, garage rock, post-punk, country et de blues.","Kings of Leon est un groupe de rock alternatif américain, originaire de Nashville, dans le Tennessee.","fr:Kings_of_Leon","c:f/f4/Kings_Of_Leon_-_Sheffield_Arena_-_Saturday_10th_June_2017_KOLSheffield100617-21_%2834869652730%29.jpg"],["Q124179",408,"groupe","Kiss","PC","Kiss est un groupe américain de pop rock et de glam metal, originaire de New York. Il est formé en janvier 1973 par le guitariste Paul Stanley et le bassiste Gene Simmons. Très populaires, notamment grâce à leurs maquillages, leurs costumes extravagants, leurs nombreux effets spéciaux sur scène et la célèbre très grande langue de Gene Simmons, les membres de Kiss ont vendu plus de 60 millions d'albums aux États-Unis; Kiss est un des groupes les plus vendeurs de l'histoire de la musique.","Kiss est un groupe américain de pop rock et de glam metal, originaire de New York.","fr:Kiss_(groupe_américain)","c:9/9a/Kiss_%C3%A0_Paris_-_Bercy_le_7_juin_2022.jpg",{"cats":["chanteurs_int","groupes"]}],["Q80304",409,"groupe","Korn","C","Korn, stylisé KoЯn, est un groupe de nu metal américain, originaire de Bakersfield, en Californie. En 2017, le groupe se compose de Brian « Head » Welch et James « Munky » Shaffer à la guitare, de Reginald « Fieldy » Arvizu à la basse, de Jonathan Davis au chant et Ray Luzier à la batterie.","Korn, stylisé KoЯn, est un groupe de nu metal américain, originaire de Bakersfield, en Californie.","fr:Korn","c:f/f7/Korn%2C_2013.jpg",{"cats":["chanteurs_int","groupes"]}],["Q2331",410,"groupe","Led Zeppelin","R","Led Zeppelin est un groupe de rock britannique originaire de Londres, fondé à l'été 1968 par Jimmy Page, avec Robert Plant, John Paul Jones et John Bonham. Le groupe se sépare en 1980 après la mort de Bonham. Reconnu pour son son distinctif, dominé par la virtuosité des riffs de guitare de Page, la voix puissante de Plant, l'excellence de Jones et le groove et la force de frappe unique de Bonham, Led Zeppelin est aujourd'hui considéré comme l'un des plus grands groupes de rock, aussi bien pour son succès…",116,"fr:Led_Zeppelin","c:4/49/LedZeppelinmontage.jpg",{"cats":["chanteurs_int","groupes"]}],["Q240767",411,"groupe","Limp Bizkit","C","Limp Bizkit est un groupe de nu metal américain, originaire de Jacksonville, en Floride. Grand représentant du nu metal de par son mélange entre rap et metal, le groupe définit néanmoins sa musique comme étant du « pimp-rock ». En 2010, Limp Bizkit dénombre 35 millions d'albums vendus à travers le monde. Le nom du groupe est une déformation de Limp Biscuit.","Limp Bizkit est un groupe de nu metal américain, originaire de Jacksonville, en Floride.","fr:Limp_Bizkit","c:d/d5/Limp_Bizkit_Baltimore_2013.jpg",{"cats":["chanteurs_int","groupes"]}],["Q261",412,"groupe","Linkin Park","R","Linkin Park est un groupe américain de metal et nu metal, originaire d'Agoura Hills, en Californie. Il se compose depuis 2023 de Mike Shinoda; Emily Armstrong; Brad Delson; Joe Hahn; Dave Farrell et Colin Brittain (batterie,","Linkin Park est un groupe américain de metal et nu metal, originaire d'Agoura Hills, en Californie.","fr:Linkin_Park","c:d/d8/Linkin_Park_-_From_Zero_Lead_Press_Photo_-_James_Minchin_III.jpg",{"cats":["chanteurs_int","groupes"]}],["Q158419",413,"groupe","Little Mix","C","Little Mix est un girl group anglais composé de Perrie Edwards, Jade Thirlwall et Leigh-Anne Pinnock, réduit à trois après que Jesy Nelson a quitté le groupe pour raison de santé mentale. Elles se font connaître en devenant le premier groupe à remporter l'émission britannique The X Factor en 2011. Leur style musical est principalement pop, dance-pop et RnB, avec des influences de tropical house, pop latino et électro.",116,"fr:Little_Mix","c:f/f2/Little_Mix_at_the_Confetti_Tour_in_Leeds_%282%29.png"],["Q158462",414,"groupe","Lynyrd Skynyrd","R","Lynyrd Skynyrd est un groupe américain de rock sudiste originaire de Jacksonville en Floride.",null,"fr:Lynyrd_Skynyrd","c:5/56/Lynyrd_Skynyrd_CIA_Cardiff_2010.jpg"],["Q182223",415,"groupe","Maroon 5","C","Maroon 5 est un groupe de musique pop américain, originaire de Los Angeles, en Californie. Le groupe est récompensé à de nombreuses reprises pour son premier album Songs About Jane, sorti en juin 2002, qui se retrouve en tête des classements musicaux de nombreux pays. De même, leur second album, 1.22.03.Acoustic, qui reprend des titres en version acoustique de l'album Songs About Jane, est certifié disque de platine.","Maroon 5 est un groupe de musique pop américain, originaire de Los Angeles, en Californie.","fr:Maroon_5","c:4/41/Maroon_5_Current_Lineup_Collage.jpg"],["Q357418",416,"groupe","Massive Attack","C","Massive Attack est un groupe musical britannique formé en 1988, originaire de Bristol, précurseur de la musique trip hop. Il se compose, à l'origine, de Robert Del Naja, Adrian Thaws, Grant Marshall et Andrew Vowles. Le style du groupe est en constante évolution: au début proche du hip-hop, du groove, voire de la soul, il aborde par la suite la musique électronique, et un son plus électrique à la fin des années 1990.",116,"fr:Massive_Attack","c:2/2b/Massive_Attack_composite.jpg"],["Q485116",417,"groupe","Mayhem","C","Mayhem est un groupe de black metal norvégien, originaire d'Oslo, formé en 1984. La carrière de Mayhem fait grandement polémique, en particulier en raison de la violence des prestations scéniques, mais aussi à la suite du suicide du chanteur Per Yngve Ohlin en 1991 et à l'assassinat du guitariste Euronymous par l'ancien membre Varg Vikernes, de Burzum.","Mayhem est un groupe de black metal norvégien, originaire d'Oslo, formé en 1984.","fr:Mayhem","c:8/82/Mayhem%2C_Summer_Dying_Loud_2024_22.jpg"],["Q15920",418,"groupe","Metallica","R","Metallica est un groupe américain de heavy metal, originaire de Californie. Il est considéré comme l'un des plus grands groupes de metal de tous les temps. Formé à Los Angeles en 1981, le groupe est composé de James Hetfield et Lars Ulrich, ainsi que du guitariste Kirk Hammett et du bassiste Robert Trujillo, qui a rejoint le groupe en 2003. Les précédents membres du groupe incluent Dave Mustaine, les bassistes Ron McGovney, Cliff Burton et Jason Newsted.","Metallica est un groupe américain de heavy metal, originaire de Californie.","fr:Metallica","c:8/81/Metallica_March_2024.jpg",{"cats":["chanteurs_int","groupes"]}],["Q1070606",419,"groupe","Momoiro Clover Z","C","Momoiro Clover Z, ou en abrégé Momoclo, est un groupe féminin de J-pop et pop punk japonais. Le groupe est composé d'idoles japonaises ayant commencé leur carrière en mai 2008.","Momoiro Clover Z, ou en abrégé Momoclo, est un groupe féminin de J-pop et pop punk japonais.","fr:Momoiro_Clover_Z","c:9/9b/Momoiro_Clover_Z_%2818765689144%29.jpg"],["Q19697",420,"groupe","Motörhead","C","Motörhead est un groupe britannique de heavy metal originaire de Londres en Angleterre.",null,"fr:Motörhead","c:0/0c/Motorhead-03.jpg",{"cats":["chanteurs_int","groupes"]}],["Q953918",421,"groupe","Mumford and Sons","C","Mumford and Sons est un groupe de rock et musique traditionnelle britannique, originaire de Londres, en Angleterre. Formé en 2007, le groupe est composé de Marcus Mumford, Ben Lovett, Ted Dwane et Winston Marshall jusqu'en 2021.","Mumford and Sons est un groupe de rock et musique traditionnelle britannique, originaire de Londres, en Angleterre.","fr:Mumford_and_Sons","c:2/23/Mumford_%26_Sons%2C_performing_at_Aviemore%2C_Scotland_2015.jpg"],["Q22151",422,"groupe","Muse","C","Muse est un groupe de rock britannique, originaire de Teignmouth, dans le Devon. Apparu sur la scène musicale en 1994, le trio est composé de Matthew Bellamy, Christopher Wolstenholme et Dominic Howard.","Muse est un groupe de rock britannique, originaire de Teignmouth, dans le Devon.","fr:Muse_(groupe)","c:b/be/Muse_Live_at_Alcatraz%2C_Milan_%28October_26%2C_2022%29.jpg",{"cats":["chanteurs_int","groupes"]}],["Q483285",423,"groupe","My Chemical Romance","PC","My Chemical Romance ou MCR est un groupe de rock alternatif américain, originaire du New Jersey. Actif depuis 2001, il est composé du chanteur Gerard Way, des guitaristes Ray Toro et Frank Iero, et du bassiste Mikey Way.","My Chemical Romance ou MCR est un groupe de rock alternatif américain, originaire du New Jersey.","fr:My_Chemical_Romance","c:b/b1/My_Chemical_Romance_at_Paris%2C_2011.jpg",{"cats":["chanteurs_int","groupes"]}],["Q56884561",424,"groupe","Måneskin","C","Måneskin est un groupe de rock italien, formé à Rome en 2016.",null,"fr:Måneskin","c:3/3b/Maneskin_2018.jpg",{"cats":["chanteurs_int","groupes"]}],["Q216856",425,"groupe","N.W.A","C","NWA, acronyme pour Niggaz Wit Attitudes, stylisé N.W.A, est un groupe de hip-hop américain originaire de Compton, une ville de la banlieue sud de Los Angeles. Il fait partie des promoteurs les plus précoces et des figures les plus controversées du sous-genre gangsta rap. Le groupe est largement considéré comme l'un des plus importants et influents de l'histoire du hip-hop, et plus particulièrement du rap.",117,"fr:N.W.A","c:7/7b/NWA-Logo.png"],["Q214990",426,"groupe","New Order","C","New Order est un groupe de musique électronique et de rock britannique, originaire de Manchester, en Angleterre. Formé en 1980, en pleine vague new wave, il se compose au départ des membres restant du groupe Joy Division dont le chanteur Ian Curtis vient de se suicider. À la suite de ce drame, ils optent pour un changement de nom et adoptent celui de New Order sur une suggestion de leur manager, Rob Gretton. Ce nom, comme celui de Joy Division, a fait l'objet de polémiques car il pouvait faire allusion au nazisme.","New Order est un groupe de musique électronique et de rock britannique, originaire de Manchester, en Angleterre.","fr:New_Order","c:7/79/EXIT_2012_New_Order.jpg"],["Q483802",427,"groupe","Nickelback","C","Nickelback est un groupe de rock et de metal alternatif canadien à influence grunge originaire de l'Alberta. Le groupe est actuellement composé de Chad Kroeger au chant et à la guitare solo, de Ryan Peake à la guitare rythmique, de Mike Kroeger à la guitare basse et de Daniel Adair à la batterie et aux percussions, c'est le quatrième batteur après Ryan Vikedal, Mitch Guindon et Brandon Kroeger.","Nickelback est un groupe de rock et de metal alternatif canadien à influence grunge originaire de l'Alberta.","fr:Nickelback","c:a/ae/Nickelbackwembleyarena.jpg",{"cats":["chanteurs_int","groupes"]}],["Q43510",428,"groupe","Nightwish","PC","Nightwish est un groupe de metal symphonique finlandais originaire de Kitee, dans la région de la Carélie du Nord. Formé en 1996, il est considéré comme l'un des représentants du genre et comme l'un des groupes responsables du gain de popularité que connaît le metal symphonique à la fin des années 1990. Bien que le groupe soit devenu célèbre dans son pays natal dès la sortie de son premier single, The Carpenter, sa renommée internationale ne débute qu'avec la sortie des albums Oceanborn et Wishmaster.","Nightwish est un groupe de metal symphonique finlandais originaire de Kitee, dans la région de la Carélie du Nord.","fr:Nightwish","c:4/4f/Nightwish_Toronto_concert_2022.jpg",{"cats":["chanteurs_int","groupes"]}],["Q11647",429,"groupe","Nine Inch Nails","C","Nine Inch Nails, NIN ou parfois stylisé NIИ, est un groupe de metal industriel américain, originaire de Cleveland, dans l'Ohio. Il est formé en 1988 par Trent Reznor, le principal producteur, chanteur, compositeur et instrumentiste, qui représente l'unique membre officiel de Nine Inch Nails et reste le seul responsable de sa direction, jusqu'à l'arrivée du musicien anglais Atticus Ross dans le groupe en 2016.",119,"fr:Nine_Inch_Nails","c:5/5b/Nine_inch_nails_-_Staples_Center_-_11-8-13_%2810755555065_16053de956_o%29.jpg"],["Q11649",430,"groupe","Nirvana","PC","Nirvana est un groupe de grunge américain, originaire d'Aberdeen, dans l'État de Washington, formé en 1987 par le chanteur-guitariste Kurt Cobain et le bassiste Krist Novoselic. Après Bleach en 1989, leur premier album studio produit par le label indépendant Sub Pop et une succession de batteurs, la formation se stabilise avec l'arrivée de Dave Grohl en octobre 1990.",113,"fr:Nirvana_(groupe)","c:1/19/Nirvana_around_1992.jpg",{"cats":["chanteurs_int","groupes"]}],["Q154454",431,"groupe","NSYNC","C","*NSYNC est un boys band américain de pop formé en 1995 à Orlando, en Floride dont l'activité a cessé en 2002 et s'est reformé en 2023. Les membres du groupe sont Lance Bass, JC Chasez, Joey Fatone, Chris Kirkpatrick et Justin Timberlake. Ils sont devenus un des boys band les plus célèbres des années 1990, ayant même réussi à concurrencer les Backstreet Boys. Ils ont vendu plus de 55 millions d'albums au cours de leur carrière.",117,"fr:NSYNC","c:b/be/NSYNC.jpg"],["Q382890",432,"groupe","Oasis","R","Oasis est un groupe de rock britannique, originaire de Manchester. Formé en 1991 et initialement nommé The Rain, le groupe est au départ composé de Liam Gallagher, Paul « Bonehead » Arthurs, Paul « Guigsy » McGuigan et Tony McCarroll, rapidement rejoints par Noel Gallagher, le frère aîné de Liam. Il est considéré comme l'un des principaux représentants du genre Britpop, sous-genre du rock alternatif.","Oasis est un groupe de rock britannique, originaire de Manchester.","fr:Oasis_(groupe)","c:0/03/Oasis_Noel_and_Liam_WF.jpg"],["Q146027",433,"groupe","One Direction","PC","One Direction est un boys band de pop rock anglo-irlandais formé à Londres en 2010. Le groupe est composé de Niall Horan, Liam Payne, Harry Styles et Louis Tomlinson. Zayn Malik est un ancien membre du groupe depuis son départ en mars 2015.","One Direction est un boys band de pop rock anglo-irlandais formé à Londres en 2010.","fr:One_Direction","c:6/6a/OnedirectionWWATchile.jpg"],["Q180880",434,"groupe","Pantera","C","Pantera est un groupe de groove metal américain, originaire d'Arlington, Texas. Il est initialement fondé en 1981 par les frères Abbott, le guitariste Dimebag Darrell et le batteur Vinnie Paul et dissout en 2003. Si, au départ, le groupe présente certaines caractéristiques apparentées au glam metal, sa musique relève avant tout du heavy metal. Cependant, dès 1990, le groupe prend un tournant radical vers le groove metal, un nouveau style dérivé du thrash metal.","Pantera est un groupe de groove metal américain, originaire d'Arlington, Texas.","fr:Pantera","c:a/a4/Pantera_1987-2003_lineup.jpg",{"cats":["chanteurs_int","groupes"]}],["Q473466",435,"groupe","Paramore","C","Paramore est un groupe de rock américain, originaire de Franklin, dans le Tennessee. Formé en 2004, le groupe comprend actuellement la chanteuse Hayley Williams, le guitariste Taylor York et le batteur Zac Farro.","Paramore est un groupe de rock américain, originaire de Franklin, dans le Tennessee.","fr:Paramore","c:a/a7/Paramore_at_Royal_Albert_Hall_-_19th_June_2017_-_34.jpg",{"cats":["chanteurs_int","groupes"]}],["Q142701",436,"groupe","Pearl Jam","C","Pearl Jam est un groupe de rock américain, originaire de Seattle, ville de l'État de Washington. Formé en 1990 par le guitariste Stone Gossard et le bassiste Jeff Ament, Pearl Jam est l'un des groupes les plus populaires du mouvement grunge, formant ainsi aux côtés de Soundgarden, Nirvana et Alice in Chains le Big Four of Seattle. En 2005, les lecteurs du USA Today élisent Pearl Jam « meilleur groupe américain de rock ».","Pearl Jam est un groupe de rock américain, originaire de Seattle, ville de l'État de Washington.","fr:Pearl_Jam","c:a/ae/PearlJamHamilton2011-01.jpg"],["Q485625",437,"groupe","Pet Shop Boys","C","Pet Shop Boys est un duo britannique de synthpop, formé en 1981 à Chelsea. Il se compose de Neil Tennant au chant, au clavier et occasionnellement à la guitare, et de Chris Lowe au synthétiseur et occasionnellement au chant. Leur style musical évolue entre disco, new wave, house et dance-pop.","Pet Shop Boys est un duo britannique de synthpop, formé en 1981 à Chelsea.","fr:Pet_Shop_Boys","c:8/86/Pet_Shop_Boys_interview_2013_still.png"],["Q2306",438,"groupe","Pink Floyd","R","Pink Floyd est un groupe britannique de rock originaire de Londres. Le groupe débute avec un premier album de musique psychédélique pour ensuite bifurquer vers le rock progressif. Formé en 1965, il est considéré comme un pionnier et représentant majeur de ces styles musicaux. Il est reconnu pour sa musique planante et expérimentale, ses textes philosophiques et satiriques, ses albums-concept et ses performances en concert originales et élaborées.","Pink Floyd est un groupe britannique de rock originaire de Londres.","fr:Pink_Floyd","c:b/be/PinkFloyd1973_retouched.jpg",{"cats":["chanteurs_int","groupes"]}],["Q188464",439,"groupe","Pixies","C","Pixies est un groupe de rock alternatif américain, originaire de Boston, au Massachusetts. Formé en 1986, le groupe se sépare en janvier 1993 dans des conditions quelque peu houleuses, et se reforme en avril 2004. De ses débuts jusqu'en 2013, le groupe est constitué de quatre membres: Black Francis, Joey Santiago, Kim Deal et David Lovering.","Pixies est un groupe de rock alternatif américain, originaire de Boston, au Massachusetts.","fr:Pixies","c:6/65/Pixies_in_Kansas_City%2C_October_1%2C_2004.jpg"],["Q484839",440,"groupe","Placebo","C","Placebo est un groupe de rock alternatif britannique, originaire de Londres, en Angleterre. Il est formé en 1994 par Brian Molko et Stefan Olsdal, qui sont d'abord accompagnés par Robert Schultzberg jusqu'en 1996, puis Steve Hewitt jusqu'en 2007, et Steve Forrest jusqu'en 2015.","Placebo est un groupe de rock alternatif britannique, originaire de Londres, en Angleterre.","fr:Placebo_(groupe)","c:f/f7/Placebo_in_Cracow%2C_Poland%2C_2012.jpg"],["Q15862",441,"groupe","Queen","R","Queen est un groupe de rock britannique, originaire de Londres, en Angleterre. Il est formé en 1970 par Freddie Mercury, Brian May et Roger Taylor, ces deux derniers étant issus du groupe Smile. L’année suivante, le bassiste John Deacon vient compléter la formation. Les quatre membres de Queen sont tous des auteurs-compositeurs, chacun apportant une touche unique à l'identité musicale du groupe.","Queen est un groupe de rock britannique, originaire de Londres, en Angleterre.","fr:Queen","c:3/33/Queen_%E2%80%93_montagem_%E2%80%93_new.png",{"cats":["chanteurs_int","groupes"]}],["Q1243718",442,"groupe","Queens of the Stone Age","R","Queens of the Stone Age est un groupe de rock américain, originaire de Palm Desert, en Californie. Il est formé en 1996 suivant la dissolution du groupe Kyuss. Parfois classé comme stoner rock ou hard rock, Queens of the Stone Age a connu de nombreux changements de personnel au fil des années. Josh Homme est le seul membre fondateur à apparaître sur tous les albums du groupe.","Queens of the Stone Age est un groupe de rock américain, originaire de Palm Desert, en Californie.","fr:Queens_of_the_Stone_Age","c:c/c2/Queens_of_the_Stone_Age_-_SSE_Arena_Wembley_-_Saturday_18th_November_2017_QOTSAWembley181117-29_%2824730972488%29_%28cropped%29.jpg"],["Q134969",443,"groupe","R.E.M.","C","R.E.M. est un groupe de pop rock américain, originaire d'Athens, dans l'État de Géorgie. Il est formé en 1979 par Michael Stipe, Peter Buck, Mike Mills et Bill Berry. Ce fut l'un des premiers groupes à créer le courant rock alternatif, attirant très tôt l'attention grâce au jeu de guitare en arpèges de Buck et aux paroles énigmatiques de Stipe.","R.E.M.","fr:R.E.M.","c:a/a4/Padova_REM_concert_July_22_2003_blue.jpg"],["Q44190",444,"groupe","Radiohead","PC","Radiohead est un groupe de rock britannique, originaire d'Abingdon, dans l'Oxfordshire. Formé en 1985, il est composé de Thom Yorke, des frères Jonny Greenwood et Colin Greenwood, Ed O'Brien, et Phil Selway.","Radiohead est un groupe de rock britannique, originaire d'Abingdon, dans l'Oxfordshire.","fr:Radiohead","c:a/a1/RadioheadO2211125_composite.jpg"],["Q72092",445,"groupe","Rage Against the Machine","PC","Rage Against the Machine est un groupe de rock américain, originaire de Los Angeles, en Californie. Leur style musical est une fusion de metal et de rap, avec des influences funk et punk. Composé de Zack de la Rocha, Tom Morello, Tim Commerford et Brad Wilk, le groupe marque les années 1990 jusqu'à sa dissolution en 2000. Le groupe a sorti quatre albums studio. Il se reforme à partir de janvier 2007 pour le festival de Coachella, mais ne publie plus de nouvel album.","Rage Against the Machine est un groupe de rock américain, originaire de Los Angeles, en Californie.","fr:Rage_Against_the_Machine","c:f/f9/Rage_Against_The_Machine.jpg",{"cats":["chanteurs_int","groupes"]}],["Q25177",446,"groupe","Rammstein","PC","Rammstein est un groupe de metal industriel allemand créé en 1994, originaire de Berlin.",null,"fr:Rammstein","c:3/38/Rammstein_aux_Ar%C3%A8nes_de_N%C3%AEmes_le_13_juillet_2017.jpg",{"cats":["chanteurs_int","groupes"]}],["Q483407",447,"groupe","Ramones","C","Ramones est un groupe américain de punk rock, originaire de New York. Formé en 1974, il est souvent cité comme le premier groupe de punk rock. Bien qu'ayant eu un succès commercial assez limité, le groupe a une grande influence sur le punk et ses dérivés.","Ramones est un groupe américain de punk rock, originaire de New York.","fr:Ramones","c:3/3a/Ramones_Toronto_1976.jpg"],["Q10708",448,"groupe","Red Hot Chili Peppers","PC","Les Red Hot Chili Peppers sont un groupe de funk rock américain, originaire de Los Angeles, en Californie, actif depuis 1982. La formation actuelle s'articule autour des membres fondateurs et amis d'enfance Anthony Kiedis et Flea, auxquels se joignent en 1988 Chad Smith et John Frusciante qui, après avoir quitté le groupe à deux reprises, le rejoint une troisième fois en 2019.",119,"fr:Red_Hot_Chili_Peppers","c:f/fc/RHChiliPeppersSpurs210723_%2838_of_90%29_%2853064693542%29.jpg",{"cats":["chanteurs_int","groupes"]}],["Q203871",449,"groupe","Rush","PC","Rush est un groupe canadien de hard rock, originaire de Toronto, en Ontario. Ses membres emblématiques sont le bassiste, claviériste et chanteur Geddy Lee, le guitariste Alex Lifeson, et le batteur et parolier Neil Peart. Créé en 1968, sa composition subit diverses modifications avant de se stabiliser en juillet 1974, à l'arrivée de Neil Peart, remplaçant le batteur originel John Rutsey, deux semaines avant la première tournée du groupe aux États-Unis.","Rush est un groupe canadien de hard rock, originaire de Toronto, en Ontario.","fr:Rush_(groupe)","c:4/46/Rush-in-concert.jpg"],["Q124147",450,"groupe","Scorpions","C","Scorpions est un groupe allemand de hard rock, originaire de Hanovre. Son premier album voit le jour en 1972. Le groupe connaît un prestige planétaire surtout à partir des années 1980 grâce à des titres de hard rock tels que Rock You Like a Hurricane et Big City Nights en 1984 ou No One Like You en 1982 et des ballades à l'instar de Still Loving You ou Wind of Change et Send Me an Angel, des chansons à grand succès commercial.","Scorpions est un groupe allemand de hard rock, originaire de Hanovre.","fr:Scorpions","c:c/cd/Scorpions_au_Th%C3%A9%C3%A2tre_Antique_de_Vienne_le_18_juin_2024.jpg",{"cats":["chanteurs_int","groupes"]}],["Q82545",451,"groupe","Sex Pistols","PC","Sex Pistols est un groupe de punk rock britannique, originaire de Londres, au Royaume-Uni. Il est formé en 1975 et connu pour être parmi les plus célèbres du mouvement punk. À sa formation, le quatuor se compose de Johnny Rotten au chant, Steve Jones à la guitare, Paul Cook à la batterie et Glen Matlock à la basse. Ce dernier est remplacé par Sid Vicious en 1977.","Sex Pistols est un groupe de punk rock britannique, originaire de Londres, au Royaume-Uni.","fr:Sex_Pistols","c:1/1e/Sex_Pistols_in_Paradiso.jpg"],["Q484918",452,"groupe","Simon and Garfunkel","C","Simon and Garfunkel est un duo de folk rock américain formé à Forest Hills, dans le Queens à New York, composé de Paul Simon et Art Garfunkel.",118,"fr:Simon_and_Garfunkel","c:f/f9/Simon_and_Garfunkel_1968.jpg"],["Q323834",453,"groupe","Siouxsie and the Banshees","C","Siouxsie and the Banshees est un groupe rock britannique, originaire de Londres, en Angleterre, formé en 1976 par la chanteuse Siouxsie Sioux et le bassiste Steven Severin. Avec le guitariste John McKay et le batteur Kenny Morris, Siouxsie and the Banshees créent « une forme de dissonance post-punk remplie d'expérimentation rythmique et sonore », dès la sortie de leur premier album The Scream.",116,"fr:Siouxsie_and_the_Banshees","c:b/bf/Siouxsie_and_the_Banshees-3.jpg"],["Q254138",454,"groupe","Slipknot","PC","Slipknot est un groupe de metal américain, originaire de Des Moines, dans l'Iowa.",null,"fr:Slipknot","c:7/7c/Slipknot_%40_Claremont_Showgrounds.jpg",{"cats":["chanteurs_int","groupes"]}],["Q174817",455,"groupe","Soundgarden","C","Soundgarden est un groupe de rock alternatif américain originaire de Seattle, dans l'État de Washington. Il est formé en 1984 par le chanteur guitariste et batteur Chris Cornell, le guitariste Kim Thayil et le bassiste Hiro Yamamoto. Cornell passe à la guitare rythmique en 1985, remplacé à la batterie par Scott Sundquist, puis par Matt Cameron en 1986. Yamamoto quitte le groupe en 1990 et est remplacé par Jason Everman et peu de temps après par Ben Shepherd. Le groupe se sépare en 1997 et se reforme en 2010.","Soundgarden est un groupe de rock alternatif américain originaire de Seattle, dans l'État de Washington.","fr:Soundgarden","c:8/81/Soundgarden_at_Paramount_Theatre.jpg"],["Q55641",456,"groupe","Spice Girls","PC","Spice Girls est un groupe de pop anglais formé en 1994 à Londres. Ce girl band est composé à l'origine de cinq chanteuses et danseuses: Victoria Beckham, Melanie Chisholm, Melanie Brown, Geri Halliwell et Emma Bunton.","Spice Girls est un groupe de pop anglais formé en 1994 à Londres.","fr:Spice_Girls","c:a/ac/Spice_Girls_in_Toronto%2C_Ontario.jpg"],["Q193697",457,"groupe","Sugababes","C","Sugababes est un groupe britannique composé de trois chanteuses originaires de Londres. Au départ formé par Keisha Buchanan, Mutya Buena et Siobhán Donaghy, le groupe se composera également de Heidi Range, Amelle Berrabah et Jade Ewen, chacune d'entre elles remplaçant un membre de la formation initiale entre 2001 et 2009. Le groupe retrouvera finalement sa formation d’origine en 2013.","Sugababes est un groupe britannique composé de trois chanteuses originaires de Londres.","fr:Sugababes","c:c/c5/Mutya_Keisha_Siobhan.jpg"],["Q45165",458,"groupe","System of a Down","PC","System of a Down est un groupe de rock arméno-américain, originaire de Californie. Formé en 1994, le groupe est actuellement composé de quatre membres, ayant tous des origines arméniennes: Daron Malakian, Serj Tankian, Shavo Odadjian et John Dolmayan. Issu de la scène underground californienne, le groupe rencontre son premier succès majeur avec la sortie de son premier album homonyme en 1998.","System of a Down est un groupe de rock arméno-américain, originaire de Californie.","fr:System_of_a_Down","c:b/b5/SOADJONESBEACH.jpg",{"cats":["chanteurs_int","groupes"]}],["Q161723",459,"groupe","T.A.T.u.","C","t.A.T.u. est un duo pop russe composé de Julia Volkova et de Lena Katina. Les deux chanteuses ont débuté leur carrière en 1991 comme membres du groupe d'enfants Neposedy avant la formation du groupe en 1999 sous la direction du producteur et réalisateur Ivan Chapovalov. En douze ans d'activité, t.A.T.u. est devenu le groupe pop russe le plus acclamé de tous les temps. Durant leurs performances, Volkova et Katina se font souvent remarquer en s'embrassant sur la bouche de manière provocante, habillées en lolitas.","t.A.T.u.","fr:T.A.T.u.","c:b/b1/Tatu_2026.jpg"],["Q205001",460,"groupe","Talking Heads","C","Talking Heads est un groupe américain de rock, originaire du New York. Le nom « talking head » désigne en anglais un spécialiste intervenant à la télévision. Issu de la scène punk de New York et associé plus tard aux mouvements post-punk et new wave, le groupe existe entre 1974 et 1991 et a notamment joué au CBGB aux côtés de groupes tels que les Ramones, Television ou Patti Smith.","Talking Heads est un groupe américain de rock, originaire du New York.","fr:Talking_Heads","c:c/c7/Talking_Heads_band3.jpg"],["Q269091",461,"groupe","Tears for Fears","C","Tears for Fears, parfois abrégé en TFF et plus rarement en T4F, est un groupe pop rock britannique, originaire de Bath, en Angleterre. Formé par Roland Orzabal et Curt Smith en 1981, le groupe, initialement affilié au mouvement new wave, a vendu plus de trente millions d'albums à travers le monde. Ses trois albums studio parus dans les années 1980 cumulent à eux seuls plus de vingt millions d'exemplaires vendus.",119,"fr:Tears_for_Fears","c:6/68/Tears_for_Fears_2008.jpg"],["Q131422",462,"groupe","The Animals","C","The Animals est un groupe britannique de rock des années 1960. Au même titre que les Rolling Stones, cette formation a été l'une des pionnières du British Blues Boom et a contribué à importer en Europe le rhythm and blues noir américain.","The Animals est un groupe britannique de rock des années 1960.","fr:The_Animals","c:0/02/Eric_Burdon_%26_the_Animals.jpg"],["Q214418",463,"groupe","The Bangles","C","The Bangles est un groupe féminin américain de rock, originaire de Los Angeles, en Californie. Il est populaire dans les années 1980, période durant laquelle il sort trois albums studio, et notamment à travers les chansons Manic Monday, Walk Like an Egyptian et Eternal Flame. Après une séparation en 1989, le groupe se reforme en 1999, et sort deux nouveaux albums.","The Bangles est un groupe féminin américain de rock, originaire de Los Angeles, en Californie.","fr:The_Bangles","c:f/f0/Bangles_at_Festival_of_Friends_2012.jpg"],["Q183048",464,"groupe","The Beach Boys","PC","The Beach Boys est un groupe de pop-rock américain, originaire de Hawthorne, en Californie. Formé en 1961 par trois frères, leur cousin et un ami, il connait une très grande popularité dans les années 1960 et 1970. C'est l'un des rares groupes américains à avoir pu rivaliser musicalement avec les groupes britanniques de la même époque, tels que les Beatles et les Rolling Stones.","The Beach Boys est un groupe de pop-rock américain, originaire de Hawthorne, en Californie.","fr:The_Beach_Boys","c:e/eb/The_Beach_Boys%2C_May_29%2C_2012.jpg"],["Q1299",465,"groupe","The Beatles","L","The Beatles, prononcé en français, est un groupe de pop et de rock britannique des années 1960, originaire de Liverpool, en Angleterre. Il est considéré comme le groupe le plus célèbre et influent dans l'histoire de la musique populaire occidentale.",109,"fr:The_Beatles","c:d/d8/The_Beatles_members_at_New_York_City_in_1964.jpg"],["Q125603",466,"groupe","The Clash","C","The Clash est un groupe britannique de punk rock, originaire de Londres, en Angleterre, actif entre 1976 et 1986. Il s'agit d'un des quatuors majeurs de l'histoire du rock et du punk rock britannique. Le groupe commence sa carrière en 1976 et se dissout en 1986. En 2003, la formation entre au Rock and Roll Hall of Fame.","The Clash est un groupe britannique de punk rock, originaire de Londres, en Angleterre, actif entre 1976 et 1986.","fr:The_Clash","c:6/6f/The_Clash_in_San_Diego%2C_1982_%28cropped%29.jpg"],["Q483810",467,"groupe","The Cranberries","PC","The Cranberries est un groupe de rock originaire de Limerick en Irlande, formé en 1989. Le groupe est initialement formé sous le nom de The Cranberry Saw Us par le guitariste Noel Hogan, le bassiste Mike Hogan, le chanteur Niall Quinn et le batteur Fergal Lawler. Quinn est remplacé par Dolores O'Riordan en 1990 et le groupe se renomme en The Cranberries.","The Cranberries est un groupe de rock originaire de Limerick en Irlande, formé en 1989.","fr:The_Cranberries","c:4/49/The-Cramberries-Paris-31-mai-2010_IMG_7726.JPG"],["Q484427",468,"groupe","The Cure","PC","The Cure () est un groupe rock britannique, originaire de Crawley, dans le Sussex de l'Ouest, en Angleterre. Formé en 1978, le groupe comprend actuellement Robert Smith au chant et à la guitare, Roger O'Donnell aux claviers, Reeves Gabrels à la guitare, Simon Gallup à la basse, et Jason Cooper à la batterie. Robert Smith est la figure emblématique du groupe. Seul membre présent depuis son origine, il en est le parolier et le principal compositeur.","The Cure () est un groupe rock britannique, originaire de Crawley, dans le Sussex de l'Ouest, en Angleterre.","fr:The_Cure","c:2/21/The_Cure_Live_in_Singapore_2-_1st_August_2007.jpg"],["Q45354",469,"groupe","The Doors","C","The Doors est un groupe américain de rock, originaire de Los Angeles, en Californie. Il est formé en juillet 1965 et dissous en 1973, deux ans après la mort du chanteur Jim Morrison en 1971.","The Doors est un groupe américain de rock, originaire de Los Angeles, en Californie.","fr:The_Doors","c:6/60/Doors_electra_publicity_photo.JPG"],["Q43267",470,"groupe","The Jackson Five","C","The Jackson Five, également appelé J5, Jackson Five ou The Jacksons, est un groupe américain de soul, originaire de Gary, dans l'Indiana, et composé au départ de cinq membres d'une même fratrie: Jackie, Toriano dit « Tito », Jermaine, Marlon, et Michael.",115,"fr:The_Jackson_Five","c:f/f4/The_Jacksons_1976_2.jpg"],["Q220730",471,"groupe","The Killers","C","The Killers est un groupe américain de rock alternatif, originaire de Las Vegas dans le Nevada. Formé en 2001, il se compose de Brandon Flowers, David Brent « Dave » Keuning, Mark Stoermer et Ronald « Ronnie » Vannucci Jr.","The Killers est un groupe américain de rock alternatif, originaire de Las Vegas dans le Nevada.","fr:The_Killers","c:f/f8/The_Killers_in_concert.jpg"],["Q188713",472,"groupe","The Kinks","PC","The Kinks est un groupe britannique de rock, originaire de Londres, en Angleterre. Il est formé en 1963 par les frères Ray et Dave Davies, et actif jusqu'en 1996. Il est l'un des groupes majeurs de la British Invasion et reste considéré comme l'un des groupes les plus importants et influents des années 1960.","The Kinks est un groupe britannique de rock, originaire de Londres, en Angleterre.","fr:The_Kinks","c:8/88/Helmfrid-sofa4_Touched.JPG"],["Q211277",473,"groupe","The Mamas and the Papas","C","The Mamas and the Papas est un groupe américain de pop, folk et rock, originaire de New York, et basé à Los Angeles, en Californie. Le groupe se compose de John Phillips, Cass Elliot, Denny Doherty et Michelle Phillips. Ils seront actifs entre 1965 et 1968, et se reforment brièvement en 1971.",119,"fr:The_Mamas_and_the_Papas","c:8/8e/The_Mamas_and_the_Papas_Ed_Sullivan_Show_1968.JPG"],["Q464036",474,"groupe","The Monkees","C","The Monkees est un groupe américain pop rock, formé en 1965 et dissous en 1970.",null,"fr:The_Monkees","c:8/8f/The_Monkees_May_1967.jpg"],["Q157041",475,"groupe","The Offspring","C","The Offspring, ou simplement Offspring, est un groupe de punk rock américain, originaire du Comté d'Orange, en Californie. Constitué en 1984, le groupe est actuellement formé de Bryan \"Dexter\" Holland au chant et à la guitare rythmique, Todd Morse à la basse, Kevin \"Noodles\" Wasserman à la guitare solo, Jonah Nimoy aux claviers, percussions et guitare additionnelle et Brandon Pertzborn à la batterie",110,"fr:The_Offspring","c:f/f9/Eurocks2026_TheOffspring_NF5_5571_NathanFabry.jpg",{"cats":["chanteurs_int","groupes"]}],["Q178095",476,"groupe","The Police","C","The Police est un groupe rock britannique, originaire de Londres, en Angleterre. Il est issu de la génération new wave et post-punk, et formé par les Britanniques Sting au chant et à la basse, Andy Summers à la guitare électrique et l'Américain Stewart Copeland à la batterie. Summers a rapidement remplacé en 1977 le Français Henry Padovani. Le groupe est très populaire vers la fin des années 1970 et au début des années 1980 grâce à leur musique rock, mélangeant jazz, punk et reggae.","The Police est un groupe rock britannique, originaire de Londres, en Angleterre.","fr:The_Police","c:a/a2/ThePolice_2007.jpg"],["Q7256860",477,"groupe","The Prodigy","PC","The Prodigy est un groupe de musique électronique issu de la scène rave britannique, originaire de Braintree, Essex, en Angleterre. Aux côtés notamment de The Chemical Brothers, Fatboy Slim et The Crystal Method, ils font partie des pionniers de la dance électronique qualifiée plus tard de « big beat » par la presse. Ce style atteint sa popularité dans les années 1990 avec le développement des raves parties et de leur médiatisation dès lors qu'elles sont rendues illégales.",119,"fr:The_Prodigy","c:8/84/The_Prodigy_live_in_Romania.JPG",{"cats":["chanteurs_int","electro"]}],["Q102385",478,"groupe","The Pussycat Dolls","C","Les Pussycat Dolls est un girl group américain de pop et RnB, originaire de Los Angeles, en Californie.",null,"fr:The_Pussycat_Dolls","c:3/3b/PCD_-_DDWT.jpg"],["Q11036",479,"groupe","The Rolling Stones","R","The Rolling Stones est un groupe rock britannique originaire de Londres, en Angleterre. En activité depuis 1962, il est l'un des plus vieux groupes de rock encore en activité à ce jour.","The Rolling Stones est un groupe rock britannique originaire de Londres, en Angleterre.","fr:The_Rolling_Stones","c:5/5e/Rolling_Stones_onstage_at_Summerfest_2015.jpg"],["Q184217",480,"groupe","The Smashing Pumpkins","R","The Smashing Pumpkins est un groupe de rock alternatif américain, originaire de Chicago, dans l'Illinois. Il est formé en 1987 par le chanteur et guitariste Billy Corgan, seul membre à avoir participé à tous les albums du groupe. Il est historiquement composé de Billy Corgan, James Iha, Jimmy Chamberlin et D'arcy Wretzky. James Iha et D'arcy Wretzky sont remplacés par Jeff Schroeder et Ginger Reyes pour les prestations live de l'année 2000 ainsi que pour l'album Zeitgeist en 2007.","The Smashing Pumpkins est un groupe de rock alternatif américain, originaire de Chicago, dans l'Illinois.","fr:The_Smashing_Pumpkins","c:5/54/SP2012STLChaifetz.jpg"],["Q180598",481,"groupe","The Smiths","C","The Smiths est un groupe de rock anglais créé à Manchester en 1982 par Morrissey, chanteur et parolier, et Johnny Marr en tant que compositeur et guitariste. Le duo fut ensuite rejoint par Mike Joyce à la batterie et Andy Rourke, mort le 19 mai 2023, à la basse. Le groupe se sépare en 1987.",118,"fr:The_Smiths","c:6/68/The_Smiths_%281984_Sire_publicity_photo%29_002.jpg"],["Q211583",482,"groupe","The Strokes","PC","The Strokes est un groupe de rock américain, originaire de New York.",null,"fr:The_Strokes","c:6/65/The_Strokes_by_Roger_Woolman.jpg"],["Q103550",483,"groupe","The Velvet Underground","C","The Velvet Underground est un groupe de rock américain, originaire de New York. Formé au milieu des années 1960, il est lié à l'aventure de la Factory d'Andy Warhol qui l'a produit. D'abord connu des seuls milieux « underground » new-yorkais, son influence n'a cessé de croître après sa dissolution. Il a beaucoup influencé David Bowie, qui, à ses débuts, a été parmi les premiers à interpréter un de leurs titres dans des clubs.","The Velvet Underground est un groupe de rock américain, originaire de New York.","fr:The_Velvet_Underground","c:d/d8/Velvet_Underground_%26_Nico_publicity_photo_%28retouched%29.jpg"],["Q93346",484,"groupe","The Who","C","The Who est un groupe britannique de rock, originaire de Londres, en Angleterre.",null,"fr:The_Who","c:9/92/Who_-_1975.jpg"],["Q192725",485,"groupe","The Yardbirds","C","The Yardbirds est un groupe britannique de blues rock, originaire de Londres, en Angleterre. Issu des années 1960, il est formé en mai 1963. Anthony « Top » Topham, Eric Clapton, Jeff Beck puis Jimmy Page se succèdent à la guitare au sein du groupe; en 1966, Beck et Page y jouent simultanément.","The Yardbirds est un groupe britannique de blues rock, originaire de Londres, en Angleterre.","fr:The_Yardbirds","c:8/8c/Yardbirds2006.jpg"],["Q202314",486,"groupe","Thin Lizzy","C","Thin Lizzy est un groupe irlandais de hard rock formé à Dublin en 1969. À l'origine un trio composé d'Eric Bell, Phil Lynott et Brian Downey, le groupe connaît un premier succès en 1973 avec Whiskey in the Jar, une adaptation d'un air traditionnel irlandais. Après le départ de Eric Bell, remplacé par les guitaristes Brian Robertson et Scott Gorham, Thin Lizzy atteint le sommet de sa popularité en faisant évoluer sa musique vers le hard rock.","Thin Lizzy est un groupe irlandais de hard rock formé à Dublin en 1969.","fr:Thin_Lizzy","c:9/95/Thin_Lizzy_-1983.jpg"],["Q386216",487,"groupe","Tokio Hotel","C","Tokio Hotel est un groupe de pop rock allemand originaire de Magdebourg. Formé en 2001, et constitué de quatre jeunes Allemands, dont les frères jumeaux Tom et Bill Kaulitz, le groupe compte au total huit albums: Devilish, Schrei, Zimmer 483 / Scream, Humanoid, Kings of Suburbia, Dream Machine, 2001 et Encore.","Tokio Hotel est un groupe de pop rock allemand originaire de Magdebourg.","fr:Tokio_Hotel","c:e/e9/Tokio1899.jpg",{"cats":["chanteurs_int","groupes"]}],["Q184827",488,"groupe","Tool","C","Tool est un groupe de metal progressif américain, originaire de Los Angeles, en Californie formé en 1990 par le chanteur Maynard James Keenan, le guitariste Adam Jones, le batteur Danny Carey et le bassiste Paul D'Amour. Ce dernier quitte le groupe en 1995 pour être remplacé par Justin Chancellor du groupe britannique Peach peu de temps avant l'enregistrement de leur deuxième album, Ænima.",111,"fr:Tool","c:c/ce/Hellfest2019Tool_02.jpg"],["Q207472",489,"groupe","Toto","C","Toto est un groupe américain de rock, originaire de Los Angeles, en Californie. Il est formé en 1976 par Jeff Porcaro et David Paich, auxquels se joignent Steve Lukather, Steve Porcaro, David Hungate et Bobby Kimball. Après des débuts prometteurs, le groupe atteint la consécration dans les années 1980 avec son album Toto IV. En 1982, Mike Porcaro remplace David Hungate à la basse.","Toto est un groupe américain de rock, originaire de Los Angeles, en Californie.","fr:Toto_(groupe)","c:9/9e/TOTO_live_2010_in_Copenhagen_in_KB_Hallen.JPG"],["Q7857806",490,"groupe","Twenty One Pilots","PC","Twenty One Pilots est un groupe de musique alternative américain, originaire de Columbus dans l'Ohio. Il est, à ses débuts en 2009, composé de Tyler Joseph, Nick Thomas et Chris Salih. Ces deux derniers quittent le groupe en 2011 et Salih est remplacé sitôt après par Josh Dun. C'est en duo que le groupe accède à la notoriété, dès 2012. En 2017, ils gagnent un Grammy Awards pour leur performance sur leur titre Stressed Out.","Twenty One Pilots est un groupe de musique alternative américain, originaire de Columbus dans l'Ohio.","fr:Twenty_One_Pilots","c:a/aa/Twenty_One_Pilots_from_Clancy_Tour_in_Dublin_%28landscape_crop%29.jpg",{"cats":["chanteurs_int","groupes"]}],["Q396",491,"groupe","U2","PC","U2 est un groupe de rock irlandais originaire de Dublin, formé en 1976.",null,"fr:U2","c:a/ac/U2_on_Joshua_Tree_Tour_2017_Brussels_8-1-17.jpg"],["Q190155",492,"groupe","Van Halen","C","Van Halen est un groupe américain de hard rock, originaire de Pasadena, en Californie. Le guitariste du groupe, Eddie Van Halen, d'origine néerlandaise, est rapidement devenu célèbre pour ses prouesses techniques et sa sensibilité musicale. Il a surtout inspiré un nouveau courant de guitar heroes grâce à la popularisation de la technique du tapping. Son premier chanteur, David Lee Roth, s'est également imposé comme un véritable showman.","Van Halen est un groupe américain de hard rock, originaire de Pasadena, en Californie.","fr:Van_Halen","c:b/ba/VAN_HALEN_2008.jpg"],["Q192861",493,"groupe","Venom","PC","Venom, est un groupe britannique de heavy metal, originaire de Newcastle upon Tyne, en Angleterre. Formé en 1979, Venom est considéré comme le groupe précurseur du heavy metal dit « extrême », et à ce titre est considéré comme le plus important des groupes initiateurs du black metal, avec son album du même nom. Le groupe est dissous en 2026 peu après la mort de Conrad « Cronos » Lant, son dernier membre fondateur.","Venom, est un groupe britannique de heavy metal, originaire de Newcastle upon Tyne, en Angleterre.","fr:Venom_(groupe)","c:5/58/Venom_%28Brutal_Assault_2014%29.jpg"],["Q209956",494,"groupe","Weezer","C","Weezer est un groupe de rock américain, originaire de Los Angeles, en Californie. Le groupe est actuellement composé de trois de ses membres fondateurs: le chanteur et guitariste Rivers Cuomo, le batteur, guitariste et choriste Patrick Wilson et le claviériste, guitariste et choriste Brian Bell. Ses titres les plus connus sont Undone – The Sweater Song, Buddy Holly, Hash Pipe, Island in the Sun, Beverly Hills, Pork and Beans et Perfect Situation. Son style est situé entre le rock alternatif et la power pop.","Weezer est un groupe de rock américain, originaire de Los Angeles, en Californie.","fr:Weezer","c:b/b7/Weezer_Performing_in_2015_-_Photo_by_Peter_Dzubay.jpg"],["Q151241",495,"groupe","Westlife","C","Westlife est un groupe vocal pop irlandais, formé depuis 1998 à Sligo, en Irlande. Ils se sont dissous en 2012 et se sont réunis en 2018. Ils ont été signés à l’origine par Simon Cowell, créateur notamment de X-Factor au Royaume-Uni. Le groupe est composé de Shane Filan, Mark Feehily, Kian Egan, Nicky Byrne et de Brian McFadden qui a quitté le groupe en 2004.","Westlife est un groupe vocal pop irlandais, formé depuis 1998 à Sligo, en Irlande.","fr:Westlife","c:b/b4/West_life.jpg"],["Q52463",496,"groupe","Wu-Tang Clan","PC","Wu-Tang Clan est un groupe de hip-hop américain formé en 1992, originaire de New York. Les dix membres qui le composent sont originaires des quartiers new-yorkais de Staten Island et de Brooklyn. Wu-Tang Clan se présente et se lance sous plusieurs groupes et artistes affiliés, connus sous le nom collectif de Wu-Tang Killa Bees.","Wu-Tang Clan est un groupe de hip-hop américain formé en 1992, originaire de New York.","fr:Wu-Tang_Clan","c:1/1b/WuTangClanLogo.png"],["Q184386",497,"groupe","Yes","C","Yes est un groupe britannique de rock, originaire de Londres, au Royaume-Uni. Formé en 1968, il est considéré comme un des pionniers du genre progressif. Au cours de son histoire longue de plus d'un demi-siècle, le groupe a compté dans ses différentes formations dix-huit membres dont la moitié y a fait plusieurs passages.","Yes est un groupe britannique de rock, originaire de Londres, au Royaume-Uni.","fr:Yes","c:4/46/Yes_-_18.06.2022_-_Royal_Concert_Hall%2C_Nottingham.jpg"],["Q95688943",498,"groupe","Yoasobi","C","Yoasobi, stylisé YOASOBI, est un superduo de musique japonaise, originaire de Tokyo. Il est formé par Sony Music Entertainment Japan, composé du producteur de vocaloid Ayase et de l'auteure-compositrice-interprète Ikura (de son vrai nom Lilas Ikuta).","Yoasobi, stylisé YOASOBI, est un superduo de musique japonaise, originaire de Tokyo.","fr:Yoasobi","c:a/ab/Yoasobi.jpg"],["Q136591",499,"groupe","ZZ Top","C","ZZ Top est un groupe américain de blues rock originaire de Houston. Il connaît le sommet de sa célébrité dans les années 1970 et 1980. Le groupe a vendu plus de 70 millions d'albums à travers le monde, dont la moitié aux États-Unis.","ZZ Top est un groupe américain de blues rock originaire de Houston.","fr:ZZ_Top","c:4/4f/ZZ_Top_2015.jpg"],["Q62140662",500,"chanteur","Girl in Red","C","Marie Ulven Ringheim, mieux connue sous le nom de scène Girl in Red, est une auteure-compositrice-interprète, musicienne et productrice norvégienne. Elle est connue pour « ses hymnes de pop de chambre parlant d'amour et de santé mentale ». Son single I Wanna Be Your Girlfriend est streamé plus de 150 millions de fois en ligne, et se classe no 9 sur la liste du New York Times des 68 meilleures chansons de 2018.",109,"fr:Girl_in_Red","c:3/37/Girl_in_Red_EOTR1.jpg"],["Q23761694",501,"chanteur","Mitski","C","Mitski, de son nom complet Mitski Miyawaki (ミツキ・ミヤワキ, née Mitsuki Laycock, le 27 septembre 1990 au Japon), est une auteure-compositrice-interprète américaine de rock indépendant et de rock alternatif. Sa carrière musicale a débuté pendant ses études au conservatoire de musique au Purchase College, période durant laquelle Mitski auto-produit ses deux premiers albums : Lush (2012) et Retired from Sad, New Career in Business (en) (2013).",114,"fr:Mitski","c:2/29/Mitksi_%2846927277872%29_%28cropped%29.jpg"],["Q18534249",502,"chanteur","Halsey","PC","Ashley Nicolette Frangipane, plus connue sous le nom de scène Halsey, est une auteure-compositrice-interprète, poète, entrepreneuse et actrice américaine.",110,"fr:Halsey_%28chanteuse%29","https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c4/Halsey_at_the_2026_Cannes_Film_Festival.jpg/3840px-Halsey_at_the_2026_Cannes_Film_Festival.jpg"],["Q15948790",503,"chanteur","Tove Lo","C","Tove Lo, de son vrai nom Tove Ebba Elsa Nilsson, née le 29 octobre 1987 à Helsingborg, est une auteure-compositrice-interprète suédoise.",94,"fr:Tove_Lo","c:2/26/Tove_Lo_%282%29_By_Daniel_%C3%85hs_Karlsson.jpeg"],["Q288525",504,"chanteur","Birdy","C","Jasmine van den Bogaerde, connue sous son nom de scène Birdy, est une auteure-compositrice-interprète, pianiste et guitariste britannique, née le 15 mai 1996 à Lymington (Angleterre).",114,"fr:Birdy_%28chanteuse%29","c:1/13/Birdy-2450.jpg"],["Q4027095",505,"chanteur","Tom Odell","C","Thomas Odell, dit Tom Odell, né le 24 novembre 1990 à Chichester est un auteur-compositeur-interprète et pianiste britannique. Il sort son premier EP, Songs from Another Love, en 2012. Il remporte le prix BRITs Critics' Choice Award début 2013. Le premier album studio de Tom, Long Way Down, sort le 24 juin 2013. Trois ans plus tard, son album studio suivant, Wrong Crowd, est publié. Il est suivi par plusieurs autres albums.",113,"fr:Tom_Odell","c:c/cc/Tom_Odell_-_Southside_Festival_2024_-_1DX_8854.jpg"],["Q15459513",506,"chanteur","George Ezra","C","George Ezra, né le 7 juin 1993 à Hertford, est un auteur-compositeur-interprète de pop-folk et guitariste britannique. Il est mis sur le devant de la scène par la BBC qui l'intègre à la soirée d'introduction du festival du Glastonbury Festival 2013 et le classe dans le top BBC Sound of 2014. Son premier EP Did You Hear the Rain? sort en octobre 2013, suivi par Cassy O en mars 2014.",105,"fr:George_Ezra","c:9/95/Boardmasters2022_%2851_of_246%29_%2852301476769%29_%28CROPPED%29.jpg"],["Q15044005",507,"chanteur","Vance Joy","C","James Keogh, plus connu sous le nom de scène de Vance Joy, est un auteur-compositeur-interprète australien. Il est principalement connu pour sa chanson Riptide (2013).",114,"fr:Vance_Joy","c:6/6e/ACL_Music_Festival_2015_Overview_%28Austin%2C_Texas%2C_2015-10%29_%2822116140030%29_%28cropped%29.jpg"],["Q61983346",508,"chanteur","Dermot Kennedy","C","Dermot Kennedy, né le 13 décembre 1991 à Rathcoole, est un chanteur, parolier, guitariste et compositeur irlandais. En octobre 2019, il sort son premier album studio Without Fear. L'album se classe numéro 1 des ventes au Royaume-Uni.",115,"fr:Dermot_Kennedy","https://thumb.wikimedia.org/wikipedia/commons/thumb/2/29/Dermot_Kennedy_7.jpg/3840px-Dermot_Kennedy_7.jpg"],["Q64577327",509,"chanteur","Cavetown","C","Robin Daniel Skinner, dit Cavetown , est un auteur-compositeur-interprète et musicien britannique.",null,"fr:Cavetown","c:d/d3/Cavetown_talking_with_Rimmers_Music_%282%29_%28cropped%29.png"],["Q52433533",510,"chanteur","Clairo","C","Claire Cottrill, dite Clairo, est une autrice-compositrice-interprète américaine née le 18 août 1998 à Atlanta en Géorgie. Elle a grandi à Carlisle dans le Massachusetts.",113,"fr:Clairo","c:b/b2/Clairo_-_Sabrina_Carpenter_at_BST_Hyde_Park_-_20250706_-_100_%28cropped%29.jpg"],["Q24883319",511,"chanteur","Phoebe Bridgers","E","Phoebe Bridgers, née le 17 août 1994 à Los Angeles, est autrice-compositrice-interprète américaine originaire de Los Angeles, en Californie. Après un premier album, Stranger in The Alps, remarqué par la critique spécialisée, elle gagne en notoriété avec son second disque, Punisher, acclamé par la presse et le public, qui lui vaut plusieurs nominations aux Grammy Awards.",116,"fr:Phoebe_Bridgers","c:3/3c/BoygeniusKingstonEarly240823_%2829_of_45%29_%2853138924957%29_Cropped.jpg"],["Q319502",512,"chanteur","Sufjan Stevens","C","Sufjan Stevens, né le 1er juillet 1975 à Détroit (Michigan), est un auteur-compositeur-interprète américain.",null,"fr:Sufjan_Stevens","c:8/84/Sufjan_Stevens_playing_banjo_edit1_%28cropped%29.jpg"],["Q65214814",513,"chanteur","Conan Gray","C","Conan Gray, né le 5 décembre 1998 à Lemon Grove, dans le Comté de San Diego en Californie aux États-Unis, est un chanteur d'indie pop et auteur-compositeur-interprète américain d’origines japonaise et irlandaise.",112,"fr:Conan_Gray","https://thumb.wikimedia.org/wikipedia/commons/thumb/c/ce/Conan_Gray_at_2026_Montreux_Jazz_Festival-08.jpg/3840px-Conan_Gray_at_2026_Montreux_Jazz_Festival-08.jpg"],["Q53832755",514,"chanteur","Noah Kahan","R","Noah Kahan, né le 1er janvier 1997 à Strafford, est un auteur-compositeur-interprète américain de pop-folk signé chez Republic Records depuis 2017.",112,"fr:Noah_Kahan","c:e/ea/Noah_Kahan_at_Glastonbury_Festival_2025_04_%28cropped%29_%28again%29.jpg"],["Q26834366",515,"chanteur","Rag'n'Bone Man","C","Rag'n'Bone Man, de son vrai nom Rory Charles Graham, est un chanteur britannique de soul, de blues et de hip-hop, né le 29 janvier 1985 à Uckfield en Angleterre. Il est connu pour sa voix baryton.",116,"fr:Rag%27n%27Bone_Man","https://thumb.wikimedia.org/wikipedia/commons/thumb/9/98/Festival_du_Bout_du_Monde_2018_-_Rag%27n%27Bone_Man_-_042.jpg/3840px-Festival_du_Bout_du_Monde_2018_-_Rag%27n%27Bone_Man_-_042.jpg"],["Q717626",516,"chanteur","James Arthur","C","James Arthur, né le 2 mars 1988 à Middlesbrough (Angleterre), est un chanteur et artiste britannique ayant remporté la 9e saison du télécrochet britannique The X Factor, le 9 décembre 2012.",115,"fr:James_Arthur","c:c/cb/James_Arthur-6645_%28cropped%29.jpg"],["Q30122205",517,"chanteur","Ruelle","C","Ruelle est une auteure-compositrice-interprète américaine, née en 1985. Son style : synth-pop.",null,"en:Ruelle_%28singer%29",""],["Q270935",518,"chanteur","Chris Cornell","R","Christopher Cornell, dit Chris Cornell, né Christopher Boyle le 20 juillet 1964 à Seattle dans l’État de Washington, et mort le 18 mai 2017 à Détroit dans le Michigan, est un auteur-compositeur-interprète américain.",116,"fr:Chris_Cornell","c:5/58/ChrisCornellTIFFSept2011.jpg"],["Q194187",519,"chanteur","Sade Adu","PC","Helen Adu, dite Sade Adu ou simplement Sade, est une chanteuse, auteure-compositrice-interprète, réalisatrice et arrangeuse de musique soul et jazz nigériane naturalisée britannique, née le 16 janvier 1959 à Ibadan (Nigéria). Elle fait partie depuis 1983 du groupe Sade qui porte son nom.",112,"fr:Sade_Adu","c:9/94/Sade_Adu_1.jpg"],["Q229375",520,"chanteur","Linda Ronstadt","R","Linda Ronstadt, née le 15 juillet 1946 à Tucson, dans l'Arizona, est une chanteuse américaine dont la carrière débute vers la fin des années 1960. Elle annonce sa retraite en 2011.",110,"fr:Linda_Ronstadt","c:5/50/LindaRonstadtPerforming.jpg"],["Q152929",521,"chanteur","Meat Loaf","PC","Meat Loaf, de son nom Michael Lee Aday, né Marvin Lee Aday le 27 septembre 1947 à Dallas (Texas) et mort le 20 janvier 2022 à Nashville (Tennessee), est un chanteur et un acteur américain.",110,"fr:Meat_Loaf","c:e/e7/Meat_Loaf.jpg"],["Q215215",522,"chanteur","John Mayer (guitariste)","PC","John Clayton Mayer, né le 16 octobre 1977 à Bridgeport dans le Connecticut, est un auteur-compositeur-interprète, guitariste et producteur américain.",113,"fr:John_Mayer_%28guitariste%29","c:8/89/JohnMayerin2019.jpg"],["Q215026",523,"chanteur","Debbie Harry","PC","Deborah Ann Harry, dite Debbie Harry, née sous le nom Angela Trimble le 1er juillet 1945 à Miami, est une chanteuse et actrice américaine. Elle est surtout célèbre en tant que chanteuse du groupe rock new-yorkais Blondie.",115,"fr:Debbie_Harry","c:3/32/Debbie_Harry_in_1977.jpg"],["Q200586",524,"chanteur","Sheryl Crow","PC","Sheryl Crow, née le 11 février 1962 à Kennett (Missouri), est une chanteuse et guitariste américaine.",null,"fr:Sheryl_Crow","c:b/b2/Katherine_Clark_and_Sheryl_Crow_Grammy_Event_%28cropped%29.jpg"],["Q202937",525,"chanteur","Stevie Ray Vaughan","C","Stevie Ray Vaughan [ˈstivi reɪ vɔn] est un auteur-compositeur-interprète et guitariste de blues américain, né le 3 octobre 1954 à Dallas (Texas) et mort le 27 août 1990 à East Troy (Wisconsin) dans un accident d'hélicoptère. Malgré une courte carrière parfois peu connue du grand public, il est largement considéré comme l'un des plus brillants guitaristes de l'histoire de la musique et comme l'un des pionniers du renouveau du blues dans les années 1980.",114,"fr:Stevie_Ray_Vaughan","c:4/43/Stevie_Ray_Vaughan_Live_1983.jpg"],["Q819016",526,"chanteur","Carlos Santana","C","Carlos Santana Barragán, simplement dit Carlos Santana voire seulement Santana, est un guitariste, compositeur et chanteur mexicano-américain, né le 20 juillet 1947 à Autlán de Navarro, dans l'État de Jalisco, au Mexique. Il est le leader du groupe Santana.",113,"fr:Carlos_Santana","c:2/2f/Santana_1984.jpg"],["Q299073",527,"chanteur","Nusrat Fateh Ali Khan","C","Nuṣrat Fateḥ ′Ali Khān, né le 13 octobre 1948 à Lyallpur, dans le Pendjab pakistanais, et mort le 16 août 1997 à Londres, est un musicien pakistanais, maître de qawwalî, un style musical soufi.",112,"fr:Nusrat_Fateh_Ali_Khan","c:9/93/Nusrat_Fateh_Ali_Khan.jpg"],["Q221310",528,"chanteur","Anggun","C","Anggun Cipta Sasmi, dite Anggun, est une chanteuse indonésienne naturalisée française, née le 29 avril 1974 à Jakarta.",null,"fr:Anggun","https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7d/Anggun_at_Sundance_Film_Festival_2026-1.jpg/3840px-Anggun_at_Sundance_Film_Festival_2026-1.jpg"],["Q487882",529,"chanteur","Demis Roussos","C","Artémios Ventoúris Roússos, dit Demis Roussos, est un musicien et chanteur grec, né le 15 juin 1946 à Alexandrie (Égypte) et mort le 25 janvier 2015 à Athènes (Grèce).",112,"fr:Demis_Roussos","c:3/32/Demis_Roussos_in_Baku_2-cropped.jpg"],["Q190231",530,"chanteur","Adam Lambert","C","Adam Lambert est un chanteur et acteur américain, né le 29 janvier 1982 à Indianapolis (Indiana). Découvert lors de la huitième saison de l'émission American Idol, son premier album studio, For Your Entertainment, sorti en 2009, se place en 3e position du US Billboard 200 avec 198 000 exemplaires vendus dès la première semaine. Puis il enchaîne avec une grande tournée mondiale, le Glam Nation Tour.",115,"fr:Adam_Lambert","c:9/9d/Queen_And_Adam_Lambert_-_The_O2_-_Tuesday_12th_December_2017_QueenO2121217-14_%2825093782907%29_Cropped.jpg"],["Q185147",531,"chanteur","Gary Moore","C","Gary Moore, né Robert William Gary Moore le 4 avril 1952 à Belfast et mort le 6 février 2011 à Estepona, en Espagne, est un guitariste et chanteur natif d'Irlande du Nord.",116,"fr:Gary_Moore","c:e/e4/Gary-Moore-at-Pite-Havsbad.jpg"],["Q18814",532,"chanteur","Jessie J","C","Jessica Ellen Cornish, plus connue sous le pseudonyme de Jessie J, née le 27 mars 1988 dans le district de Redbridge, à Londres, est une autrice-compositrice-interprète britannique. Elle commence sa carrière à l'âge de 11 ans avec un rôle dans la comédie musicale Whistle Down the Wind, elle étudie à la BRIT School avant de signer avec Gut Records et de parvenir à un accord avec Sony/ATV Music Publishing ; elle est aujourd'hui en contrat avec le label Lava Records.",106,"fr:Jessie_J","c:7/71/Jessie_J_performing_live_at_The_Peppermint_Club_05_%28cropped%29.jpg"],["Q19810390",533,"chanteur","Charlie Puth","C","Charlie Puth, est un chanteur, musicien, compositeur et producteur américain né le 2 décembre 1991 à Rumson.",null,"fr:Charlie_Puth","c:8/86/Charlie_Puth_2017_%28cropped%29.jpg"],["Q34584",534,"chanteur","Anastacia","C","Anastacia Lyn Newkirk, dite Anastacia, née le 17 septembre 1968 à Chicago (Illinois), est une chanteuse américaine de pop, soul et d'influence rock.",114,"fr:Anastacia","c:a/a8/Anastacia%2C_Women%27s_World_Awards_2009_a.jpg"],["Q262314",535,"chanteur","Chris Rea","C","Christopher Anton Rea, dit Chris Rea, né le 4 mars 1951 à Middlesbrough et mort le 22 décembre 2025 à Londres, est un auteur-compositeur-interprète, guitariste de soft rock et blues rock britannique d'origine italienne et irlandaise.",114,"fr:Chris_Rea","c:2/2d/Chris_Rea_01_AB.jpg"],["Q56755505",536,"chanteur","Ava Max","C","Amanda Ava Koçi, née, le 16 février 1994 à Milwaukee dans l'État du Wisconsin aux États-Unis, dite Ava Max, est une auteure-compositrice-interprète américaine.",115,"fr:Ava_Max","c:e/ed/Ava_Max_%40_HOB_San_Diego_6_19_2023_%2853352357483%29.jpg"],["Q487125",537,"chanteur","Viktor Tsoï","C","Viktor Robertovitch Tsoï, est un chanteur soviétique de rock, actif dans les années 1980, et leader du groupe Kino. Bien que Viktor Tsoï ne soit pas un vrai pionnier du rock, il donne une couleur particulière à ce genre, un côté crépusculaire[style trop lyrique ou dithyrambique]. Il rencontre la journaliste et critique de cinéma Natalia Razlogova (ru), avec laquelle il vit en couple au no 116b, rue Profsoyouznaïa à Moscou.",115,"fr:Viktor_Tso%C3%AF","c:4/4e/Victor_Tsoi_1986_cropped.jpg"],["Q193744",538,"chanteur","Tori Amos","C","Tori Amos, est une auteure-compositrice-interprète, chanteuse, pianiste, arrangeuse et productrice américaine, née le 22 août 1963 à Newton en Caroline du Nord.",114,"fr:Tori_Amos","c:7/7b/Tori_Amos_12_01_2017_-35_%2825495988058%29.jpg"],["Q159099",539,"chanteur","Nina Hagen","C","Catharina Hagen, dite Nina Hagen, née le 11 mars 1955 à Berlin-Est en RDA, est une chanteuse, auteur-compositrice-interprète et actrice est-allemande puis allemande. Elle est connue pour ses performances vocales particulières et devient célèbre dans la musique punk et new wave des années 1970 et 1980.",93,"fr:Nina_Hagen","https://thumb.wikimedia.org/wikipedia/commons/thumb/1/16/Nina_Hagen_%286266181937%29.jpg/3840px-Nina_Hagen_%286266181937%29.jpg"],["Q40580",540,"chanteur","Lisa Gerrard","C","Lisa Gerrard /ˈliːsə ˈd͡ʒerəd/, née le 12 avril 1961 à Melbourne, est une musicienne, chanteuse et compositrice australienne qui est devenue célèbre en faisant partie du groupe Dead Can Dance. Elle est connue pour sa technique vocale unique, influencée depuis son enfance par le multiculturalisme de Melbourne. Elle est une contralto dramatique qui possède une étendue vocale variant sur trois octaves.",111,"fr:Lisa_Gerrard","c:c/c2/Lisa_Gerard_2012.jpg"],["Q463945",541,"chanteur","Teresa Teng","C","Teresa Teng, née le 29 janvier 1953 dans le comté de Yunlin (Taïwan) et morte le 8 mai 1995 à Chiang Mai (Thaïlande), est une chanteuse taïwanaise très populaire en Extrême-Orient, aux États-Unis et en Europe dans les communautés chinoises.",104,"fr:Teresa_Teng","c:c/c0/%E5%8F%B0%E4%B8%AD%E7%B8%A3%E5%A5%BD%E4%BA%BA%E5%A5%BD%E4%BA%8B%E4%BB%A3%E8%A1%A8%E8%81%AF%E8%AA%BC%E6%9C%83_%E9%84%A7%E9%BA%97%E5%90%9B.jpg"],["Q774155",542,"chanteur","Nancy Ajram","C","Nancy Ajram ,née le 16 mai 1983 à Beyrouth est une chanteuse et personnalité de la télévision libanaise, surnommée par Spotify la « reine de la pop arabe ». Avec le soutien de son père, elle commence à se produire dès son enfance et apparaît dans plusieurs émissions de télévision au cours de ses premières années. À l’âge de 15 ans, Ajram signe un contrat d’enregistrement avec EMI et sort son premier album studio, Mihtagalak (1998).",114,"fr:Nancy_Ajram","c:b/b0/Nancy_Ajram_signing_ceremony.jpg"],["Q15902",543,"chanteur","Amy Macdonald","C","Amy Macdonald est une auteure-compositrice-interprète, chanteuse et multi-instrumentiste écossaise, née le 25 août 1987 à Glasgow en Écosse. Elle connaît un important succès pour des titres tels que This Is the Life ou Mr Rock & Roll.",114,"fr:Amy_Macdonald","c:0/07/Amy_MacDonald-9578.jpg"],["Q483376",544,"chanteur","Loreen","C","Loreen, de son vrai nom Lorine Zineb Nora Talhaoui, née le 16 octobre 1983 à Stockholm (Suède), est une auteure-compositrice-interprète suédo-marocaine.",103,"fr:Loreen","c:1/17/Loreen_-_Melodifestivalen_2023%2C_Malm%C3%B6_118_%28cropped%29.jpg"],["Q113581",545,"chanteur","Conchita Wurst","C","Conchita Wurst est un personnage incarné depuis 2011 par son créateur, le chanteur et drag queen autrichien Thomas Neuwirth, né le 6 novembre 1988 à Gmunden, en Autriche.",114,"fr:Conchita_Wurst","c:8/8b/Conchita_Wurst_at_Berlinale_2026.jpg"],["Q43189",546,"chanteur","Juanes","C","Juan Esteban Aristizábal Vásquez, alias Juanes, est un auteur-compositeur-interprète et guitariste colombien, né le 9 août 1972 à Medellín, en Colombie. Son pseudonyme vient de son premier prénom et des deux premières lettres de son second prénom. Dans sa musique, Juanes combine des rythmes colombiens comme la cumbia et le vallenato avec le rock et la pop. Entre 1987 et 1999, Juanes est membre du groupe de heavy metal Ekhymosis.",115,"fr:Juanes","https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b9/JuanesUnpluggedtour.JPG/1920px-JuanesUnpluggedtour.JPG"],["Q1362169",547,"chanteur","Agnez Mo","PC","Agnes Monica Muljoto, dite Agnez Mo, née le 1er juillet 1986 à Jakarta en Indonésie, est une auteure-compositrice-interprète et actrice indonésienne-américaine.",92,"fr:Agnez_Mo","c:b/b6/Agnez_Mo_2019_by_Glenn_Francis.jpg"],["Q237324",548,"chanteur","Lisa Marie Presley","E","Lisa Marie Presley, née le 1er février 1968 à Memphis (Tennessee) et morte le 12 janvier 2023 à Los Angeles (Californie), est une chanteuse de rock et auteure-compositrice-interprète américaine.",107,"fr:Lisa_Marie_Presley","c:4/4b/Lisa_Marie_Presley_%28cropped%29.jpg"],["Q19329827",549,"chanteur","Aurora (chanteuse)","C","Aurora Aksnes, plus connue sous le mononyme d'Aurora, née le 15 juin 1996 à Stavanger (Norvège), est une auteure-compositrice-interprète, musicienne et productrice norvégienne.",104,"fr:Aurora_%28chanteuse%29","c:6/65/AURORA%2C_Ravnedalen_Live_festival%2C_Kristiansand%2C_Norway_%2853867200364%29_%28cropped%29.jpg"],["Q186329",550,"chanteur","Mika","C","Michael Penniman Jr., dit Mika, est un auteur-compositeur-interprète, musicien et acteur libano-américano-britannique, né le 18 août 1983 à Beyrouth (Liban).",88,"fr:Mika_%28chanteur%29","c:7/70/Mika_Venoge_Festival_2025.jpg"],["Q28864768",551,"chanteur","Sigrid","C","Sigrid Solbakk Raabe, dite Sigrid, est une chanteuse norvégienne. Elle atteint un succès international en 2017 avec son single Don't Kill My Vibe, puis avec Strangers. En janvier 2018, elle a remporté le prix The Sound of 2018 de la BBC.",115,"fr:Sigrid_%28chanteuse%29","c:b/b9/Sigrid_Over_Oslo_2018_%28201832%29.jpg"]]]);